const Step1InviteCode = ({ data, onChange, onNext, onBack }) => {
  const [validating, setValidating] = useState(false);
  const [error, setError] = useState("");
  const [validated, setValidated] = useState(false);

  const handleNext = async () => {
    const code = data.inviteCode.trim().toUpperCase();
    if (code.length < 9) { setError("Please enter your full invite code."); return; }
    setValidating(true);
    setError("");
    const result = await validateInviteCode(code);
    setValidating(false);
    if (!result) {
      setError("That code isn't valid or has been deactivated. Check your invite and try again, or contact your building manager.");
      return;
    }
    // Store building info from the code for use throughout onboarding
    onChange({
      inviteCode: code,
      buildingId: result.buildingId,
      buildingName: result.buildingName,
      unitNumber: result.unitNumber,
      buildingEquipment: result.buildingEquipment || [],
    });
    setValidated(true);
    setTimeout(onNext, 400); // brief pause so checkmark is visible
  };

  return (
    <OnboardingShell step={1} onBack={onBack} hideBack={true}>
      <QuestionHeader
        label="Enter your invite code"
        subtitle="Your building provided this code when AmenityFit was set up. Check your welcome packet or ask at the front desk."
      />
      <div style={{ position: "relative", marginBottom: 12 }}>
        <input
          type="text"
          value={data.inviteCode}
          onChange={(e) => {
            const normalized = e.target.value
              .toUpperCase()
              .replace(/[–—]/g, "-")
              .replace(/[^A-Z0-9-]/g, "")
              .slice(0, 9);
            onChange({ inviteCode: normalized });
            setError("");
            setValidated(false);
          }}
          placeholder="AF-XXXXXX"
          maxLength={9}
          autoCorrect="off"
          autoCapitalize="characters"
          autoComplete="off"
          spellCheck={false}
          style={{
            width: "100%", padding: "18px 20px",
            borderRadius: 16,
            border: `1.5px solid ${validated ? COLORS.success : error ? "#FF4D4D" : data.inviteCode ? COLORS.accent : COLORS.border}`,
            background: COLORS.card, color: COLORS.white,
            fontSize: 28, fontWeight: 800, letterSpacing: 6, textAlign: "center",
            outline: "none", fontFamily: "'Inter', sans-serif",
            boxSizing: "border-box" as const, transition: "all 0.2s ease",
          }}
        />
        {validated && (
          <div style={{ position: "absolute", right: 16, top: "50%", transform: "translateY(-50%)" }}>
            <Check size={22} color={COLORS.success} strokeWidth={3} />
          </div>
        )}
      </div>

      {error && (
        <div style={{ background: "#FF4D4D15", border: "1px solid #FF4D4D40", borderRadius: 12, padding: "12px 16px", marginBottom: 16 }}>
          <p style={{ color: "#FF6B6B", fontSize: 13, margin: 0, lineHeight: 1.5 }}>{error}</p>
        </div>
      )}

      <p style={{ color: COLORS.textSecondary, fontSize: 13, textAlign: "center", margin: "0 0 32px", lineHeight: 1.5 }}>
        Don't have a code? Contact your building manager or the front desk.
      </p>

      <ContinueButton
        onPress={handleNext}
        disabled={data.inviteCode.trim().length < 9 || validating}
        label={validating ? "Checking code..." : "Continue"}
      />
    </OnboardingShell>
  );
};

const Step1bHomeBuilding = ({ data, onChange, onNext, onBack }) => {
  const selected = data.isHomeBuilding;
  const options = [
    {
      value: true,
      label: "Yes, this is my building",
      sub: "I live here and this is my primary gym.",
      icon: "🏠",
    },
    {
      value: false,
      label: "No, I'm visiting",
      sub: "I'm a guest or staying temporarily.",
      icon: "🧳",
    },
  ];
  return (
    <OnboardingShell step={2} onBack={onBack}>
      <QuestionHeader
        label="Is this your home building?"
        subtitle="This helps us know where to track your progress and keep your stats accurate."
      />
      <div style={{ display: "flex", flexDirection: "column", gap: 12, marginBottom: 32 }}>
        {options.map((opt) => {
          const isSelected = selected === opt.value;
          return (
            <button
              key={String(opt.value)}
              onClick={() => onChange({ isHomeBuilding: opt.value })}
              style={{
                width: "100%", padding: "20px", borderRadius: 16, cursor: "pointer",
                border: `1.5px solid ${isSelected ? COLORS.accent : COLORS.border}`,
                background: isSelected ? `${COLORS.accent}15` : COLORS.card,
                display: "flex", alignItems: "center", gap: 16,
                transition: "all 0.2s ease", textAlign: "left",
              }}
            >
              <span style={{ fontSize: 28, flexShrink: 0 }}>{opt.icon}</span>
              <div style={{ flex: 1 }}>
                <p style={{
                  color: isSelected ? COLORS.white : COLORS.white,
                  fontSize: 16, fontWeight: 700, margin: "0 0 4px",
                }}>{opt.label}</p>
                <p style={{
                  color: COLORS.textSecondary, fontSize: 13, margin: 0, lineHeight: 1.4,
                }}>{opt.sub}</p>
              </div>
              <div style={{
                width: 22, height: 22, borderRadius: 99, flexShrink: 0,
                border: `2px solid ${isSelected ? COLORS.accent : COLORS.border}`,
                background: isSelected ? COLORS.accent : "transparent",
                display: "flex", alignItems: "center", justifyContent: "center",
                transition: "all 0.2s ease",
              }}>
                {isSelected && <div style={{ width: 8, height: 8, borderRadius: 99, background: COLORS.white }} />}
              </div>
            </button>
          );
        })}
      </div>
      {data.isHomeBuilding === false && (
        <div style={{
          background: `${COLORS.accent}10`, border: `1px solid ${COLORS.accent}30`,
          borderRadius: 14, padding: "14px 16px", marginBottom: 24,
        }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: 0, lineHeight: 1.5 }}>
            No problem. You'll work out in <span style={{ color: COLORS.white, fontWeight: 700 }}>guest mode</span> here. Your progress and streak travel with you everywhere. When you get home, enter your building's code to set your home base.
          </p>
        </div>
      )}
      <ContinueButton onPress={onNext} disabled={selected === undefined || selected === null} />
    </OnboardingShell>
  );
};

const Step2Name = ({ data, onChange, onNext, onBack }) => {
  // Requires an actual first and last name, not just any 2+ characters -
  // without this, "Al" or a single nickname passed the old check, leaving
  // the resident database full of names too incomplete to search or
  // identify someone by later (e.g. matching a support email to their
  // account, or telling two residents apart in the same unit).
  const trimmedName = data.name.trim();
  const hasFullName = trimmedName.split(/\s+/).filter(Boolean).length >= 2;
  return (
    <OnboardingShell step={3} onBack={onBack}>
      <QuestionHeader label="What's your full name?" subtitle="We'll use this to personalize your experience." />
      <input type="text" value={data.name} onChange={(e) => { const raw = e.target.value; const formatted = raw.split(" ").map((w: string) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(" "); onChange({ name: formatted }); }} placeholder="First and last name"
        style={{ width: "100%", padding: "18px 20px", borderRadius: 16, border: `1.5px solid ${data.name ? COLORS.accent : COLORS.border}`, background: COLORS.card, color: COLORS.white, fontSize: 20, fontWeight: 600, outline: "none", fontFamily: "'Inter', sans-serif", boxSizing: "border-box", marginBottom: 8, transition: "all 0.2s ease" }}
      />
      <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: "0 0 24px", minHeight: 18 }}>
        {trimmedName.length > 0 && !hasFullName ? "Please enter both your first and last name." : ""}
      </p>
      <ContinueButton onPress={onNext} disabled={!hasFullName} />
    </OnboardingShell>
  );
};

const Step2bCreateAccount = ({ data, onChange, onNext, onBack }) => {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");

  const emailValid = data.email && data.email.includes("@");
  const passwordValid = data.password && data.password.length >= 6;
  const passwordsMatch = data.password === confirmPassword;
  const canContinue = emailValid && passwordValid && passwordsMatch;

  const inputStyle = (hasVal: boolean) => ({
    width: "100%", padding: "18px 20px", borderRadius: 16,
    border: `1.5px solid ${hasVal ? COLORS.accent : COLORS.border}`,
    background: COLORS.card, color: COLORS.white, fontSize: 16,
    fontWeight: 500, outline: "none", fontFamily: "'Inter', sans-serif",
    boxSizing: "border-box" as const, marginBottom: 16, transition: "all 0.2s ease",
  });

  const handleNext = () => {
    if (!emailValid) { setError("Please enter a valid email address."); return; }
    if (!passwordValid) { setError("Password must be at least 6 characters."); return; }
    if (!passwordsMatch) { setError("Passwords don't match."); return; }
    setError("");
    onNext();
  };

  return (
    <OnboardingShell step={4} onBack={onBack}>
      <QuestionHeader label={`Create your account, ${data.name.split(" ")[0]}.`} subtitle="You'll use this to sign in across devices." />
      <input
        type="email"
        value={data.email || ""}
        onChange={(e) => { onChange({ email: e.target.value }); setError(""); }}
        placeholder="Email address"
        style={inputStyle(!!data.email)}
      />
      <div style={{ position: "relative", marginBottom: 16 }}>
        <input
          type={showPassword ? "text" : "password"}
          value={data.password || ""}
          onChange={(e) => { onChange({ password: e.target.value }); setError(""); }}
          placeholder="Create a password (6+ characters)"
          style={{ ...inputStyle(!!data.password), marginBottom: 0, paddingRight: 48 }}
        />
        <button onClick={() => setShowPassword(s => !s)} style={{ position: "absolute", right: 14, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", padding: 4, display: "flex" }}>
          {showPassword ? <EyeOff size={18} color={COLORS.textSecondary} /> : <Eye size={18} color={COLORS.textSecondary} />}
        </button>
      </div>
      <div style={{ position: "relative", marginBottom: 16 }}>
        <input
          type={showConfirmPassword ? "text" : "password"}
          value={confirmPassword}
          onChange={(e) => { setConfirmPassword(e.target.value); setError(""); }}
          placeholder="Confirm password"
          style={{ ...inputStyle(!!confirmPassword), marginBottom: 0, paddingRight: 48 }}
        />
        <button onClick={() => setShowConfirmPassword(s => !s)} style={{ position: "absolute", right: 14, top: "50%", transform: "translateY(-50%)", background: "none", border: "none", cursor: "pointer", padding: 4, display: "flex" }}>
          {showConfirmPassword ? <EyeOff size={18} color={COLORS.textSecondary} /> : <Eye size={18} color={COLORS.textSecondary} />}
        </button>
      </div>
      <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: "-8px 0 16px", lineHeight: 1.5 }}>
        Minimum 6 characters.
      </p>
      {error && (
        <div style={{ background: "#FF4D4D15", border: "1px solid #FF4D4D40", borderRadius: 12, padding: "12px 16px", marginBottom: 16 }}>
          <p style={{ color: "#FF6B6B", fontSize: 13, margin: 0 }}>⚠️ {error}</p>
        </div>
      )}
      <ContinueButton onPress={handleNext} disabled={!canContinue} />
    </OnboardingShell>
  );
};

