const Step5HeightWeight = ({ data, onChange, onNext, onBack }) => {
  const [unit, setUnit] = useState("imperial");

  const heightFt = Number(data.heightFt);
  const weightLbs = Number(data.weightLbs);
  const heightCm = Number(data.heightCm);
  const showHeightWarning = (unit === "imperial" && data.heightFt !== "" && (heightFt < 4 || heightFt > 7)) ||
    (unit === "metric" && data.heightCm !== "" && (heightCm < 122 || heightCm > 213));
  const showWeightWarning = (unit === "imperial" && !!data.weightLbs && (weightLbs < 80 || weightLbs > 500)) ||
    (unit === "metric" && !!data.weightKg && (Number(data.weightKg) < 36 || Number(data.weightKg) > 227));

  const inputStyle = (hasVal) => ({
    width: "100%", padding: "16px 14px", borderRadius: 14,
    border: `1.5px solid ${hasVal ? COLORS.accent : COLORS.border}`,
    background: COLORS.card, color: COLORS.white, fontSize: 28,
    fontWeight: 800, textAlign: "center" as const, outline: "none",
    fontFamily: "'Inter', sans-serif", boxSizing: "border-box" as const,
    transition: "all 0.2s ease",
  });
  return (
    <OnboardingShell step={6} onBack={onBack}>
      <QuestionHeader label="Height & weight" subtitle="Used to set your baseline and track body composition over time." />
      <div style={{ display: "flex", background: COLORS.card, borderRadius: 12, padding: 4, marginBottom: 24, border: `1px solid ${COLORS.border}` }}>
        {["imperial", "metric"].map((u) => (
          <button key={u} onClick={() => { setUnit(u); if (u === "imperial") { onChange({ heightCm: "", weightKg: "" }); } else { onChange({ heightFt: "", heightIn: "", weightLbs: "" }); } }} style={{ flex: 1, padding: "10px", borderRadius: 9, border: "none", background: unit === u ? COLORS.primary : "transparent", color: unit === u ? COLORS.white : COLORS.textSecondary, fontSize: 14, fontWeight: 700, cursor: "pointer", transition: "all 0.2s ease" }}>
            {u === "imperial" ? "ft / lbs" : "cm / kg"}
          </button>
        ))}
      </div>
      {unit === "imperial" ? (
        <>
          <div style={{ display: "flex", gap: 12, marginBottom: 16 }}>
            <div style={{ flex: 1 }}>
              <input type="number" placeholder="5" value={data.heightFt || ""} onChange={(e) => { const v = Number(e.target.value); if (v <= 8 || e.target.value === "") onChange({ heightFt: e.target.value }); }} style={inputStyle(!!data.heightFt)} />
              <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "6px 0 0" }}>ft</p>
            </div>
            <div style={{ flex: 1 }}>
              <input type="number" placeholder="10" value={data.heightIn || ""} onChange={(e) => { const ft = Number(data.heightFt); const v = Number(e.target.value); if ((ft < 8 && v >= 0 && v <= 11) || e.target.value === "") onChange({ heightIn: e.target.value }); }} style={inputStyle(!!data.heightIn)} />
              <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "6px 0 0" }}>in</p>
            </div>
          </div>
          <input type="number" placeholder="175" min={100} value={data.weightLbs || ""} onChange={(e) => onChange({ weightLbs: e.target.value })} onBlur={(e) => { const v = Number(e.target.value); if (v < 100) onChange({ weightLbs: "100" }); if (v > 500) onChange({ weightLbs: "500" }); }} style={inputStyle(!!data.weightLbs)} />
          <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "6px 0 24px" }}>lbs</p>
        </>
      ) : (
        <>
          <input type="number" placeholder="178" value={data.heightCm || ""} onChange={(e) => { const v = Number(e.target.value); if (v <= 226) onChange({ heightCm: e.target.value }); }} style={inputStyle(!!data.heightCm)} />
          <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "6px 0 16px" }}>cm</p>
          <input type="number" placeholder="80" min={45} value={data.weightKg || ""} onChange={(e) => onChange({ weightKg: e.target.value })} onBlur={(e) => { const v = Number(e.target.value); if (v < 45) onChange({ weightKg: "45" }); if (v > 227) onChange({ weightKg: "227" }); }} style={inputStyle(!!data.weightKg)} />
          <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "6px 0 24px" }}>kg</p>
        </>
      )}
      {showHeightWarning && (
        <div style={{ background: "#FF6B3515", border: "1px solid #FF6B3550", borderRadius: 12, padding: "12px 16px", marginBottom: 12 }}>
          <p style={{ color: "#FF8C5A", fontSize: 13, margin: 0, lineHeight: 1.5 }}>
            ⚠️ Double check your height. This looks unusual. If it's correct, no worries, just continue.
          </p>
        </div>
      )}
      {showWeightWarning && (
        <div style={{ background: "#FF6B3515", border: "1px solid #FF6B3550", borderRadius: 12, padding: "12px 16px", marginBottom: 12 }}>
          <p style={{ color: "#FF8C5A", fontSize: 13, margin: 0, lineHeight: 1.5 }}>
            ⚠️ Double check your weight. This looks unusual. If it's correct, no worries, just continue.
          </p>
        </div>
      )}
      <ContinueButton onPress={onNext} disabled={unit === "imperial" ? !data.heightFt || !data.weightLbs || Number(data.weightLbs) < 100 || Number(data.weightLbs) > 500 : !data.heightCm || !data.weightKg || Number(data.weightKg) < 45 || Number(data.weightKg) > 227} />
    </OnboardingShell>
  );
};

