const getProgramMotivationalName = (programKey: string): string => {
  if (!programKey || typeof programKey !== "string") return "";
  const cleanKey = programKey.replace("month6-", "");
  return PROGRAM_NAME_MAP[cleanKey] || "";
};

const getEvolvedProgramName = (programKey: string): string => {
  return getProgramMotivationalName(programKey) || "Winner's Delight";
};

const getMasteryBadge = (cycleNumber: number) => {
  if (cycleNumber >= 15) return { label: "Platinum", icon: "crown", color: "#FFFFFF", bg: "rgba(255,255,255,0.1)", border: "rgba(255,255,255,0.5)" };
  if (cycleNumber >= 10) return { label: "Gold", icon: "trophy", color: "#FFD166", bg: "rgba(255,209,102,0.15)", border: "rgba(255,209,102,0.45)" };
  if (cycleNumber >= 6) return { label: "Silver", icon: "shield", color: "#A8B8CC", bg: "rgba(140,160,185,0.15)", border: "rgba(140,160,185,0.45)" };
  if (cycleNumber >= 3) return { label: "Bronze", icon: "flame", color: "#E8A87C", bg: "rgba(232,168,124,0.15)", border: "rgba(232,168,124,0.4)" };
  return null;
};

const getMasteryBadgeExplainer = (badgeLabel: string): string => {
  const thresholds: Record<string, number> = { Bronze: 3, Silver: 6, Gold: 10, Platinum: 15 };
  const n = thresholds[badgeLabel] || 3;
  return `${badgeLabel}. Earned by completing ${n} full program cycles. This tracks consistency, not skill level.`;
};

const WelcomeBackScreen = ({ profile, onContinue }) => {
  const rawUserName = (profile.name || "Athlete").split(" ")[0];
  const userName = rawUserName.charAt(0).toUpperCase() + rawUserName.slice(1).toLowerCase();
  const daysGone = profile.lastSessionDate
    ? Math.floor((new Date().getTime() - new Date(profile.lastSessionDate).getTime()) / (1000 * 60 * 60 * 24))
    : 0;
  const reEntryTarget = Math.round((profile.frequency || 3) * 2);
  return (
    <div style={{ height: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "flex-start", padding: "calc(72px + env(safe-area-inset-top, 0px)) 28px 36px", overflow: "hidden", textAlign: "center" }}>
      <div style={{ width: 80, height: 80, borderRadius: 99, marginBottom: 20, background: `${COLORS.primary}20`, border: `2px solid ${COLORS.primary}50`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 0 40px ${COLORS.primary}25` }}>
        <Flame size={36} color={COLORS.primary} strokeWidth={1.5} />
      </div>
      <div style={{ display: "inline-flex", alignItems: "center", background: `${COLORS.accent}20`, borderRadius: 99, padding: "4px 14px", marginBottom: 16 }}>
        <span style={{ color: COLORS.accent, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase" }}>Welcome Back</span>
      </div>
      <h1 style={{ color: COLORS.white, fontSize: 32, fontWeight: 900, margin: "0 0 10px", letterSpacing: -0.8, lineHeight: 1.1 }}>{userName}</h1>
      <p style={{ color: COLORS.textSecondary, fontSize: 15, margin: "0 0 8px", lineHeight: 1.6 }}>
        You've been away for {daysGone} day{daysGone !== 1 ? "s" : ""}. No judgment. We've adjusted your program to ease you back in.
      </p>
      <p style={{ color: COLORS.textSecondary, fontSize: 14, margin: "0 0 24px", lineHeight: 1.6 }}>
        Hit {reEntryTarget} sessions over the next two weeks and you'll reclaim your full programming.
      </p>
      <div style={{ width: "100%", background: COLORS.card, borderRadius: 16, padding: "16px 20px", border: `1px solid ${COLORS.border}`, marginBottom: 24, textAlign: "left" }}>
        <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.4, textTransform: "uppercase", margin: "0 0 10px" }}>Re-Entry Progress</p>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
          <span style={{ color: COLORS.white, fontSize: 13, fontWeight: 600 }}>0 of {reEntryTarget} sessions</span>
          <span style={{ color: COLORS.textSecondary, fontSize: 13 }}>14 days</span>
        </div>
        <div style={{ width: "100%", height: 6, background: COLORS.border, borderRadius: 99 }}>
          <div style={{ width: "0%", height: 6, background: COLORS.primary, borderRadius: 99 }} />
        </div>
      </div>
      <button onClick={onContinue} style={{ width: "100%", padding: "18px", borderRadius: 16, border: "none", background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`, color: COLORS.white, fontSize: 16, fontWeight: 800, cursor: "pointer", letterSpacing: 0.3, boxShadow: `0 8px 24px ${COLORS.primary}50` }}>
        Let's Get Back To It
      </button>
    </div>
  );
};

const getGreeting = () => {
  const h = new Date().getHours();
  if (h < 12) return "Good morning";
  if (h < 17) return "Good afternoon";
  return "Good evening";
};

const TodayWorkoutCard = ({ type = "upper-body", sessionLength = 45, experience = "Intermediate", programDay = 1, programWeek = 1, workoutDoneToday = false, isInProgress = false, onStartWorkout = () => {}, onCompleteRestDay = () => {}, exerciseCount = 0, dayFocus = "", groups = [] as any[], profile = null as any }) => {
  // Preload today's exercise thumbnails as soon as this card renders (i.e. the
  // moment the Dashboard loads), well before the user actually taps into the
  // workout screen. Without this, the exercise-list screen's <img> tags only
  // start fetching from vumbnail.com the instant that screen renders, which is
  // exactly why a brief flash/placeholder was visible on first open. Creating
  // an in-memory Image() and setting its src causes the browser to fetch and
  // cache that exact URL immediately, so by the time the exercise list
  // actually renders, the same URL is already in the browser's cache and
  // displays instantly instead of triggering a fresh network fetch.
  React.useEffect(() => {
    if (!groups || groups.length === 0) return;
    groups.forEach((g: any) => {
      (g.exercises || []).forEach((ex: any) => {
        const thumbUrl = getThumbnailUrl(ex.id, programDay);
        if (thumbUrl) {
          const preloadImg = new window.Image();
          preloadImg.src = thumbUrl;
        }
      });
    });

    // Also preload swap-candidate thumbnails for every exercise in today's
    // workout, not just each exercise's own thumbnail. Previously these
    // only started fetching the moment someone actually opened the swap
    // picker mid-workout, causing a visible loading delay right when
    // someone's mid-set and wants a fast decision. Running this here means
    // it's already warm in the browser's cache before Begin Workout is even
    // tapped, matching the exact same preload pattern already used above
    // for each exercise's own thumbnail. Uses each exercise's own id as a
    // stand-in "original" for candidate scoring purposes, which is close
    // enough for a background warm-up - the live modal computes the exact
    // real original at swap time, this just needs to be a good approximation
    // of what's likely to be shown.
    if (profile?.programKey && PROGRAMS[profile.programKey]) {
      const fullProgramExerciseIds: string[] = [];
      PROGRAMS[profile.programKey].days?.forEach((day: any) => {
        if (!day.isRest && day.groups) {
          day.groups.forEach((dg: any) => {
            dg.exercises?.forEach((e: any) => {
              if (e.id && !fullProgramExerciseIds.includes(e.id)) fullProgramExerciseIds.push(e.id);
            });
          });
        }
      });
      groups.forEach((g: any) => {
        const groupIds = (g.exercises || []).map((e: any) => e.id);
        (g.exercises || []).forEach((ex: any) => {
          const otherIds = groupIds.filter((id: string) => id !== ex.id);
          const candidates = getSwapCandidates(
            ex.id, ex.id, otherIds, fullProgramExerciseIds,
            profile?.equipmentPreference || "gym-and-bands",
            profile?.injuries || "none",
            profile?.effectiveLevel || profile?.experience || "beginner",
            profile?.buildingEquipment || [],
            (parseInt(String(profile?.age)) || 30) >= 65
          );
          candidates.forEach((c: any) => {
            const thumbUrl = getThumbnailUrl(c.id, programDay);
            if (thumbUrl) {
              const preloadImg = new window.Image();
              preloadImg.src = thumbUrl;
            }
          });
        });
      });
    }
  }, [groups, programDay, profile]);
  return (
  <div style={{
    borderRadius: 24, overflow: "hidden", marginBottom: 20, position: "relative",
    boxShadow: `0 16px 48px ${COLORS.primary}55`, cursor: "pointer",
    minHeight: 260,
  }}>
    {/* Hero image */}
    <div style={{
      position: "absolute", inset: 0,
      backgroundImage: `url(${getWorkoutImage(type, programDay)})`,
      backgroundSize: "cover", backgroundPosition: "center top",
    }} />
    {/* Dark gradient overlay — makes any photo work with dark theme */}
    <div style={{
      position: "absolute", inset: 0,
      background: "linear-gradient(160deg, rgba(10,20,50,0.82) 0%, rgba(15,37,87,0.75) 50%, rgba(30,95,190,0.65) 100%)",
    }} />

    <div style={{ padding: "24px 24px 20px", position: "relative" }}>
      {/* Badge */}
      <div style={{ display: "inline-flex", alignItems: "center", background: "rgba(255,255,255,0.15)", borderRadius: 99, padding: "4px 12px", marginBottom: 16 }}>
        <div style={{ width: 6, height: 6, borderRadius: 99, background: COLORS.success, marginRight: 7 }} />
        <span style={{ color: COLORS.white, fontSize: 11, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase" }}>Week {programWeek} · Day {programDay} of 30</span>
      </div>

      <h2 style={{ color: COLORS.white, fontSize: 28, fontWeight: 900, margin: "0 0 4px", letterSpacing: -0.8, lineHeight: 1.1 }}>{
        // Prefer the same real-exercise-based title used on the detail and
        // weekly-view screens (deriveWorkoutTitle) whenever actual groups data
        // is available, instead of this generic category label. Previously
        // this always used the generic label, which is why this card could
        // read "Cardio" while the detail view for the same day correctly
        // showed something like "Legs & Abs & Cardio" - the hardcoded fallback
        // below is kept only for rest days or the rare case groups isn't populated yet.
        type !== "rest" && groups && groups.length > 0
          ? deriveWorkoutTitle(groups, type, dayFocus)
          : (type === "upper-body" ? "Upper Body" : type === "lower-body" ? "Lower Body" : type === "core" ? "Core" : type === "push" ? "Push Day" : type === "pull" ? "Pull Day" : type === "cardio" ? "Cardio" : type === "rest" ? "Rest Day" : "Full Body")
      }</h2>
      <p style={{ color: "rgba(255,255,255,0.7)", fontSize: 14, margin: "0 0 20px" }}>{dayFocus || (type === "upper-body" ? "Chest, Back & Shoulders" : type === "lower-body" ? "Quads, Hamstrings & Glutes" : type === "core" ? "Abs, Obliques & Lower Back" : type === "push" ? "Chest, Shoulders & Triceps" : type === "pull" ? "Back, Biceps & Rear Delts" : type === "cardio" ? "Cardio" : type === "rest" ? "Active Recovery & Mobility" : "Full Body Compound Movements")}</p>

      {/* Meta row */}
      <div style={{ display: "flex", gap: 20, marginBottom: 24 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Clock size={14} color="rgba(255,255,255,0.7)" />
          <span style={{ color: "rgba(255,255,255,0.7)", fontSize: 13, fontWeight: 500 }}>{sessionLength} min</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Dumbbell size={14} color="rgba(255,255,255,0.7)" />
          <span style={{ color: "rgba(255,255,255,0.7)", fontSize: 13, fontWeight: 500 }}>{exerciseCount} exercises</span>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
          <Zap size={14} color="rgba(255,255,255,0.7)" />
          <span style={{ color: "rgba(255,255,255,0.7)", fontSize: 13, fontWeight: 500 }}>{experience}</span>
        </div>
      </div>

      {/* Start button — hidden on rest days */}
      {type !== "rest" && (
        <button style={{
          width: "100%", padding: "16px", borderRadius: 14, border: "none",
          background: workoutDoneToday ? "rgba(46,204,113,0.9)" : COLORS.white,
          color: workoutDoneToday ? COLORS.white : COLORS.primary,
          fontSize: 16, fontWeight: 800, cursor: workoutDoneToday ? "default" : "pointer",
          display: "flex", alignItems: "center", justifyContent: "center", gap: 10,
          boxShadow: "0 4px 20px rgba(0,0,0,0.2)",
        }} onClick={workoutDoneToday ? undefined : onStartWorkout}>
          {workoutDoneToday ? (
            <><Check size={18} color={COLORS.white} strokeWidth={3} /> Today's Workout Complete</>
          ) : isInProgress ? (
            <><ChevronRight size={18} color={COLORS.primary} /> Continue Workout</>
          ) : (
            <><ChevronRight size={18} color={COLORS.primary} /> Start Today's Workout</>
          )}
        </button>
      )}
      {type === "rest" && (
        <button
          onClick={workoutDoneToday ? undefined : onCompleteRestDay}
          style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: workoutDoneToday ? "rgba(46,204,113,0.9)" : COLORS.white, color: workoutDoneToday ? COLORS.white : COLORS.primary, fontSize: 16, fontWeight: 800, cursor: workoutDoneToday ? "default" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 10, boxShadow: "0 4px 20px rgba(0,0,0,0.2)", fontFamily: "'Inter', sans-serif" }}
        >
          {workoutDoneToday ? (<><Check size={18} color={COLORS.white} strokeWidth={3} /> Rest Day Complete</>) : "Rest & Recover Today"}
        </button>
      )}
    </div>
  </div>
  );
};

const StatCard = ({ label, value, sub, icon: Icon, color }) => (
  <div style={{ flex: 1, background: COLORS.card, borderRadius: 18, padding: "16px 14px", border: `1px solid ${COLORS.border}`, display: "flex", flexDirection: "column" }}>
    <div style={{ width: 36, height: 36, borderRadius: 10, background: `${color}20`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 10 }}>
      <Icon size={18} color={color} strokeWidth={1.8} />
    </div>
    <p style={{ color: COLORS.white, fontSize: 24, fontWeight: 800, margin: "0 0 2px", letterSpacing: -0.5 }}>{value}</p>
    <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: "0 0 2px", fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8 }}>{label}</p>
    {sub && <p style={{ color: color, fontSize: 11, margin: 0, fontWeight: 600 }}>{sub}</p>}
  </div>
);

const PlaylistCard = () => (
  <div
    onClick={() => {
      const spotifyWebUrl = "https://open.spotify.com/playlist/1vZ4MOciV3rtd3a67JWKv2";
      // Inside the native iOS wrapper, skip the custom-scheme-then-timeout
      // trick entirely. A raw spotify:// URL set via window.location.href can
      // get silently blocked by the WebView before it ever reaches the native
      // navigation handler - this was found to be the actual reason the
      // button did nothing on iOS, even after the earlier window.open() fix.
      // A plain https:// link, on the other hand, is something iOS's own
      // Universal Links system already knows how to route correctly -
      // straight to the Spotify app if it's installed, or Safari if not -
      // without needing to reimplement that detection ourselves.
      const hasRNWebView = !!(window as any).ReactNativeWebView;
      if (hasRNWebView) {
        window.location.href = spotifyWebUrl;
        return;
      }
      window.location.href = "spotify://playlist/1vZ4MOciV3rtd3a67JWKv2";
      setTimeout(() => {
        if (!document.hidden) {
          // On mobile with the Spotify app installed, document.hidden becomes true above and
          // this never runs — the native app correctly takes over and switching back to
          // AmenityFit works naturally. This fallback only fires when there's no app to hand
          // off to (desktop web, or mobile without Spotify installed), so it opens a new tab
          // instead of navigating the current one away — otherwise the AmenityFit session
          // would be replaced entirely with no way back.
          window.open(spotifyWebUrl, "_blank");
        }
      }, 1500);
    }}
    style={{
      background: `linear-gradient(135deg, #1a1a2e 0%, #0d2137 100%)`,
      borderRadius: 20, padding: "18px 20px", marginBottom: 20,
      border: `1px solid #1DB95430`, cursor: "pointer",
      display: "flex", alignItems: "center", gap: 16,
      boxShadow: "0 8px 32px rgba(29,185,84,0.12)",
    }}
  >
    <div style={{
      width: 52, height: 52, borderRadius: 14, flexShrink: 0,
      background: "linear-gradient(135deg, #1DB954, #17a348)",
      display: "flex", alignItems: "center", justifyContent: "center",
      boxShadow: "0 4px 16px rgba(29,185,84,0.4)",
    }}>
      <Music size={24} color="#ffffff" strokeWidth={2.5} />
    </div>
    <div style={{ flex: 1 }}>
      <p style={{ color: COLORS.white, fontWeight: 700, fontSize: 15, margin: "0 0 3px" }}>Fitmakesenz Afrobeats Mix</p>
      <p style={{ color: "#1DB954", fontSize: 12, margin: "0 0 2px", fontWeight: 600 }}>Trainer's Playlist</p>
      <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>Curated by Senz · Open in Spotify</p>
    </div>
    <ChevronRight size={18} color={COLORS.textSecondary} />
  </div>
);

