// Cycles: all of Senz's quotes first, then generated variants, then loops back.
// Each user gets a stable, unique starting offset derived from their own uid, so two
// people at the same session count almost never see the same quote on the same day,
// while any single user still sees a consistent, non-repeating, deterministic sequence.
const getUserQuoteOffset = (uid: string): number => {
  if (!uid) return 0;
  let hash = 0;
  for (let i = 0; i < uid.length; i++) {
    hash = (hash * 31 + uid.charCodeAt(i)) | 0;
  }
  return Math.abs(hash);
};

const getMotivationalMessage = (sessionCount: number, uid: string = ""): string => {
  const primary = SENZ_QUOTES;
  const secondary = GENERATED_QUOTES;
  const total = primary.length + secondary.length;
  if (total === 0) return "You showed up. That's what separates you.";
  const offset = getUserQuoteOffset(uid);
  const idx = (sessionCount + offset) % total;
  if (idx < primary.length) return primary[idx];
  return secondary[idx - primary.length];
};

// ─── Session Complete Screen ───────────────────────────────────────────────────
const SessionCompleteScreen = ({ totalSets, timeSeconds, userName, sessionCount = 0, uid = "", onDone, weightsLogged = {}, liftPRs = {}, dayTitle = "", sessionId = "" }) => {
  const mins = Math.floor(timeSeconds / 60);
  const secs = timeSeconds % 60;
  const message = getMotivationalMessage(sessionCount, uid);
  const [showShareCard, setShowShareCard] = useState(false);
  const [showStickerMode, setShowStickerMode] = useState(false);
  // Weightlifting RPE - identical concept to cardio's, self-reported
  // effort 1-10, saved directly onto this lifting session's own doc.
  const [sessionRpe, setSessionRpe] = useState<number | null>(null);
  const [rpeSaveStatus, setRpeSaveStatus] = useState<"idle" | "saving" | "saved" | "error">("idle");
  // Real gap this closes: a lift+cardio combined day (e.g. legs+cardio)
  // saves as two separate workoutSessions documents, and the cardio one
  // is tagged with linkedWorkoutId pointing back to this lifting
  // session's id - but until now nothing ever queried for it, so this
  // screen only ever showed the lifting half even on a combined day.
  // undefined = still checking, null = checked and none found, object =
  // the real linked cardio session data - three distinct states, not
  // collapsed into one, so the loading moment never gets mistaken for
  // "definitely no cardio today."
  const [linkedCardioSession, setLinkedCardioSession] = useState<any>(undefined);
  useEffect(() => {
    if (!sessionId) { setLinkedCardioSession(null); return; }
    let cancelled = false;
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "workoutSessions"), where("linkedWorkoutId", "==", sessionId)));
        if (cancelled) return;
        if (!snap.empty) {
          setLinkedCardioSession({ id: snap.docs[0].id, ...snap.docs[0].data() });
        } else {
          setLinkedCardioSession(null);
        }
      } catch (e) {
        console.error("Failed to check for linked cardio session:", e);
        if (!cancelled) setLinkedCardioSession(null);
      }
    })();
    return () => { cancelled = true; };
  }, [sessionId]);

  // Same retry pattern as cardio's saveSessionNotes: a couple of
  // automatic retries so a transient blip resolves invisibly, and a
  // genuine "error" state, distinct from "idle", if every retry fails.
  const saveRpe = async (value: number) => {
    if (!sessionId) return;
    setRpeSaveStatus("saving");
    const maxAttempts = 2;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      try {
        await setDoc(doc(db, "workoutSessions", sessionId), { rpe: value }, { merge: true });
        setRpeSaveStatus("saved");
        return;
      } catch (e) {
        console.error("saveRpe error:", e);
        if (attempt < maxAttempts - 1) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
        }
      }
    }
    setRpeSaveStatus("error");
  };

  // Weight-only PRs (see checkAndUpdateLiftPRs) - real exercise names via
  // EXERCISES_DATA, not raw ids, and only ever the weight actually logged -
  // no volume/reps claim, per the honest scope this was built to.
  const prExercises = Object.entries(liftPRs)
    .filter(([, v]: any) => v?.isPR)
    .map(([exerciseId, v]: any) => ({ name: (EXERCISES_DATA as any)[exerciseId]?.name || exerciseId, weight: v.weight }));

  // Real completion of the linked-cardio read: a combined lift+cardio day
  // now presents as one earned, unified story instead of two disconnected
  // moments. Derived only once linkedCardioSession has actually resolved
  // (not undefined - the "still checking" state), so this never flashes a
  // half-built cardio section before the query returns.
  const cardioMeta = linkedCardioSession ? ACTIVITY_TYPES.find((a) => a.key === linkedCardioSession.type) : null;
  // Same 0.05km floor as the trusted live/save-time guard.
  const cardioHasDistance = (linkedCardioSession?.distanceMeters || 0) >= 50;
  const cardioCourtType = cardioMeta?.courtType;
  // Real MapLibre+Esri snapshot, replacing the old Mapbox static image -
  // called unconditionally regardless of whether linkedCardioSession
  // exists, which the hook already treats as "no route, return null."
  const cardioRouteSnapshotUrl = useRouteMapSnapshot(
    (linkedCardioSession && !cardioCourtType) ? linkedCardioSession.route : null,
    640, 360
  );
  const cardioOutlineSnapshotUrl = useRouteMapSnapshot(
    (linkedCardioSession && !cardioCourtType) ? linkedCardioSession.route : null,
    640, 360, undefined, true
  );
  const cardioLocationLabel = (linkedCardioSession && !cardioCourtType)
    ? getRouteLocationLabel(linkedCardioSession.route)
    : null;
  const cardioMapUrl = linkedCardioSession
    ? (cardioCourtType
        ? buildCourtIllustrationUrl(cardioCourtType, COLORS.accent)
        : cardioRouteSnapshotUrl)
    : null;
  const cardioPaceLabel = cardioHasDistance && linkedCardioSession?.avgPaceSecondsPerKm
    ? `${Math.floor(linkedCardioSession.avgPaceSecondsPerKm / 60)}:${String(Math.round(linkedCardioSession.avgPaceSecondsPerKm % 60)).padStart(2, "0")}/km`
    : null;
  const cardioDisplayName = linkedCardioSession?.customActivityName || cardioMeta?.label || linkedCardioSession?.type;
  const cardioMinutes = linkedCardioSession ? Math.round((linkedCardioSession.durationSeconds || 0) / 60) : 0;

  const shareStats = [
    { label: "Sets Done", value: String(totalSets) },
    { label: "Time", value: `${mins}m ${secs}s` },
    ...prExercises.map((p) => ({ label: p.name, value: `${p.weight} lbs`, isPR: true })),
    ...(sessionRpe !== null ? [{ label: "RPE", value: `${sessionRpe}/10` }] : []),
    // Appended only when a real linked cardio session exists, so the
    // exported sticker/share card tells the whole day's story in one
    // image rather than only the lifting half.
    ...(linkedCardioSession ? [
      ...(cardioHasDistance ? [{ label: `${cardioDisplayName} Distance`, value: `${(linkedCardioSession.distanceMeters / 1000).toFixed(2)} km` }] : []),
      { label: `${cardioDisplayName} Time`, value: `${cardioMinutes} min` },
      ...(cardioPaceLabel ? [{ label: `${cardioDisplayName} Pace`, value: cardioPaceLabel }] : []),
    ] : []),
  ];

  return (
    <div style={{ minHeight: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "32px 32px", textAlign: "center" }}>
      {/* Green check */}
      <div style={{ width: 100, height: 100, borderRadius: 99, background: `${COLORS.success}20`, display: "flex", alignItems: "center", justifyContent: "center", marginBottom: 24, boxShadow: `0 0 60px ${COLORS.success}30` }}>
        <Check size={48} color={COLORS.success} strokeWidth={2.5} />
      </div>

      <h1 style={{ color: COLORS.white, fontSize: 32, fontWeight: 900, margin: "0 0 8px", letterSpacing: -1 }}>
        Session Complete
      </h1>
      {userName && (
        <p style={{ color: COLORS.accent, fontSize: 16, fontWeight: 700, margin: "0 0 8px" }}>
          Well done, {userName}.
        </p>
      )}
      <p style={{ color: COLORS.textSecondary, fontSize: 15, margin: "0 0 24px", lineHeight: 1.6, maxWidth: 300 }}>
        {message}
      </p>

      {prExercises.length > 0 && (
        <div style={{ width: "100%", marginBottom: 20, padding: "14px 16px", borderRadius: 16, background: `${COLORS.accent}18`, border: `1px solid ${COLORS.accent}60` }}>
          <p style={{ color: COLORS.accent, fontSize: 11, fontWeight: 900, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 8px" }}>New PR{prExercises.length > 1 ? "s" : ""}</p>
          {prExercises.map((p, i) => (
            <p key={i} style={{ color: COLORS.white, fontSize: 14, fontWeight: 700, margin: i > 0 ? "4px 0 0" : 0 }}>{p.name} — {p.weight} lbs</p>
          ))}
        </div>
      )}

      {/* Stats */}
      <div style={{ display: "flex", gap: 16, marginBottom: 24, width: "100%" }}>
        <div style={{ flex: 1, background: COLORS.card, borderRadius: 18, padding: "18px 14px", border: `1px solid ${COLORS.border}` }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8, margin: "0 0 6px" }}>Sets Done</p>
          <p style={{ color: COLORS.white, fontSize: 28, fontWeight: 900, margin: 0 }}>{totalSets}</p>
        </div>
        <div style={{ flex: 1, background: COLORS.card, borderRadius: 18, padding: "18px 14px", border: `1px solid ${COLORS.border}` }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8, margin: "0 0 6px" }}>Time</p>
          <p style={{ color: COLORS.white, fontSize: 28, fontWeight: 900, margin: 0 }}>{mins}<span style={{ fontSize: 14, color: COLORS.textSecondary }}>m </span>{secs}<span style={{ fontSize: 14, color: COLORS.textSecondary }}>s</span></p>
        </div>
      </div>

      {/* Real self-reported RPE for weightlifting - same concept and
          scale as cardio's, saved straight onto this session's doc. */}
      <div style={{ width: "100%", marginBottom: 20 }}>
        <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 10px" }}>Effort (RPE)</p>
        <div style={{ display: "flex", gap: 6, marginBottom: 4 }}>
          {Array.from({ length: 10 }, (_, i) => i + 1).map((n) => (
            <button
              key={n}
              onClick={() => {
                const newVal = sessionRpe === n ? null : n;
                setSessionRpe(newVal);
                setRpeSaveStatus("idle");
                if (newVal !== null) saveRpe(newVal);
              }}
              style={{
                flex: 1, aspectRatio: "1", borderRadius: 10, border: `1px solid ${sessionRpe === n ? COLORS.accent : COLORS.border}`,
                background: sessionRpe === n ? `${COLORS.accent}25` : COLORS.card,
                color: sessionRpe === n ? COLORS.accent : COLORS.textSecondary,
                fontSize: 13, fontWeight: 700, cursor: "pointer", padding: 0,
              }}
            >
              {n}
            </button>
          ))}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between" }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 10, margin: 0 }}>Easy</p>
          <p style={{ color: COLORS.textSecondary, fontSize: 10, margin: 0 }}>Max Effort</p>
        </div>
        {rpeSaveStatus === "error" && (
          <p style={{ color: COLORS.danger || "#ff4444", fontSize: 11, margin: "8px 0 0" }}>Couldn't save - tap a number again to retry</p>
        )}
      </div>

      <div style={{ display: "flex", gap: 12, width: "100%", marginBottom: 12 }}>
        <button onClick={() => setShowShareCard(true)} style={{ flex: 1, padding: "16px", borderRadius: 16, border: `1px solid ${COLORS.border}`, background: COLORS.card, color: COLORS.white, fontSize: 15, fontWeight: 700, cursor: "pointer" }}>
          Share
        </button>
        <button onClick={() => setShowStickerMode(true)} style={{ flex: 1, padding: "16px", borderRadius: 16, border: `1px solid ${COLORS.border}`, background: COLORS.card, color: COLORS.white, fontSize: 15, fontWeight: 700, cursor: "pointer" }}>
          Sticker
        </button>
      </div>

      <button onClick={onDone} style={{ width: "100%", padding: "18px", borderRadius: 16, border: "none", background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`, color: COLORS.white, fontSize: 17, fontWeight: 700, cursor: "pointer", boxShadow: `0 8px 30px ${COLORS.primary}40`, letterSpacing: 0.3 }}>
        Back to Dashboard
      </button>

      {showShareCard && (
        <ShareableStatCard
          title={dayTitle || "Workout"}
          subtitle={new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })}
          stats={shareStats}
          // Real gap found tonight: the linked-cardio map was computed
          // (cardioMapUrl) but never actually passed anywhere - a
          // combined lift+cardio day's exported card told the whole
          // day's story in its STATS (already handled above) but never
          // showed the actual route, even though it existed.
          mapUrl={cardioMapUrl}
          outlineMapUrl={cardioOutlineSnapshotUrl}
          locationLabel={cardioLocationLabel}
          onClose={() => setShowShareCard(false)}
        />
      )}

      {showStickerMode && (
        <StickerShareScreen
          title={dayTitle || "Workout"}
          stats={shareStats}
          mapUrl={cardioMapUrl}
          outlineMapUrl={cardioOutlineSnapshotUrl}
          locationLabel={cardioLocationLabel}
          onClose={() => setShowStickerMode(false)}
        />
      )}
    </div>
  );
};

// ─── Workout Flow Controller ───────────────────────────────────────────────────
// ─── Weekly Schedule Logic ────────────────────────────────────────────────────

// Maps a program day number to workout type — reads directly from the actual program data.
// This is the source of truth for what day type/rest status shows in calendar and weekly view.
// No generic patterns — your programs define the structure, this just reads them.
// Real muscle-group label derived from the actual exercises in a day's
// groups, instead of the static "focus" text baked into that day's authored
// data - which can silently drift out of sync with the real content (e.g.
// a day's focus field still saying "& Cardio" long after the cardio block
// was removed from its groups, exactly the kind of stale-copy bug that's
// caused real confusion tonight). getWorkoutTypeForProgramDay already
// computed this correctly for Weekly View and the workout screens - this
// extracts that same logic into a reusable function instead of leaving
// Dashboard and any other consumer to keep reading the raw, driftable field
// independently, which is exactly how they ended up disagreeing.
// Extracted verbatim from WorkoutListScreen's own subtitle computation -
// the actual, confirmed-accurate source of truth for "what does this
// workout really contain," not a second approximation of it. Deliberately
// uses raw muscle names with no collapsing (Quads and Hamstrings stay
// separate, not merged into an umbrella "Legs"), and deliberately excludes
// "Full Body"-tagged exercises from the summary - a single exercise tagged
// generically "Full Body" (e.g. kettlebell swings) doesn't mean the whole
// day is full-body, and including it here was misleading exactly the way
// it looked on Dashboard. Cardio is handled as a trailing "& Cardio" suffix
// rather than a muscle name, matching Review's own display.
// Type classification only ("upper-body" / "lower-body" / "full-body") -
// the actual TITLE text now always comes from deriveWorkoutTitle (defined
// earlier in this file), the one genuinely robust source already proven
// correct on Review - it buckets Quads/Hamstrings/Glutes/Calves into one
// unified "Legs" category and checks category presence, rather than
// picking "whichever two muscles happened to appear first in exercise
// order," which is exactly what caused chat to show "Legs & Calves"
// instead of "Legs & Abs" for the same real workout Review correctly named.
const deriveWorkoutType = (groups: any[]): string => {
  const allMuscles: string[] = [];
  (groups || []).forEach((g: any) => {
    (g.exercises || []).forEach((ex: any) => {
      const m = (EXERCISES_DATA as any)[ex.id]?.muscle;
      if (m && !allMuscles.includes(m)) allMuscles.push(m);
    });
  });
  const hasUpper = allMuscles.some(m => ["Chest","Back","Shoulders","Triceps","Biceps"].includes(m));
  const hasLower = allMuscles.some(m => ["Quads","Hamstrings","Glutes","Calves"].includes(m));
  return hasUpper && hasLower ? "full-body" : hasUpper ? "upper-body" : hasLower ? "lower-body" : "full-body";
};

const deriveWorkoutSubtitle = (groups: any[]): string => {
  const muscles = [...new Set((groups || []).filter((g: any) => g.type !== "cardio").flatMap((g: any) =>
    (g.exercises || []).map((ex: any) => { const d = (EXERCISES_DATA as any)[ex.id]; return d?.muscle || null; }).filter(Boolean)
  ))].filter(m => m !== "Full Body" && m !== "Cardio").slice(0, 5);
  const hasCardio = (groups || []).some((g: any) => g.type === "cardio");
  const parts = muscles.length > 0 ? muscles.join(", ") : "";
  return hasCardio ? (parts ? parts + " & Cardio" : "Cardio") : parts;
};

const getWorkoutTypeForProgramDay = (
  programDay: number,
  frequency: number,
  calendarDayOfWeek?: number,
  programKey?: string,
  generatedDays?: any[]
): { type: string; label: string; focus: string; isRest: boolean } => {
  const restDefault = { type: "rest", label: "Rest Day", focus: "Recovery", isRest: true };

  // Month 6+ — read from generatedDays but override isRest from frequency
  if (programKey?.startsWith("month6-") && generatedDays && generatedDays.length > 0) {
    const restDaysByFrequency: Record<number, number[]> = {
      6: [7], 5: [4, 7], 4: [3, 5, 7], 3: [2, 4, 6, 7], 2: [2, 4, 5, 6, 7],
    };
    const weekRestDays = restDaysByFrequency[frequency] || [7];
    const cycleDay = ((programDay - 1) % 7) + 1;
    const isRestByFrequency = weekRestDays.includes(cycleDay);
    if (isRestByFrequency) return restDefault;
    // Always use ALL generated days that have groups as workout days — ignore isRest flag from data
    const workoutDays = generatedDays.filter((d: any) => d.groups && d.groups.length > 0);
    const workoutDayIndex = Array.from({ length: cycleDay }, (_, j) => j + 1)
      .filter(d => !weekRestDays.includes(d)).length - 1;
    const day = workoutDays[workoutDayIndex % workoutDays.length];
    if (day) {
      return {
        type: day.type || "full-body",
        label: expandDayTitle(day.title || day.focus || "Workout"),
        focus: day.focus || "Workout",
        isRest: false,
        groups: day.groups || [],
        notes: day.notes || [],
      };
    }
  }

  // Any other program with generatedDays (e.g. frequency-adapted via adaptProgramToFrequency,
  // which already bakes in the correct rest days for the chosen frequency) — read directly by
  // day index, using the exact same lookup getProgramDay uses for the real workout screen.
  // Without this, the weekly calendar could show a title or content pulled from the static,
  // un-adapted PROGRAMS entry instead, mismatching what the person actually sees once they
  // open that day.
  if (!programKey?.startsWith("month6-") && generatedDays && generatedDays.length > 0) {
    const idx = (programDay - 1) % generatedDays.length;
    const day = generatedDays[idx];
    if (day) {
      if (day.isRest) {
        return { type: "rest", label: "Rest Day", focus: "Recovery", isRest: true, groups: [] };
      }
      return {
        type: day.type || "full-body",
        label: expandDayTitle(day.title || day.focus || "Workout"),
        focus: day.focus || "Workout",
        isRest: false,
        groups: day.groups || [],
        notes: day.notes || [],
      };
    }
  }

  // If we have a program key, read directly from the program data
  if (programKey && PROGRAMS[programKey]) {
    const program = PROGRAMS[programKey];
    if (program.days && program.days.length > 0) {
      const idx = (programDay - 1) % program.days.length;
      const day = program.days[idx];
      if (day) {
        if (day.isRest) {
          return { type: "rest", label: "Rest Day", focus: "Recovery", isRest: true, groups: [] };
        }
        // Derive title from actual exercise content to avoid mismatch
        const rawGroups = day.groups || [];
        const derivedType = deriveWorkoutType(rawGroups);
        const derivedFocus = deriveWorkoutSubtitle(rawGroups) || day.focus || "Workout";
        const derivedLabel = deriveWorkoutTitle(rawGroups, derivedType, derivedFocus) || expandDayTitle(day.title || day.focus || "Workout");
        return {
          type: derivedType,
          label: derivedLabel,
          focus: derivedFocus,
          isRest: false,
          groups: rawGroups,
          notes: day.notes || [],
        };
      }
    }
  }

  // Fallback: if no program key available, use a simple pattern based on frequency
  // This should rarely trigger — only before a program is assigned
  const dayInWeek = (programDay - 1) % 7;
  const isRest = frequency <= 3
    ? [1, 3, 5, 6].includes(dayInWeek)   // 3x: rest on days 2,4,6,7
    : frequency === 4
    ? [2, 5, 6].includes(dayInWeek)       // 4x: rest on days 3,6,7
    : frequency === 5
    ? [5, 6].includes(dayInWeek)          // 5x: rest on days 6,7
    : [6].includes(dayInWeek);            // 6x: rest on day 7

  return isRest
    ? restDefault
    : { type: "full-body", label: "Workout", focus: "Training", isRest: false };
};

// Returns the 7-day week starting from today, reading day types from actual program data
// Resolves which program day's content is actually in effect for a given
// calendar date, accounting for any active day-swap for the current week.
// Swaps are stored as a date-string -> program-day map, so any number of
// swaps within a week compose correctly on top of each other, and a swap
// automatically stops applying once its date has passed - nothing needs
// active resetting. Everything downstream (getWorkoutTypeForProgramDay,
// getProgramDay, completion tracking, progression) continues to operate
// purely on whatever day number this resolves to, and has no awareness a
// swap ever happened - this is the single shared source every screen that
// shows "what workout happens on this date" reads from, replacing what
// used to be independently computed in three separate places.
const resolveProgramDayForDate = (
  naturalProgramDay: number,
  date: Date,
  dayOverrides?: Record<string, number>
): number => {
  if (!dayOverrides) return naturalProgramDay;
  const dateKey = date.toDateString();
  return dayOverrides[dateKey] ?? naturalProgramDay;
};

const getWeekSchedule = (
  currentProgramDay: number,
  frequency: number,
  completedProgramDays: number[],
  lastSessionDate: string,
  programKey?: string,
  todayOverride?: Date,
  generatedDays?: any[],
  injuries?: string,
  equipmentPreference?: string,
  buildingEquipment?: string[],
  age?: number,
  sessionLength?: number,
  experience?: string,
  dayOverrides?: Record<string, number>
) => {
  const isSenior = (age || 30) >= 65;
  const today = todayOverride || new Date();
  const days = [];
  const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

  for (let i = 0; i < 7; i++) {
    const date = new Date(today);
    date.setDate(today.getDate() + i);
    const naturalProgramDay = currentProgramDay + i;
    const programDay = resolveProgramDayForDate(naturalProgramDay, date, dayOverrides);
    // Pass programKey through so calendar reads from your actual program structure
    const workout = getWorkoutTypeForProgramDay(programDay, frequency, date.getDay(), programKey, generatedDays);
    // Apply filters so weekly titles match actual workout content
    if (workout && !workout.isRest && workout.groups?.length > 0) {
      // Session length must be filtered FIRST, matching the exact order used by the real
      // per-day workout screen — this is what can drop groups entirely (e.g. abs is dropped
      // whenever cardio is present at shorter durations). Without this step here, the weekly
      // list's title could show a group (like "Abs") that never actually appears once the
      // person opens the day, since that drop only happened downstream, not in this title
      // computation.
      const _sess = filterGroupsForSessionLength(workout.groups, sessionLength || 60, experience || "intermediate");
      const _eq = filterExercisesByEquipment(_sess, equipmentPreference || "gym-and-bands", buildingEquipment || []);
      const _vid = filterExercisesByVideo(_eq);
      const _inj = (injuries && injuries !== "none") || isSenior ? filterExercisesByInjury(_vid, injuries || "none", equipmentPreference || "gym-and-bands", buildingEquipment || [], isSenior) : _vid;
      workout.groups = dedupeExercisesInDay(_inj, equipmentPreference || "gym-and-bands", buildingEquipment || []);
    }
    const isToday = date.toLocaleDateString() === today.toLocaleDateString();
    const isPast = i < 0;
    const isFutureDay = i > 0;
    // TODAY's completion status must rely ONLY on the real, unambiguous
    // signal (lastSessionDate matching today) - the same one Dashboard
    // already uses - never on completedProgramDays.includes(programDay).
    // Day-numbers are not unique to a single calendar date: they can and do
    // repeat across a cycle, a program swap, or a recalibration, so "was
    // this day-number ever completed, on any date" is a fundamentally
    // different question than "was today specifically completed" - and
    // answering the wrong one here is exactly what caused Weekly View to
    // show "Today's Workout Complete" while Dashboard correctly showed
    // "Start Today's Workout" for the same real day, at the same moment.
    // Past days keep the looser historical check since that's just a
    // glance-back, not an active "should I start this" decision point.
    const isCompleted = !isFutureDay && (
      isToday
        ? lastSessionDate === today.toDateString()
        : completedProgramDays?.includes(programDay)
    );

    const isRestFinal = (isToday && isCompleted) ? false : workout.isRest;
    days.push({
      date,
      dayName: dayNames[date.getDay()],
      dateNum: date.getDate(),
      monthName: monthNames[date.getMonth()],
      programDay,
      isToday,
      isPast,
      isCompleted,
      ...workout,
      isRest: isRestFinal,
    });
  }
  return days;
};

// ─── Weekly Program View Screen ───────────────────────────────────────────────

const WeeklyProgramView = ({ profile, onBack, onStartWorkout, onCompleteRestDay = () => {}, onReviewWorkout, workoutDoneToday, isInProgress = false, onPreviewWorkout = null as any, initialSelectedDay = null as any, onProfileUpdate = (updates: any) => {} }) => {
  // Swaps two days' worth of content for the current week - guarded twice
  // over: the UI never gives a completed or past day a drag handle in the
  // first place, and this function independently re-checks both days
  // aren't completed or past before writing anything, so a stale click
  // (e.g. a day that got completed in another tab moments earlier) can
  // never slip through. Writes both a real Firestore save and an
  // immediate local profile update, the same paired pattern already used
  // for exercise swaps and workout progress, so a fresh mount elsewhere in
  // the app (Dashboard, the assistant) picks up the change instantly
  // rather than waiting on an async re-fetch.
  const swapDays = async (day1: any, day2: any) => {
    if (day1.isCompleted || day2.isCompleted || day1.isPast || day2.isPast) return;
    const dateKey1 = day1.date.toDateString();
    const dateKey2 = day2.date.toDateString();
    const updatedOverrides = {
      ...(profile?.dayOverrides || {}),
      [dateKey1]: day2.programDay,
      [dateKey2]: day1.programDay,
    };
    if (profile?.uid) {
      await setDoc(doc(db, "users", profile.uid), { dayOverrides: updatedOverrides }, { merge: true });
      // Clears today's saved Fitness Assistant conversation, the same way
      // it would naturally reset at midnight - without this, if someone
      // already asked about "tomorrow" earlier in the day, the assistant
      // would keep agreeing with its own now-stale earlier answer for the
      // rest of the day (chat history persists until the natural daily
      // reset), rather than reflecting the swap that just happened.
      deleteDoc(doc(db, "users", profile.uid, "assistantChat", "today")).catch(() => {});
    }
    onProfileUpdate?.({ dayOverrides: updatedOverrides });
  };

  // Clears every active swap at once, reverting the week back to the
  // program's original, unmoved arrangement. Since every screen (Progress,
  // Program Calendar, both Weekly View lists, the assistant) already reads
  // live from this same dayOverrides field through the shared resolver,
  // clearing it here is enough on its own to update everywhere at once -
  // no separate wiring needed per screen. Also clears today's saved chat,
  // the same way an individual swap does, so the assistant reflects the
  // reset immediately rather than continuing to reference the arrangement
  // that just got undone.
  const resetWeek = async () => {
    if (!profile?.uid) return;
    if (!window.confirm("Reset this week back to your original schedule? Any days you've moved will go back to where they started.")) return;
    await setDoc(doc(db, "users", profile.uid), { dayOverrides: {} }, { merge: true });
    deleteDoc(doc(db, "users", profile.uid, "assistantChat", "today")).catch(() => {});
    onProfileUpdate?.({ dayOverrides: {} });
  };

  // Long-press picks a day up (matching the same timer-based long-press
  // pattern already used in the Fitness Assistant chat), then a single tap
  // on any other eligible day completes the swap - deliberately not
  // continuous drag, since this list also needs to scroll, and reliably
  // telling "wants to scroll" apart from "wants to drag this row" is a
  // genuinely hard gesture problem. Tapping the picked-up day again cancels.
  const [pickedUpDay, setPickedUpDay] = useState<any>(null);
  const pickupTimerRef = React.useRef<any>(null);
  const startPickupTimer = (day: any) => {
    if (day.isCompleted || day.isPast) return;
    pickupTimerRef.current = setTimeout(() => setPickedUpDay(day), 500);
  };
  const cancelPickupTimer = () => {
    if (pickupTimerRef.current) { clearTimeout(pickupTimerRef.current); pickupTimerRef.current = null; }
  };

  const [selectedDay, setSelectedDay] = useState<any>(initialSelectedDay ?? null);
  // Ensure today is always selected on mount if no day was passed in
  React.useEffect(() => {
    if (!initialSelectedDay) {
      // weekDays is computed below; we find today after first render
      setSelectedDay((prev: any) => prev);
    }
  }, []);
  const [dayWeightLog, setDayWeightLog] = useState<Record<string, number | string>>({});
  const [dayWeightNotes, setDayWeightNotes] = useState<Record<string, string>>({});
  const scrollRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const fetchWeightLog = async () => {
      if (!selectedDay?.isCompleted || !profile?.uid) { setDayWeightLog({}); setDayWeightNotes({}); return; }
      try {
        const logDate = (() => {
          const now = new Date();
          const todayLocal = getLocalDateString(now);
          if (selectedDay.isToday) return todayLocal;
          if (selectedDay.date instanceof Date) {
            const d = selectedDay.date;
            const y = d.getFullYear();
            const m = String(d.getMonth() + 1).padStart(2, "0");
            const day = String(d.getDate()).padStart(2, "0");
            return `${y}-${m}-${day}`;
          }
          return getLocalDateString();
        })();
        // Fast-then-verify pattern: show whatever's cached immediately so
        // this doesn't block on a network round-trip, then quietly confirm
        // with a real server read a moment later and correct the display if
        // a just-completed group's weight wasn't reflected in the cached
        // version. This replaces the earlier fix that forced the server read
        // BEFORE showing anything - that fixed the correctness problem but
        // introduced real, sometimes 30+ second waits on a slow connection.
        // This gives both: instant display, and eventual correctness.
        const parseDayLogs = (snap: any): { logs: Record<string, number | string>; notes: Record<string, string> } => {
          const logs: Record<string, number | string> = {};
          const notes: Record<string, string> = {};
          if (snap.docs.length > 0) {
            const data = snap.docs[0].data();
            const weightsLogged = data.weightsLogged || {};
            Object.entries(weightsLogged).forEach(([exId, weight]) => {
              if (typeof weight === "number" && weight > 0) {
                logs[exId] = weight;
              } else if (typeof weight === "string" && weight.trim().length > 0) {
                logs[exId] = weight;
              }
            });
            const weightNotes = data.weightNotes || {};
            Object.entries(weightNotes).forEach(([exId, note]) => {
              if (typeof note === "string" && note.trim().length > 0) notes[exId] = note;
            });
          }
          return { logs, notes };
        };
        // Forces the first read from local cache explicitly - the plain
        // getDocs() default used here previously doesn't reliably guarantee
        // a cache-only read, and could quietly fall through to a real
        // network round trip, which is exactly what caused a visible
        // flicker (briefly empty, then repopulated) every time this screen
        // remounted after navigating away and back.
        try {
          // orderBy(completedAt, desc) added so that if multiple session
          // documents ever share the same date - each new, genuinely
          // different workout now correctly gets its own document instead
          // of merging into one shared per-date doc - this always prefers
          // the most recently completed one instead of an arbitrary,
          // possibly stale earlier one. Safe here specifically because
          // this whole fetch is gated to only run for already-completed
          // days, so every candidate document is guaranteed to have
          // completedAt set (Firestore's orderBy excludes documents
          // missing the ordered field entirely, which would be a problem
          // for a still-in-progress, not-yet-completed document, but that
          // case can't reach this code path).
          const cacheSnap = await getDocsFromCache(query(collection(db, "workoutSessions"), where("uid", "==", profile.uid), where("date", "==", logDate), orderBy("completedAt", "desc")));
          const cacheResult = parseDayLogs(cacheSnap);
          setDayWeightLog(cacheResult.logs);
          setDayWeightNotes(cacheResult.notes);
        } catch {}
        getDocsFromServer(query(collection(db, "workoutSessions"), where("uid", "==", profile.uid), where("date", "==", logDate), orderBy("completedAt", "desc")))
          .then(serverSnap => {
            const serverResult = parseDayLogs(serverSnap);
            setDayWeightLog(serverResult.logs);
            setDayWeightNotes(serverResult.notes);
          })
          .catch(() => {});
      } catch (e) { setDayWeightLog({}); setDayWeightNotes({}); }
    };
    fetchWeightLog();
  }, [selectedDay?.programDay, selectedDay?.isCompleted]);

  // Scroll to selected day card on mount (restores position after preview)
  React.useEffect(() => {
    if (initialSelectedDay && scrollRef.current) {
      setTimeout(() => {
        const card = scrollRef.current?.querySelector('[data-selected-day="true"]');
        if (card) card.scrollIntoView({ behavior: 'auto', block: 'center' });
      }, 50);
    }
  }, []);
  const frequency = profile?.frequency || 4;
  const rawProgramDay = profile?.programDay || 1;
  // After completing a workout today, programDay is already incremented to the next day.
  // For display purposes, the week should start from the day we actually worked out today.
  const workoutWasDoneToday = profile?.lastSessionDate === new Date().toDateString();
  const currentProgramDay = workoutWasDoneToday ? Math.max(rawProgramDay - 1, 1) : rawProgramDay;
  const completedProgramDays = profile?.completedProgramDays || [];
  const lastSessionDate = profile?.lastSessionDate || "";
  const experience = profile?.effectiveLevel || profile?.experience || "beginner";
  const sessionLength = profile?.sessionLength || 45;

  // Reset selected day if frequency changes so stale selections don't persist
  const prevFrequency = React.useRef(frequency);
  React.useEffect(() => {
    if (prevFrequency.current !== frequency) {
      const todayDay = weekDays.find((d: any) => d.isToday);
      setSelectedDay(todayDay ?? null);
      prevFrequency.current = frequency;
    }
  }, [frequency]);

  const todayLocal = React.useMemo(() => new Date(), []);
  const weekDays = getWeekSchedule(currentProgramDay, frequency, completedProgramDays, lastSessionDate, profile?.programKey, todayLocal, profile?.generatedDays, profile?.injuries, profile?.equipmentPreference, profile?.buildingEquipment, parseInt(String(profile?.age)) || 30, profile?.sessionLength || 60, profile?.effectiveLevel || profile?.experience || "intermediate", profile?.dayOverrides);

  const todayDay = weekDays.find((d: any) => d.isToday) ?? null;
  const didAutoSelect = React.useRef(false);
  if (!didAutoSelect.current && !initialSelectedDay && todayDay) {
    didAutoSelect.current = true;
    Promise.resolve().then(() => setSelectedDay(todayDay));
  }

  const snapshotDay = profile?.lastWorkoutSnapshot?.programDay;
  const displayProgramDay = workoutWasDoneToday && snapshotDay ? snapshotDay : currentProgramDay;
  const actualDayData = getProgramDay(profile?.programKey || selectProgram(profile), displayProgramDay, profile?.generatedDays);
  const todayEntryRaw = weekDays[0];
  const todayEntry = actualDayData
    ? { ...todayEntryRaw, label: actualDayData.focus || todayEntryRaw.label, focus: actualDayData.focus || todayEntryRaw.focus, type: actualDayData.type || todayEntryRaw.type, isRest: actualDayData.isRest !== undefined ? actualDayData.isRest : todayEntryRaw.isRest }
    : todayEntryRaw;

  // Per-type background positions so focal points show correctly
  const getBgPosition = (type: string) => {
    if (type === "rest") return "center 55%";
    if (type === "upper-body" || type === "push") return "center 40%";
    if (type === "lower-body") return "center 60%";
    if (type === "pull") return "center 25%";
    if (type === "core") return "center 40%";
    if (type === "cardio") return "center 30%";
    return "center 35%";
  };

  // Preloads every day's hero image the instant this screen mounts, not
  // just the currently selected one - without this, each day's image only
  // started fetching the moment someone actually tapped into it, causing
  // a visible flicker on every day's first view. Since getImageForDay is
  // declared below, this runs after weekDays is available but the effect
  // itself only needs read access to it, so declaration order here is fine.
  React.useEffect(() => {
    weekDays.forEach((day: any) => {
      const url = getImageForDay(day);
      if (url) {
        const preloadImg = new window.Image();
        preloadImg.src = url;
      }
    });
  }, [weekDays]);

  const getImageForDay = (day: any): string => {
    const type = day.isRest ? "rest" : day.type;
    const pool = IMAGE_POOLS[type] || IMAGE_POOLS["full-body"];
    if (type === "rest") {
      // For rest days: use calendar day-of-week as a guaranteed-unique offset
      // within the 8-image pool. Two rest days in the same week (e.g. Sat+Sun)
      // get different images because their day-of-week values differ.
      // Offset by programDay's week number so it rotates week-over-week too.
      const weekNum = Math.floor((day.programDay - 1) / 7);
      const dowIndex = (day.date.getDay() + weekNum * 3) % pool.length;
      return pool[dowIndex];
    }
    // For actual workout days, use the exact same shared function as every
    // other screen (Home dashboard, preview, Progress history) instead of a
    // separate, independently-computed formula. Previously this used its own
    // seed math, which could - and did - land on a completely different image
    // than what the same day showed everywhere else in the app.
    return getWorkoutImage(day.type, day.programDay);
  };

  const expLabel = experience === "beginner" ? "Beginner" : experience === "intermediate" ? "Intermediate" : "Advanced";
  const programMotivationalName = getProgramMotivationalName(profile?.programKey || "");
  const isMonth6Program = profile?.programKey?.startsWith("month6-");
  const weeklySubtitle = (() => {
    const name = isMonth6Program ? getEvolvedProgramName(profile?.programKey || "") : programMotivationalName;
    if (name) return `${name} · ${expLabel} · ${sessionLength} min`;
    return `${expLabel} · ${sessionLength} min`;
  })();

  return (
    <div style={{ height: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column", overflowY: "auto", WebkitOverflowScrolling: "touch" as any }}>

      {/* Header */}
      <div style={{ padding: "calc(48px + env(safe-area-inset-top, 0px)) 24px 20px", background: `linear-gradient(180deg, ${COLORS.primary}20 0%, transparent 100%)` }}>
        <button onClick={onBack} style={{ background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 12, width: 40, height: 40, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", marginBottom: 20 }}>
          <ArrowLeft size={18} color={COLORS.white} />
        </button>
        <h1 style={{ color: COLORS.white, fontSize: 26, fontWeight: 900, margin: "0 0 4px", letterSpacing: -0.5 }}>This Week</h1>
        <p style={{ color: COLORS.textSecondary, fontSize: 14, margin: 0 }}>{weeklySubtitle}</p>
      </div>

      <div style={{ padding: "0 24px 12px" }}>

        {/* Day strip */}
        <style>{`.wk-daystrip::-webkit-scrollbar{display:none}`}</style>
        <div className="wk-daystrip" style={{ display: "flex", gap: 8, marginBottom: 24, overflowX: "auto", paddingBottom: 4, msOverflowStyle: "none", scrollbarWidth: "none" } as any}>
          {weekDays.map((day, i) => (
            <div key={i} onClick={() => {
              setSelectedDay(day);
              // Clicking today's workout tile goes directly to the workout screen
              if (day.isToday && !day.isRest && !day.isCompleted) {
                onStartWorkout();
              }
            }} style={{
              flexShrink: 0, width: 56, borderRadius: 16, padding: "10px 0",
              // Compares actual calendar date, not programDay number - two
              // different days in a week can legitimately share the same
              // programDay (seen with re-entry mode's day-numbering), which
              // was highlighting both at once. Date is unique per day.
              background: (selectedDay?.date instanceof Date && day.date instanceof Date && selectedDay.date.getTime() === day.date.getTime())
                ? `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`
                : COLORS.card,
              border: `1.5px solid ${
                (selectedDay?.date instanceof Date && day.date instanceof Date && selectedDay.date.getTime() === day.date.getTime()) ? "transparent" :
                (!selectedDay && day.isToday) ? COLORS.accent : COLORS.border
              }`,
              cursor: "pointer", textAlign: "center" as const,
              transition: "all 0.15s ease",
            }}>
              <p style={{ color: selectedDay?.programDay === day.programDay ? "rgba(255,255,255,0.7)" : COLORS.textSecondary, fontSize: 10, fontWeight: 700, textTransform: "uppercase" as const, letterSpacing: 0.8, margin: "0 0 4px" }}>{day.dayName}</p>
              <p style={{ color: COLORS.white, fontSize: 16, fontWeight: 900, margin: "0 0 6px" }}>{day.dateNum}</p>
              {day.isCompleted ? (
                <div style={{ width: 18, height: 18, borderRadius: 99, background: COLORS.success, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto" }}>
                  <Check size={10} color="#fff" strokeWidth={3} />
                </div>
              ) : day.isRest ? (
                <span style={{ fontSize: 13, lineHeight: 1 }}>🌙</span>
              ) : (
                <div style={{ width: 8, height: 8, borderRadius: 99, background: COLORS.border, margin: "0 auto 5px" }} />
              )}
            </div>
          ))}
        </div>

        {/* Selected day detail or today by default */}
        {(() => {
          const todayWeekEntry = weekDays.find(d => d.isToday) || todayEntry;
const todayEntry2 = weekDays.find((d: any) => d.isToday) || todayWeekEntry;
          if (!selectedDay && todayEntry2 && selectedDay !== todayEntry2) { setTimeout(() => setSelectedDay(todayEntry2), 0); }
          // Re-resolve by date against the freshly recomputed weekDays array
          // instead of trusting selectedDay's own captured object directly -
          // selectedDay is only set once per tap and never automatically
          // updates its baked-in programDay/groups/label afterward, so a
          // swap (or any other dayOverrides change) would recompute weekDays
          // correctly but the hero card would keep showing the old content
          // until the whole screen remounted. Looking the same date back up
          // in the current array picks up the change immediately instead.
          const viewing = (selectedDay && weekDays.find((d: any) => d.date.toDateString() === selectedDay.date.toDateString())) || todayEntry2;
          const isToday = viewing.isToday;

          return (
            <div style={{ background: COLORS.card, borderRadius: 20, overflow: "hidden", border: `1px solid ${COLORS.border}`, marginBottom: 24 }}>
              {/* Image header — always shown */}
              {(() => {
                const image = getImageForDay(viewing);
                return (
                  <div style={{ position: "relative", height: 220, overflow: "hidden" }}>
                    <div style={{ position: "absolute", inset: 0, backgroundImage: `url(${image})`, backgroundSize: "cover", backgroundPosition: getBgPosition(viewing.type || "rest") }} />
                    <div style={{ position: "absolute", inset: 0, background: "linear-gradient(180deg, rgba(0,0,0,0.2) 0%, rgba(26,26,46,0.95) 100%)" }} />
                    <div style={{ position: "absolute", bottom: 16, left: 20, right: 20 }}>
                      {isToday && (
                        <div style={{ display: "inline-flex", alignItems: "center", background: `${COLORS.accent}30`, borderRadius: 99, padding: "3px 10px", marginBottom: 6, backdropFilter: "blur(4px)" }}>
                          <span style={{ color: COLORS.accent, fontSize: 10, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase" }}>Today · Day {viewing.programDay}</span>
                        </div>
                      )}
                      {!isToday && (
                        <div style={{ display: "inline-flex", alignItems: "center", background: "rgba(255,255,255,0.1)", borderRadius: 99, padding: "3px 10px", marginBottom: 6, backdropFilter: "blur(4px)" }}>
                          <span style={{ color: "rgba(255,255,255,0.7)", fontSize: 10, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase" }}>{viewing.dayName} {viewing.dateNum} {viewing.monthName} · Day {viewing.programDay}</span>
                        </div>
                      )}
                      <h2 style={{ color: COLORS.white, fontSize: 22, fontWeight: 900, margin: 0, letterSpacing: -0.5, textShadow: "0 2px 8px rgba(0,0,0,0.5)" }}>
                        {viewing.isRest ? "Rest Day" : (viewing.groups?.length > 0 ? deriveWorkoutTitle(viewing.groups, viewing.type, viewing.focus) : viewing.label)}
                      </h2>
                    </div>
                  </div>
                );
              })()}

              <div style={{ padding: "16px 20px 20px" }}>
                {viewing.isRest && (
                  <p style={{ color: COLORS.textSecondary, fontSize: 14, margin: "0 0 16px", lineHeight: 1.5 }}>Recovery</p>
                )}

                {!viewing.isRest && (
                  <div style={{ display: "flex", gap: 10, marginBottom: 16 }}>
                    <div style={{ flex: 1, background: COLORS.background, borderRadius: 12, padding: "10px 14px" }}>
                      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase" as const, letterSpacing: 0.8, margin: "0 0 2px" }}>Duration</p>
                      <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 700, margin: 0 }}>{sessionLength} min</p>
                    </div>
                    <div style={{ flex: 1, background: COLORS.background, borderRadius: 12, padding: "10px 14px" }}>
                      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase" as const, letterSpacing: 0.8, margin: "0 0 2px" }}>Level</p>
                      <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 700, margin: 0 }}>{expLabel}</p>
                    </div>
                    <div style={{ flex: 1, background: COLORS.background, borderRadius: 12, padding: "10px 14px" }}>
                      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase" as const, letterSpacing: 0.8, margin: "0 0 2px" }}>Day</p>
                      <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 700, margin: 0 }}>{viewing.programDay} of 30</p>
                    </div>
                  </div>
                )}

                {viewing.isRest && (
                  <div style={{ background: `${COLORS.success}10`, border: `1px solid ${COLORS.success}25`, borderRadius: 12, padding: "12px 16px", marginBottom: 16 }}>
                    <p style={{ color: COLORS.success, fontSize: 13, margin: 0, lineHeight: 1.5 }}>Recovery is part of the program. Use this day to stretch, walk, or just rest. Your next session will be stronger for it.</p>
                  </div>
                )}

                {/* Action button */}
                {isToday && (
                  viewing.isCompleted ? (
                    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                      <div style={{ width: "100%", padding: "14px 16px", borderRadius: 14, background: "rgba(46,204,113,0.15)", border: `1px solid ${COLORS.success}40`, display: "flex", alignItems: "center", justifyContent: "center", gap: 8, boxSizing: "border-box", overflow: "hidden" }}>
                        <Check size={18} color={COLORS.success} strokeWidth={3} />
                        <span style={{ color: COLORS.success, fontSize: 15, fontWeight: 700 }}>Today's Workout Complete</span>
                      </div>
                      {!viewing.isRest && Object.keys(dayWeightLog).length > 0 && (
                        <div style={{ background: COLORS.background, borderRadius: 14, padding: "14px 16px", border: `1px solid ${COLORS.border}` }}>
                          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase", margin: "0 0 10px" }}>Weights Logged</p>
                          {Object.entries(dayWeightLog).map(([exId, weight]) => {
                            const exData = (EXERCISES_DATA as any)[exId];
                            // Kettlebells are conventionally sold and marked
                            // in kg increments universally, regardless of
                            // whether the person selected imperial or
                            // metric units elsewhere - this overrides the
                            // general unit choice specifically for them.
                            const isKettlebellEx = exData?.equipment?.toLowerCase().includes("kettlebell");
                            const weightUnit = isKettlebellEx ? "kg" : (profile?.heightFt ? "lbs" : "kg");
                            const displayValue = typeof weight === "number" ? `${weight} ${weightUnit}` : weight;
                            const noteForEx = dayWeightNotes[exId];
                            return (
                              <div key={exId} style={{ padding: "6px 0", borderBottom: `1px solid ${COLORS.border}` }}>
                                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                  <span style={{ color: COLORS.white, fontSize: 13, fontWeight: 500 }}>{exData?.name || exId}</span>
                                  <span style={{ color: COLORS.accent, fontSize: 13, fontWeight: 700 }}>{displayValue}</span>
                                </div>
                                {noteForEx && (
                                  <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: "4px 0 0", fontStyle: "italic", display: "flex", alignItems: "center", gap: 4 }}>
                                    <StickyNote size={11} color={COLORS.textSecondary} /> {noteForEx}
                                  </p>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      )}
                      <button onClick={onReviewWorkout} style={{ width: "100%", padding: "14px 16px", borderRadius: 14, border: `1px solid ${COLORS.border}`, background: COLORS.background, color: COLORS.white, fontSize: 14, fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}>
                        <ChevronRight size={16} color={COLORS.textSecondary} />
                        <span>Review Today's Exercises</span>
                      </button>
                    </div>
                  ) : viewing.isRest ? (
                    <button
                      onClick={workoutDoneToday ? undefined : onCompleteRestDay}
                      style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: workoutDoneToday ? "rgba(46,204,113,0.9)" : COLORS.white, color: workoutDoneToday ? COLORS.white : COLORS.primary, fontSize: 15, fontWeight: 700, cursor: workoutDoneToday ? "default" : "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 10, fontFamily: "'Inter', sans-serif" }}
                    >
                      {workoutDoneToday ? (<><Check size={16} color={COLORS.white} strokeWidth={3} /> Rest Day Complete</>) : "Rest & Recover Today"}
                    </button>
                  ) : (
                    <button onClick={onStartWorkout} style={{ width: "100%", padding: "16px", borderRadius: 14, border: "none", background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`, color: COLORS.white, fontSize: 15, fontWeight: 700, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 10, boxShadow: `0 8px 24px ${COLORS.primary}40` }}>
                      <ChevronRight size={18} color={COLORS.white} />
                      {isInProgress ? "Continue Workout →" : "Start Today's Workout"}
                    </button>
                  )
                )}

                {!viewing.isRest && !isToday && (
                  <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                  <div style={{ width: "100%", padding: "12px 16px", borderRadius: 14, background: COLORS.background, border: `1px solid ${COLORS.border}`, display: "flex", alignItems: "center", justifyContent: "center", boxSizing: "border-box", overflow: "hidden" }}>
                    <span style={{ color: COLORS.textSecondary, fontSize: 14, fontWeight: 600 }}>
                      {viewing.isCompleted ? "✓ Completed" : `Available ${viewing.dayName}, ${viewing.monthName} ${viewing.dateNum}`}
                    </span>
                  </div>
                  {viewing.isCompleted && !viewing.isRest && Object.keys(dayWeightLog).length > 0 && (
                    <div style={{ background: COLORS.background, borderRadius: 14, padding: "14px 16px", border: `1px solid ${COLORS.border}` }}>
                      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.2, textTransform: "uppercase", margin: "0 0 10px" }}>Weights Logged</p>
                      {Object.entries(dayWeightLog).map(([exId, weight], i) => {
                        const exData = (EXERCISES_DATA as any)[exId];
                        // Same kettlebell override as the "today" card above.
                        const isKettlebellEx = exData?.equipment?.toLowerCase().includes("kettlebell");
                        const weightUnit = isKettlebellEx ? "kg" : (profile?.heightFt ? "lbs" : "kg");
                        const displayValue = typeof weight === "number" ? `${weight} ${weightUnit}` : weight;
                        const noteForEx = dayWeightNotes[exId];
                        return (
                          <div key={exId} style={{ padding: "6px 0", borderBottom: i < 6 ? `1px solid ${COLORS.border}` : "none" }}>
                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                              <span style={{ color: COLORS.white, fontSize: 13, fontWeight: 500 }}>{exData?.name || exId}</span>
                              <span style={{ color: COLORS.accent, fontSize: 13, fontWeight: 700 }}>{displayValue}</span>
                            </div>
                            {noteForEx && (
                              <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: "4px 0 0", fontStyle: "italic", display: "flex", alignItems: "center", gap: 4 }}>
                                <StickyNote size={11} color={COLORS.textSecondary} /> {noteForEx}
                              </p>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                    {!viewing.isCompleted && viewing.groups?.length > 0 && (
                      <button
                        onClick={() => onPreviewWorkout && onPreviewWorkout(viewing)}
                        style={{ width: "100%", padding: "14px 16px", borderRadius: 14, border: `1px solid ${COLORS.primary}40`, background: `${COLORS.primary}15`, color: COLORS.accent, fontSize: 14, fontWeight: 600, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", gap: 8 }}
                      >
                        <span>Preview Exercises</span>
                        <ChevronRight size={16} color={COLORS.accent} />
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        })()}

        {/* One-time hint - shown once ever per resident, dismissible, never
            reappears once dismissed or once they successfully do a swap */}
        {!profile?.hasSeenReorderHint && (
          <div style={{ background: `${COLORS.primary}15`, border: `1px solid ${COLORS.primary}30`, borderRadius: 14, padding: "12px 16px", marginBottom: 16, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
            <p style={{ color: COLORS.white, fontSize: 12, margin: 0, lineHeight: 1.4, flex: 1 }}>New: press and hold any day below to move your workouts and rest days around.</p>
            <button onClick={() => {
              if (profile?.uid) setDoc(doc(db, "users", profile.uid), { hasSeenReorderHint: true }, { merge: true });
              onProfileUpdate?.({ hasSeenReorderHint: true });
            }} style={{ background: "none", border: "none", color: COLORS.accent, fontSize: 12, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>Got it</button>
          </div>
        )}

        {/* Swap-in-progress banner */}
        {pickedUpDay && (
          <div style={{ background: `${COLORS.accent}20`, border: `1px solid ${COLORS.accent}50`, borderRadius: 14, padding: "12px 16px", marginBottom: 16, display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
            <p style={{ color: COLORS.white, fontSize: 13, fontWeight: 600, margin: 0 }}>Tap another day to swap with {pickedUpDay.dayName}</p>
            <button onClick={() => setPickedUpDay(null)} style={{ background: "none", border: "none", color: COLORS.textSecondary, fontSize: 12, fontWeight: 700, cursor: "pointer", flexShrink: 0 }}>Cancel</button>
          </div>
        )}

        {/* Week summary */}
        <div style={{ background: COLORS.card, borderRadius: 18, padding: "16px 20px", border: `1px solid ${COLORS.border}`, marginBottom: 80 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase" as const, margin: 0 }}>Week at a Glance</p>
            {profile?.dayOverrides && Object.keys(profile.dayOverrides).length > 0 && (
              <button onClick={resetWeek} style={{ background: "none", border: "none", color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, cursor: "pointer", textDecoration: "underline" }}>Reset Week</button>
            )}
          </div>
          {weekDays.map((day, i) => {
            const isEligible = !day.isCompleted && !day.isPast;
            const isPickedUp = pickedUpDay && pickedUpDay.date.toDateString() === day.date.toDateString();
            const isDimmedTarget = !!pickedUpDay && !isPickedUp && !isEligible;
            const isSelected = selectedDay?.programDay === day.programDay || (!selectedDay && day.isToday);
            return (
            <div key={i} data-selected-day={isSelected ? "true" : undefined} onClick={() => {
              if (pickedUpDay) {
                if (isPickedUp) { setPickedUpDay(null); return; }
                if (isEligible) { swapDays(pickedUpDay, day); setPickedUpDay(null); }
                return;
              }
              setSelectedDay(day);
              // If it's a future workout day with exercises, open preview directly
              if (!day.isRest && !day.isToday && !day.isCompleted && day.groups?.length > 0 && onPreviewWorkout) {
                onPreviewWorkout(day);
              }
            }}
            onTouchStart={() => startPickupTimer(day)}
            onTouchEnd={cancelPickupTimer}
            onMouseDown={() => startPickupTimer(day)}
            onMouseUp={cancelPickupTimer}
            onMouseLeave={cancelPickupTimer}
            style={{ display: "flex", alignItems: "center", gap: 14, padding: "10px 0", borderBottom: i < 6 ? `1px solid ${COLORS.border}` : "none", cursor: "pointer", background: isPickedUp ? `${COLORS.accent}20` : isSelected ? `${COLORS.primary}12` : "transparent", margin: "0 -20px", padding: i < 6 ? "10px 20px" : "10px 20px 4px", borderRadius: isSelected || isPickedUp ? 10 : 0, opacity: isDimmedTarget ? 0.35 : 1, border: isPickedUp ? `1.5px solid ${COLORS.accent}` : "1.5px solid transparent", transition: "opacity 0.15s ease, background 0.15s ease" }}>
              {isEligible && (
                <span style={{ color: isPickedUp ? COLORS.accent : COLORS.textSecondary, fontSize: 14, letterSpacing: 1, flexShrink: 0, opacity: 0.6 }}>≡</span>
              )}
              <div style={{ width: 42, textAlign: "center" as const }}>
                <p style={{ color: isSelected ? COLORS.accent : (day.isToday ? COLORS.accent : COLORS.textSecondary), fontSize: 11, fontWeight: 700, textTransform: "uppercase" as const, margin: 0 }}>{day.dayName}</p>
                <p style={{ color: isSelected ? COLORS.white : (day.isToday ? COLORS.accent : COLORS.white), fontSize: 14, fontWeight: 700, margin: 0 }}>{day.dateNum}</p>
                {/* Quiet secondary clarifier, not competing with the date above -
                    only really matters once a swap makes "5th row down" and
                    "program day 6" mean two different things, so it stays small
                    and muted rather than a second headline. */}
                <p style={{ color: COLORS.textSecondary, fontSize: 9, fontWeight: 600, margin: 0, opacity: 0.6 }}>Day {day.programDay}</p>
              </div>
              <div style={{ flex: 1 }}>
                <p style={{ color: day.isRest ? COLORS.textSecondary : COLORS.white, fontSize: 14, fontWeight: day.isRest ? 400 : 600, margin: "0 0 1px" }}>
                  {day.isRest ? "Rest Day" : (day.groups?.length > 0 ? deriveWorkoutTitle(day.groups, day.type, day.focus) : day.label)}
                </p>
                <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>
                  {day.isRest ? "Recovery" : (day.groups?.length > 0 ? (() => {
                    const muscles = [...new Set(day.groups.flatMap((g: any) => (g.exercises || []).map((ex: any) => {
                      const d = EXERCISES_DATA[ex.id]; return d?.muscle || null;
                    }).filter(Boolean)))].filter(m => m !== "Full Body" && m !== "Cardio").slice(0, 4);
                    return muscles.length > 0 ? muscles.join(", ") : "";
                  })() : "")}
                </p>
              </div>
              {day.isCompleted && !day.isFuture && <Check size={16} color={COLORS.success} strokeWidth={3} />}
              {!day.isCompleted && !day.isRest && day.isToday && <div style={{ width: 8, height: 8, borderRadius: 99, background: COLORS.accent }} />}
              {!day.isCompleted && !day.isRest && !day.isToday && <ChevronRight size={14} color={isSelected ? COLORS.accent : COLORS.border} />}
            </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

const WorkoutFlow = ({ profile, onComplete, onBack, onGoHomeSave, onProfileUpdate, isReview = false }) => {  const todayStr = new Date().toDateString();
  const [workoutFlowWeights, setWorkoutFlowWeights] = useState<Record<string, number>>({});
  const [liftPRs, setLiftPRs] = useState<Record<string, { isPR: boolean; weight: number }>>({});
  const liftPRCheckDoneRef = React.useRef(false);
  const workoutFlowWeightsRef = React.useRef<Record<string, number>>({});
  React.useEffect(() => { workoutFlowWeightsRef.current = {}; setWorkoutFlowWeights({}); }, []);
  const savedProgress = (() => {
    try {
      const raw = profile?.workoutProgress;
      if (!raw || raw.date !== todayStr) return null;
      return raw;
    } catch { return null; }
  })();

  const [localSwaps, setLocalSwaps] = useState<Record<string, string>>(profile?.programSwaps || {});
  // Sync localSwaps with Firestore on mount in case profile state is stale
  React.useEffect(() => {
    if (!profile?.uid) return;
    getDoc(doc(db, "users", profile.uid)).then(snap => {
      if (snap.exists()) {
        const saved = snap.data()?.programSwaps || {};
        setLocalSwaps(saved);
      }
    }).catch(() => {});
  }, []);
  const activeSessionIdRef = React.useRef<string | null>(null);
  // Create session doc at workout start so per-group weight saves always find it
  React.useEffect(() => {
    if (!profile?.uid || isReview) return;
    const today = getLocalDateString();
    const id = `${profile.uid}_${today}`;
    activeSessionIdRef.current = id;
    const currentProgramDay = profile?.programDay || 1;
    const sessionRef = doc(db, "workoutSessions", id);
    // Confirmed via direct testing: the session document id is date-based
    // only ({uid}_{date}), so if a person genuinely completes two different
    // program days on the same calendar date (a makeup session, re-doing a
    // day, etc.), both land in the SAME document. Without this check, an
    // earlier workout's weightsLogged/weightNotes silently persist and get
    // merged alongside a completely different, later workout's entries -
    // showing exercises from the WRONG program day mixed into what should
    // be a clean display of just today's actual workout. This reads the
    // existing doc first (if any) and only clears weightsLogged/weightNotes
    // when the programDay genuinely changed since that document was last
    // written - a normal remount mid-workout (same programDay, e.g.
    // between exercise groups) never touches them, so in-progress data
    // from earlier groups in THIS workout is still fully protected exactly
    // as before.
    getDoc(sessionRef).then(existingSnap => {
      const existingProgramDay = existingSnap.exists() ? existingSnap.data()?.programDay : null;
      const baseWrite: Record<string, any> = {
        uid: profile.uid,
        date: today,
        programDay: currentProgramDay,
      };
      if (existingSnap.exists() && existingProgramDay != null && existingProgramDay !== currentProgramDay) {
        baseWrite.weightsLogged = {};
        baseWrite.weightNotes = {};
      }
      return setDoc(sessionRef, baseWrite, { merge: true });
    }).catch(() => {});
  }, []);
  const [phase, setPhase] = useState<"list" | "active" | "complete">(savedProgress ? "list" : "list");

  // Fires once, exactly when the session actually completes (all groups
  // done) - not on every render, and not tied to the "Back to Dashboard"
  // button, since SessionCompleteScreen needs to already show correct PR
  // state the moment it first appears.
  React.useEffect(() => {
    if (phase === "complete" && !liftPRCheckDoneRef.current) {
      liftPRCheckDoneRef.current = true;
      const uid = profile?.uid;
      if (uid && Object.keys(workoutFlowWeights).length > 0) {
        checkAndUpdateLiftPRs(uid, workoutFlowWeights).then(setLiftPRs);
      }
    }
  }, [phase]);
  const [currentGroupIndex, setCurrentGroupIndex] = useState(savedProgress?.currentGroupIndex ?? 0);
  const [totalSetsCompleted, setTotalSetsCompleted] = useState(savedProgress?.totalSetsCompleted ?? 0);
  const [startTime] = useState(() => {
    if (savedProgress?.startTime) return savedProgress.startTime;
    return Date.now();
  });
  const hiddenAtRef = React.useRef<number | null>(null);
  const startTimeRef = React.useRef<number>(startTime);
  React.useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState === "hidden") {
        hiddenAtRef.current = Date.now();
      } else if (document.visibilityState === "visible" && hiddenAtRef.current !== null) {
        // Screen came back — do nothing, clock kept running on the server side via startTime
        hiddenAtRef.current = null;
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, []);
  const [groupRounds, setGroupRounds] = useState<Record<number, number>>(savedProgress?.groupRounds ?? {});
  const [groupExerciseIndexes, setGroupExerciseIndexes] = useState<Record<number, number>>(savedProgress?.groupExerciseIndexes ?? {});
  const [savedCompletedCells, setSavedCompletedCells] = useState<string[]>(savedProgress?.completedCells ?? []);
const savedCompletedCellsRef = React.useRef<string[]>(savedProgress?.completedCells ?? []);

  // Real audit finding, scoped proportionately to actual risk: this is a
  // pure resume-position bookmark (which round/exercise/cells someone was
  // on), not the actual recorded exercise data - the real weights already
  // have full durability via saveWeightsToFirestoreDurable, and the final
  // session record via saveWorkoutSessionDurable. If THIS specific save
  // fails, worst case is reopening the workout at an earlier resume point
  // and re-tapping through some already-completed checkmarks - annoying,
  // never actual data loss. Given that lower stakes plus this firing at
  // high frequency (every single set), a single-slot durable backup is the
  // right shape here, not the full multi-entry array used for weight
  // saves - only the LATEST progress position ever matters, so each new
  // save simply overwrites whatever was pending before it, rather than
  // needing to track several simultaneously.
  const PENDING_PROGRESS_SAVE_KEY = "amenityfit_pending_progress_save";
  // Guards against a real ordering risk that retries introduce: this fires
  // at high frequency (every set), and without this guard, an OLDER call
  // that's still retrying (slow connection) could finish AFTER a NEWER
  // call for a more recent set and silently overwrite genuinely more
  // complete progress with stale data - meaning a later set could
  // visually "revert" on reload. Every call gets its own sequence number;
  // a call whose sequence no longer matches the latest one (checked both
  // before each attempt AND again immediately after the write returns,
  // since a newer call could start while this one is still in flight)
  // simply abandons itself rather than risking a stale write.
  const progressSaveSeqRef = React.useRef(0);
  const saveProgressToFirestore = async (updates: Record<string, any>) => {
    if (!profile?.uid || isReview) return;
    const progressData = {
      date: todayStr,
      programDay: profile?.programDay || 1,
      completedCells: savedCompletedCellsRef.current,
      startTime,
      ...updates,
    };
    const mySeq = ++progressSaveSeqRef.current;
    try {
      localStorage.setItem(PENDING_PROGRESS_SAVE_KEY, JSON.stringify({ uid: profile.uid, progressData, seq: mySeq }));
    } catch (e) {
      // Storage can fail (quota, private mode) - the real save attempt
      // below still runs regardless.
    }
    const maxAttempts = 2;
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      if (mySeq !== progressSaveSeqRef.current) return; // superseded by a newer save - abandon
      try {
        await setDoc(doc(db, "users", profile.uid), {
          workoutProgress: progressData,
        }, { merge: true });
        if (mySeq !== progressSaveSeqRef.current) return; // superseded while this write was in flight
        onProfileUpdate?.({ workoutProgress: progressData });
        try {
          const raw = localStorage.getItem(PENDING_PROGRESS_SAVE_KEY);
          const current = raw ? JSON.parse(raw) : null;
          // Only clear the backup if it's still THIS call's entry - a
          // newer call may have already written its own pending entry,
          // which must never get deleted by an older call finishing late.
          if (current?.seq === mySeq) localStorage.removeItem(PENDING_PROGRESS_SAVE_KEY);
        } catch {}
        return;
      } catch (e) {
        console.error("Failed to save workout progress:", e);
        if (attempt < maxAttempts - 1) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
        }
      }
    }
    // Both attempts failed - backup deliberately left in place (if it's
    // still this call's own entry - see the same seq check above applied
    // implicitly by simply not deleting it here); the next set logged
    // will simply try again with a newer position anyway, and the
    // mount-time recovery effect below covers the case where the app
    // closes before that happens.
  };
  // Checked once when this screen mounts (someone opening/resuming a
  // workout) - if a previous session's progress bookmark never actually
  // confirmed as saved, this finishes writing it now, silently, before
  // anything else. Placed AFTER saveProgressToFirestore's own declaration,
  // not before it - same precaution as the weight-save recovery effect,
  // eliminating any possibility of referencing it before it's assigned.
  useEffect(() => {
    (async () => {
      let pending: { uid: string; progressData: any } | null = null;
      try {
        const raw = localStorage.getItem(PENDING_PROGRESS_SAVE_KEY);
        if (raw) pending = JSON.parse(raw);
      } catch {}
      if (!pending || pending.uid !== profile?.uid) return;
      try {
        await setDoc(doc(db, "users", pending.uid), { workoutProgress: pending.progressData }, { merge: true });
        localStorage.removeItem(PENDING_PROGRESS_SAVE_KEY);
      } catch (e) {
        console.error("Failed to recover pending workout progress:", e);
      }
    })();
  }, []);

  const sessionLength = Number(profile?.sessionLength) || 45;
  // In review mode, programDay has already incremented to the next day.
  // Use the snapshot's saved programDay (the day that was actually completed).
  const workoutWasDoneToday = profile?.lastSessionDate === new Date().toDateString();
  const snapshotDay = profile?.lastWorkoutSnapshot?.programDay;
  // Only the third branch (starting a not-yet-completed workout right now)
  // resolves through the swap-aware resolver. The first two branches are
  // reviewing a workout that's already completed - that historical record
  // is frozen and must never be affected by a later swap, matching the
  // rule that a completed day can never be part of a swap in the first
  // place. This is exactly why "Start Today's Workout" was still loading
  // the pre-swap content: this computation never went through the shared
  // resolver Dashboard's card text, Weekly View, and the assistant already
  // use, even though it's the one place that actually matters most - what
  // content someone is about to do right now.
  const actualCompletedDay = isReview && workoutWasDoneToday && snapshotDay
    ? snapshotDay
    : isReview && workoutWasDoneToday
    ? Math.max((profile?.programDay || 1) - 1, 1)
    : resolveProgramDayForDate(profile?.programDay || 1, new Date(), profile?.dayOverrides);
    const day = getProgramDay(profile?.programKey || selectProgram(profile), actualCompletedDay, profile?.generatedDays);
  // In review mode: use the frozen snapshot of what was actually completed.
  const snapshotGroups = profile?.lastWorkoutSnapshot?.groups;
  // Freeze equipment preference for review — don't let current setting alter already-done workout
  const reviewEquipmentPreference = isReview
    ? (profile?.lastWorkoutSnapshot?.equipmentPreference || profile?.equipmentPreference || "gym-and-bands")
    : (profile?.equipmentPreference || "gym-and-bands");

  // Agility ladder substitution — replace with jump rope when building
  // doesn't have an agility ladder (most residential building gyms don't).
  // Kept in advanced-athletic programs by design; substituted everywhere else.
  const filterCardioNote = (note: string, buildingEquipment: string[]): string => {
  if (!buildingEquipment || buildingEquipment.length === 0) return note;
  const equipmentRules: Record<string, string[]> = {
    "Treadmill Walk or Run": ["treadmill"],
    "Stationary Bike": ["bike"],
    "Elliptical": ["elliptical"],
    "Stairmaster": ["stairmaster"],
    "Jump Rope": ["jump-rope"],
    "Rowing Machine": ["rowing-machine"],
  };
  const lines = note.split("\n");
  const hasRowingMachine = lines.some(l => l.trim() === "• Rowing Machine");
  const rowingAvailable = buildingEquipment.includes("rowing-machine");
  const filtered = lines.filter(line => {
    if (!line.startsWith("•")) return true;
    const label = line.replace("•", "").trim();
    const required = equipmentRules[label];
    if (!required) return true;
    return required.some(eq => buildingEquipment.includes(eq));
  });
  if (rowingAvailable && !hasRowingMachine) {
    const jumpRopeIdx = filtered.findIndex(l => l.trim() === "• Jump Rope");
    if (jumpRopeIdx !== -1) {
      filtered.splice(jumpRopeIdx, 0, "• Rowing Machine");
    } else {
      const lastBullet = filtered.map((l, i) => l.startsWith("•") ? i : -1).filter(i => i !== -1).pop();
      if (lastBullet !== undefined) filtered.splice(lastBullet, 0, "• Rowing Machine");
    }
  }
  return filtered.join("\n");
};

  const rawGroups = (isReview && snapshotGroups && snapshotGroups.length > 0)
    ? snapshotGroups
    : filterGroupsForSessionLength(day.groups, sessionLength, profile?.effectiveLevel || profile?.experience || "intermediate");
  // If session is 30min and has circuit groups, update day notes to reflect 2 rounds
  const dayWithUpdatedNotes = React.useMemo(() => {
    if (sessionLength >= 45 || isReview) return day;
    const hasCircuit = rawGroups.some((g: any) => g.restBetweenSets === "None");
    if (!hasCircuit) return day;
    const updatedNotes = (day.notes || []).map((n: string) =>
      n.replace(/repeat\s+circuit\s+3[-\s]?4?\s*times?/gi, "Repeat circuit 2 times")
       .replace(/repeat\s+circuit\s+3\s*times?/gi, "Repeat circuit 2 times")
       .replace(/90\s+to\s+120\s+seconds\s+rest\s+after\s+each\s+circuit/gi, "90 to 120 seconds rest after each circuit")
       .replace(/3[-\s]?4\s*rounds?/gi, "2 rounds")
       .replace(/(?<!\d)3\s+rounds?/gi, "2 rounds")
    );
    return { ...day, notes: updatedNotes };
  }, [day, sessionLength, rawGroups, isReview]);
    const substituteAgilityLadder = (groups: any[]): any[] => {
      return groups.map(group => {
        if (group.type === "cardio") return group;
        const exercises = (group.exercises || []).map((ex: any) => {
          if (ex.id === "agility-ladder") {
            const buildingEq = profile?.buildingEquipment || [];
            const hasAgilityLadder = buildingEq.includes("agility-ladder");
            if (!hasAgilityLadder) {
              return { ...ex, id: "cone-drills" };
            }
          }
          return ex;
        });
        return { ...group, exercises };
      });
    };
    const agilitySubstituted = substituteAgilityLadder(rawGroups);
    const reEntryAdjusted = profile?.reEntryMode ? filterGroupsForReEntry(agilitySubstituted, profile?.effectiveLevel || profile?.experience || "intermediate", profile?.programKey || "") : agilitySubstituted;
    // Filter exercises based on user injury flags — hard filter, runs every workout
    const equipmentFiltered = filterExercisesByEquipment(reEntryAdjusted, reviewEquipmentPreference, profile?.buildingEquipment || []);
const videoFiltered = filterExercisesByVideo(equipmentFiltered);
const injuryFiltered = dedupeExercisesInDay(filterExercisesByInjury(videoFiltered, profile?.injuries || "none", profile?.equipmentPreference || "gym-and-bands", profile?.buildingEquipment || [], (parseInt(String(profile?.age)) || 30) >= 65), profile?.equipmentPreference || "gym-and-bands", profile?.buildingEquipment || []);
    // Filter cardio options to only show equipment the building actually has
    const buildingEquipment: string[] = profile?.buildingEquipment || [];
    // Calculate dynamic cardio minutes based on session length and remaining time
    const dynamicCardioMinutes = calculateCardioMinutes(injuryFiltered, sessionLength);
    const swapsMap = localSwaps;
const workoutGroups = injuryFiltered.map(group => ({
    ...group,
    cardioMinutes: group.type === "cardio" ? dynamicCardioMinutes : group.cardioMinutes,
    cardioNote: group.cardioNote
      ? filterCardioNote(group.cardioNote, buildingEquipment)
      : group.cardioNote,
    exercises: (group.exercises || []).map((ex: any) => {
      const swapKey = `${profile?.programKey}_day${profile?.programDay}_${ex.id}`;
      const swappedId = swapsMap[swapKey];
      return swappedId ? { ...ex, id: swappedId, _originalId: ex.id } : ex;
    }),
  }));
  // Use day.type directly for accurate hero image — avoids mismatches when session
  // length filtering removes groups that would otherwise correctly identify the type
  const dayType = day?.type || "full-body";
  const isPureCardioDay = workoutGroups.every(g => g.type === "cardio");
  const workoutType = isPureCardioDay ? "cardio"
    : dayType === "lower-body" ? "lower-body"
    : dayType === "upper-body" || dayType === "push" || dayType === "pull" ? dayType
    : dayType === "cardio" ? "cardio"
    : (() => {
        const filteredFocuses = workoutGroups.filter(g => g.type !== "cardio").map((g: any) => g.focus || "full");
        const hasUpper = filteredFocuses.some((f: string) => f.includes("upper"));
        const hasLower = filteredFocuses.some((f: string) => f.includes("lower"));
        return hasUpper && hasLower ? "full-body" : hasLower ? "lower-body" : "upper-body";
      })();

      const handleGroupComplete = () => {
        const groupSets = (workoutGroups[currentGroupIndex].exercises || []).reduce((a, e) => a + (e.sets || 0), 0);
        const newTotal = totalSetsCompleted + groupSets;
        const nextIndex = currentGroupIndex + 1;
        setTotalSetsCompleted(newTotal);
        setSavedCompletedCells([]);
        savedCompletedCellsRef.current = [];
        if (currentGroupIndex < workoutGroups.length - 1) {
          setCurrentGroupIndex(nextIndex);
          saveProgressToFirestore({
            currentGroupIndex: nextIndex,
            totalSetsCompleted: newTotal,
            groupRounds,
            groupExerciseIndexes,
            completedCells: [],
          });
        } else {
          setPhase("complete");
          // Clear progress on completion
          if (profile?.uid) {
            setDoc(doc(db, "users", profile.uid), { workoutProgress: null }, { merge: true });
          }
        }
      };

  if (phase === "list") {
    const pinnedImage = getWorkoutImage(workoutType, actualCompletedDay);
    return <WorkoutListScreen day={dayWithUpdatedNotes} filteredGroups={workoutGroups} onStart={() => setPhase("active")} onBack={onBack} workoutImage={pinnedImage} programDay={actualCompletedDay} programWeek={profile?.programWeek || 1} isReview={isReview} bgPosition={workoutType === "upper-body" || workoutType === "push" ? "center top" : workoutType === "lower-body" ? "center 60%" : "center"} equipmentPreference={reviewEquipmentPreference} isInProgress={currentGroupIndex > 0 || (savedProgress?.currentGroupIndex ?? 0) > 0 || (savedProgress?.completedCells?.length ?? 0) > 0} currentGroupIndex={currentGroupIndex} workoutType={workoutType} workoutDoneToday={isReview || workoutWasDoneToday} buildingEquipment={profile?.buildingEquipment || []} />;
  }

  if (phase === "overview") {
    return (
      <div style={{ height: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column", overflowY: "auto", WebkitOverflowScrolling: "touch" as any }}>
        <div style={{ padding: "52px 24px 20px", display: "flex", alignItems: "center", gap: 16, flexShrink: 0 }}>
          <button onClick={() => setPhase("active")} style={{ background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 12, width: 40, height: 40, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}>
            <ArrowLeft size={18} color={COLORS.white} />
          </button>
          <div style={{ flex: 1 }}>
            <h2 style={{ color: COLORS.white, fontSize: 20, fontWeight: 900, margin: 0, letterSpacing: -0.5 }}>Today's Workout</h2>
            <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: "2px 0 0" }}>{workoutGroups.length} groups · {sessionLength} min</p>
          </div>
        </div>

        <div style={{ padding: "0 24px 80px", display: "flex", flexDirection: "column", gap: 12 }}>
          {workoutGroups.map((group, i) => {
            const isCompleted = i < currentGroupIndex;
            const isCurrent = i === currentGroupIndex;
            const isUpcoming = i > currentGroupIndex;
            return (
              <div
                key={i}
                onClick={() => {
                  if (isCurrent) {
                    setPhase("active");
                  }
                }}
                style={{
                  background: isCurrent ? `${COLORS.primary}20` : COLORS.card,
                  border: `1.5px solid ${isCurrent ? COLORS.primary : isCompleted ? COLORS.success + "40" : COLORS.border}`,
                  borderRadius: 16, padding: "16px 18px",
                  cursor: isUpcoming ? "default" : "pointer",
                  opacity: isUpcoming ? 0.5 : 1,
                  transition: "all 0.2s ease",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
                  <div style={{
                    width: 36, height: 36, borderRadius: 99, flexShrink: 0,
                    background: isCompleted ? `${COLORS.success}20` : isCurrent ? `${COLORS.primary}30` : COLORS.background,
                    border: `1.5px solid ${isCompleted ? COLORS.success : isCurrent ? COLORS.primary : COLORS.border}`,
                    display: "flex", alignItems: "center", justifyContent: "center",
                  }}>
                    {isCompleted
                      ? <Check size={16} color={COLORS.success} strokeWidth={3} />
                      : <p style={{ color: isCurrent ? COLORS.accent : COLORS.textSecondary, fontSize: 13, fontWeight: 800, margin: 0 }}>{i + 1}</p>
                    }
                  </div>
                  <div style={{ flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 2 }}>
                      <span style={{ color: isCurrent ? COLORS.accent : isCompleted ? COLORS.success : COLORS.textSecondary, fontSize: 10, fontWeight: 800, letterSpacing: 1, textTransform: "uppercase" }}>
                        {group.type === "cardio" ? "Cardio" : group.type === "straight" ? "Straight Set" : group.type === "superset" && group.exercises?.length >= 3 ? "Triset" : group.type === "superset" ? "Superset" : group.label}
                      </span>
                    </div>
                    <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 700, margin: "0 0 2px" }}>
                      {group.type === "cardio" ? `${calculateCardioMinutes(workoutGroups, sessionLength)} min cardio` : group.exercises?.map((e: any) => EXERCISES_DATA[e.id]?.name || e.id).join(", ")}
                    </p>
                  </div>
                  {isCurrent && (
                    <div style={{ background: `${COLORS.accent}20`, borderRadius: 8, padding: "4px 10px" }}>
                      <span style={{ color: COLORS.accent, fontSize: 11, fontWeight: 700, letterSpacing: 0.8 }}>ACTIVE</span>
                    </div>
                  )}
                  {isCompleted && (
                    <ChevronRight size={16} color={COLORS.success} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  if (phase === "active") {
    return (
      <ActiveExerciseScreen
        key={currentGroupIndex}
        group={workoutGroups[currentGroupIndex]}
        groupIndex={currentGroupIndex}
        totalGroups={workoutGroups.length}
        startTime={startTime}
        onGroupComplete={handleGroupComplete}
        onBack={() => {
          saveProgressToFirestore({
            currentGroupIndex,
            totalSetsCompleted,
            groupRounds,
            groupExerciseIndexes,
            completedCells: savedCompletedCells,
          });
          setPhase("list");
        }}
        onGoHome={() => {
          const progressSnapshot = {
            date: new Date().toDateString(),
            programDay: profile?.programDay || 1,
            currentGroupIndex,
            totalSetsCompleted,
            groupRounds,
            groupExerciseIndexes,
          };
          saveProgressToFirestore(progressSnapshot);
          const updatedProfile = { ...profile, workoutProgress: progressSnapshot };
          onGoHomeSave ? onGoHomeSave(updatedProfile) : onBack();
        }}
initialRound={groupRounds[currentGroupIndex] ?? 1}
initialExerciseIndex={groupExerciseIndexes[currentGroupIndex] ?? 0}
initialCompletedCells={currentGroupIndex === (savedProgress?.currentGroupIndex ?? 0) && savedProgress?.date === new Date().toDateString() ? savedCompletedCells : []}
onSaveState={(round: number, exerciseIndex: number, cells?: string[]) => {
  const newRounds = { ...groupRounds, [currentGroupIndex]: round };
  const newIndexes = { ...groupExerciseIndexes, [currentGroupIndex]: exerciseIndex };
  setGroupRounds(newRounds);
  setGroupExerciseIndexes(newIndexes);
  if (cells !== undefined) {
    setSavedCompletedCells(cells);
    savedCompletedCellsRef.current = cells;
  }
  saveProgressToFirestore({
    currentGroupIndex,
    totalSetsCompleted,
    groupRounds: newRounds,
    groupExerciseIndexes: newIndexes,
    completedCells: cells !== undefined ? cells : savedCompletedCells,
  });
}}
        onShowOverview={() => setPhase("overview")}
        initialWeights={workoutFlowWeights}
        onWeightsSaved={(weights: Record<string, number>) => { const merged = { ...workoutFlowWeightsRef.current, ...weights }; workoutFlowWeightsRef.current = merged; setWorkoutFlowWeights(merged); }}
        profile={profile}
        sessionId={activeSessionIdRef.current}
        initialSwaps={localSwaps}
        onSwap={(swapKey: string, newId: string) => {
          const updated = { ...(profile?.programSwaps || {}), ...localSwaps, [swapKey]: newId };
          setLocalSwaps(updated);
          if (profile?.uid) {
            setDoc(doc(db, "users", profile.uid), { programSwaps: updated }, { merge: true });
          }
          // Immediately syncs the parent's own userProfile state, the same
          // way saveProgressToFirestore already does for workout progress.
          // Without this, a swap only ever lived in this component's own
          // local state and Firestore - the parent never found out, so a
          // fresh mount after navigating away had no way to know about it
          // until an async re-fetch caught up, if it ever did.
          onProfileUpdate?.({ programSwaps: updated });
        }}
      />
    );
  }

  return (
    <SessionCompleteScreen
      totalSets={totalSetsCompleted}
      timeSeconds={Math.floor((Date.now() - startTime) / 1000)}
      userName={profile?.name ? (profile.name.split(" ")[0].charAt(0).toUpperCase() + profile.name.split(" ")[0].slice(1).toLowerCase()) : ""}
      sessionCount={profile?.sessionsCompleted || 0}
      uid={profile?.uid || ""}
      weightsLogged={workoutFlowWeights}
      liftPRs={liftPRs}
      dayTitle={deriveWorkoutTitle(workoutGroups)}
      // Real gap found in this session's audit: a lift+cardio combined
      // day (e.g. a legs+cardio day) saves as two separate documents, and
      // the cardio one is tagged with linkedWorkoutId pointing back to
      // this session - but until now nothing ever read that tag back out,
      // so a combined day showed no unified completion moment at all.
      // Passing the real session id lets this screen check for a linked
      // cardio session and present both halves together.
      sessionId={activeSessionIdRef.current}
      // completedProgramDay is passed up alongside the groups so the save
      // path never has to independently recompute "what day was this" from
      // userProfile.programDay at some later point in time. That second,
      // separate computation is exactly what caused the label saved onto
      // lastWorkoutSnapshot to disagree with the actual groups saved right
      // next to it - programDay could drift between when this screen chose
      // its content and when completion got processed. actualCompletedDay
      // is the single value this screen already uses for both the visible
      // day badge and the content lookup, so passing it through guarantees
      // the saved label can never disagree with the saved content again.
      onDone={() => onComplete({ groups: workoutGroups, sessionLength, weightsLogged: workoutFlowWeightsRef.current, completedProgramDay: actualCompletedDay, sessionId: activeSessionIdRef.current })}
    />
  );
};




// ─── Fitness Assistant ────────────────────────────────────────────────────────

const getSuggestedQuestions = (profile: any): string[] => {
  const programDay = profile?.programDay || 1;
  const programKey = profile?.programKey || "";
  const workoutDoneToday = profile?.lastSessionDate === new Date().toDateString();
  const experience = profile?.effectiveLevel || profile?.experience || "beginner";
  const goal = profile?.primaryGoal || "general_fitness";
  const injuries = profile?.injuries && profile.injuries !== "none" ? profile.injuries : null;
  const gender = profile?.gender || "prefer_not";
  const hasProgram = !!programKey && !!PROGRAMS[programKey];
  const sessionsCompleted = profile?.sessionsCompleted || 0;
  const sessionsThisWeek = profile?.sessionsThisWeek || 0;
  const frequency = profile?.frequency || 3;
  const streak = profile?.streak || 0;
  const cycleNumber = profile?.cycleNumber || 1;
  const isEvolvedProgramming = cycleNumber >= 4 || profile?.progressionPhase === "month6+" || profile?.progressionPhase === "Month6+";

  const isRestDay = (() => {
    const resolvedDay = resolveProgramDayForDate(programDay, new Date(), profile?.dayOverrides);
    const day = getProgramDay(programKey, resolvedDay, profile?.generatedDays);
    return day?.isRest || day?.groups?.length === 0 || false;
  })();

  // If workout done today, programDay already incremented — step back to get the day actually completed
  const displayProgramDay = workoutDoneToday ? Math.max(programDay - 1, 1) : programDay;
  const todayFocus = (() => {
    if (!hasProgram) return null;
    const resolvedDisplayDay = resolveProgramDayForDate(displayProgramDay, new Date(), profile?.dayOverrides);
    const dayData = getProgramDay(programKey, resolvedDisplayDay, profile?.generatedDays);
    return deriveWorkoutTitle(dayData?.groups || [], undefined, dayData?.focus) || dayData?.title || null;
  })();

  // Gender-aware question
  const genderQ = gender === "female"
    ? "How does stress affect how my body responds to training?"
    : gender === "male"
    ? "How do I know if I'm building real strength or just getting tired?"
    : "How do I know if my effort in the gym is actually translating?";

  // No program yet
  if (!hasProgram) return [
    "How does AmenityFit decide which program to start me on?",
    "What can I ask you about before I begin?",
    "I'm struggling to stay consistent. What's actually going on?",
    "How do I best recover between sessions?",
  ];

  // Rest day
  if (isRestDay) return sessionsCompleted < 3 ? [
    "How do I use this app?",
    "My muscles are sore today. Is that a good sign or bad sign?",
    "How do I best recover between sessions?",
    "I'm struggling to stay consistent. What's actually going on?",
  ] : [
    "My muscles are sore today. Is that a good sign or bad sign?",
    "How do I best recover between sessions?",
    "I'm struggling to stay consistent. What's actually going on?",
    genderQ,
  ];

  // Post-workout
  if (workoutDoneToday) return sessionsCompleted < 3 ? [
    "How do I use this app?",
    todayFocus ? `I just finished ${todayFocus}. What should I do in the next few hours?` : "I just finished training. What should I do in the next few hours?",
    "How do I best recover between sessions?",
    "I'm struggling to stay consistent. What's actually going on?",
  ] : [
    todayFocus ? `I just finished ${todayFocus}. What should I do in the next few hours?` : "I just finished training. What should I do in the next few hours?",
    "How do I best recover between sessions?",
    "I'm struggling to stay consistent. What's actually going on?",
    genderQ,
  ];

  // Injury present
  if (injuries) return [
    "How do I use this app?",
    "Will today's session work for where I'm at physically?",
    "How do I swap an exercise that isn't working for me?",
    genderQ,
  ];

  // Early in journey
  if (sessionsCompleted < 5) return [
    "How do I use this app?",
    todayFocus ? `What should I know before starting ${todayFocus} today?` : "What should I know before I start today?",
    "How do I know if my form is right on these exercises?",
    "I'm struggling to stay consistent. What's actually going on?",
  ];

  // Goal-based
  const goalQuestions: Record<string, string[]> = {
    fat_loss: [
      todayFocus ? `What should I focus on during ${todayFocus} today?` : "What should I focus on in today's session?",
      "How do I know if I'm in a calorie deficit without losing muscle?",
      "I'm struggling to stay consistent. What's actually going on?",
      genderQ,
    ],
    muscle_gain: [
      "How do I know if I'm lifting heavy enough to actually build muscle?",
      todayFocus ? `What should I eat before ${todayFocus} today?` : "What should I eat before today's session?",
      "I'm struggling to stay consistent. What's actually going on?",
      "How do I best recover between sessions?",
    ],
    
    athletic_performance: [
      todayFocus ? `What's the best way to prepare for ${todayFocus} today?` : "What's the best way to prepare for today?",
      "How do I balance training here with what I do outside?",
      "I'm struggling to stay consistent. What's actually going on?",
      "How do I best recover between sessions?",
    ],
    general_fitness: [
      todayFocus ? `What should I know before starting ${todayFocus} today?` : "What should I focus on today?",
      "How does my program evolve the longer I stick with it?",
      "I'm struggling to stay consistent. What's actually going on?",
      genderQ,
    ],
  };

  return goalQuestions[goal] || [
    todayFocus ? `What should I focus on during ${todayFocus} today?` : "What should I focus on today?",
    "How do I swap an exercise that isn't working for me?",
    "I'm struggling to stay consistent. What's actually going on?",
    "How do I best recover between sessions?",
  ];
};


// Splits program label into { name, levelTag } for user-facing display
// "Women's Advanced — Earn Your Victory" → { name: "Earn Your Victory", levelTag: "Advanced" }
// "Advanced Athletic Month 1" → { name: "Advanced Athletic Month 1", levelTag: "" }
const getProgramParts = (label: string): { name: string; levelTag: string } => {
  if (!label) return { name: "", levelTag: "" };
  const emDashIdx = label.indexOf(" — ");
  if (emDashIdx > -1) {
    const prefix = label.slice(0, emDashIdx).trim();
    const name = label.slice(emDashIdx + 3).trim();
    // Extract clean level from prefix
    // "Beginner 3x" → "Beginner", "Women's Advanced" → "Advanced",
    // "Men's Intermediate" → "Intermediate", "Senior" → "Senior"
    let levelTag = "";
    if (prefix.toLowerCase().includes("advanced")) levelTag = "Advanced";
    else if (prefix.toLowerCase().includes("intermediate")) levelTag = "Intermediate";
    else if (prefix.toLowerCase().includes("senior")) levelTag = "Senior";
    else if (prefix.toLowerCase().includes("beginner")) levelTag = "Beginner";
    return { name, levelTag };
  }
  // No em dash — programs like "Advanced Athletic Month 1"
  return { name: label, levelTag: "" };
};

// Convenience: just the program name without prefix (for strings/assistant context)
const getProgramDisplayName = (label: string): string => getProgramParts(label).name || label;

const buildSystemPrompt = (profile: any) => {
  const name = profile?.name ? profile.name.split(" ").map((w: string) => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(" ") : "there";
  const goal = {
    fat_loss: "fat loss", muscle_gain: "muscle gain", tone: "toning up",
    general_fitness: "general fitness", athletic_performance: "athletic performance"
  }[profile?.primaryGoal] || "general fitness";
  const secondaryGoal = profile?.secondaryGoal ? ` and ${
    { fat_loss: "fat loss", muscle_gain: "muscle gain", general_fitness: "general fitness" }[profile.secondaryGoal] || profile.secondaryGoal
  }` : "";
  const experience = profile?.effectiveLevel || profile?.experience || "beginner";
  const frequency = profile?.frequency || 3;
  const sessionLength = profile?.sessionLength || 45;
  const age = profile?.age ? `${profile.age} years old` : "age not specified";
  const injuries = profile?.injuries && profile.injuries !== "none" ? profile.injuries : null;
  const equipment = profile?.equipmentPreference || "gym-and-bands";
  const cycleNumber = profile?.cycleNumber || 1;
  const programDay = profile?.programDay || 1;
  const programKey = profile?.programKey || "";
  const sessionsCompleted = profile?.sessionsCompleted || 0;
  const sessionsThisWeek = profile?.sessionsThisWeek || 0;
  const streak = profile?.streak || 0;
  const gender = profile?.gender || "prefer_not";
  const isEvolvedProgramming = (profile?.cycleNumber || 1) >= 4 || profile?.progressionPhase === "month6+" || profile?.progressionPhase === "Month6+";

  const workoutDoneToday = profile?.lastSessionDate === new Date().toDateString();

  let programName = "their current program";
  let todayFocus = "";
  let todayExercises: string[] = [];
  let tomorrowFocus = "";
  let weekStructure = "";
  let totalCardioMins = 0;
  let isRestDay = false;

  if (programKey && PROGRAMS[programKey]) {
    const prog = PROGRAMS[programKey];
    const { name: progName, levelTag } = getProgramParts(prog.label || "");
    const motivationalName = getProgramMotivationalName(programKey);
    const safeLabel = (prog.label || programKey).replace(/^(men's|women's|senior\s*)?(beginner|intermediate|advanced)\s*\d*x?\/?week?\s*[-—]?\s*/i, "").trim();
    programName = motivationalName || (progName && levelTag ? `${progName} · ${levelTag}` : (progName || safeLabel || programKey));
    const days = prog.days || [];
    if (days.length > 0) {
      // Reuses the exact same getWeekSchedule function Weekly View itself
      // calls for its own display, instead of maintaining a second,
      // independently-computed version of "what's today/tomorrow/this
      // week" that can drift out of sync with what the user actually
      // sees - which is precisely what happened here (a rest-day swap
      // wasn't correctly reflected by the old duplicate index math).
      // Guarantees the assistant can never describe a different schedule
      // than what's genuinely shown on screen.
      const workoutDoneTodayCoach = profile?.lastSessionDate === new Date().toDateString();
      const coachCurrentProgramDay = workoutDoneTodayCoach ? Math.max(programDay - 1, 1) : programDay;
      const weekDaysForCoach = getWeekSchedule(
        coachCurrentProgramDay,
        profile?.frequency || 4,
        profile?.completedProgramDays || [],
        profile?.lastSessionDate || "",
        programKey,
        new Date(),
        profile?.generatedDays,
        profile?.injuries,
        profile?.equipmentPreference,
        profile?.buildingEquipment,
        parseInt(String(profile?.age)) || 30,
        profile?.sessionLength || 60,
        profile?.effectiveLevel || profile?.experience || "intermediate",
        profile?.dayOverrides
      );
      const todayDay = weekDaysForCoach[0];
      const tomorrowDay = weekDaysForCoach[1];
      if (todayDay) {
        isRestDay = !!todayDay.isRest;
        todayFocus = todayDay.focus || todayDay.title || "";
        if (!isRestDay && todayDay.groups) {
          // Re-entry mode reduces which groups actually appear in the real
          // workout (see the same fix on Dashboard's TodayWorkoutCard) -
          // without this, the coach ends up referencing exercises that
          // were filtered out and aren't actually part of today's session.
          const reEntryFilteredGroups = profile?.reEntryMode ? filterGroupsForReEntry(todayDay.groups, profile?.effectiveLevel || profile?.experience || "intermediate", profile?.programKey || "") : todayDay.groups;
          const cardioGroups = reEntryFilteredGroups.filter((g: any) => g.type === "cardio");
          const strengthGroups = reEntryFilteredGroups.filter((g: any) => g.type !== "cardio" && g.type !== "rest");
          todayExercises = strengthGroups
            .flatMap((g: any) => g.exercises?.map((e: any) => {
              const ex = EXERCISES_DATA[e.id];
              return ex ? `${ex.name} (${e.sets} sets x ${e.reps})` : e.id;
            }) || []);
          // Recompute todayFocus from what's ACTUALLY in strengthGroups
          // after session-length truncation, instead of the day's static
          // focus/title label - which still describes the untruncated
          // program day (e.g. "Legs & Abs") even when a shorter session
          // length has already dropped some of those muscle groups from
          // what's really being shown/exercised today. Falls back to the
          // static label only if truncation somehow left no strength
          // exercises at all.
          const todayMuscles: string[] = [];
          strengthGroups.forEach((g: any) => {
            (g.exercises || []).forEach((e: any) => {
              const m = EXERCISES_DATA[e.id]?.muscle;
              if (m && !todayMuscles.includes(m)) todayMuscles.push(m);
            });
          });
          const muscleToCoachLabel: Record<string, string> = {
            "Chest": "Chest", "Back": "Back", "Shoulders": "Shoulders",
            "Triceps": "Triceps", "Biceps": "Biceps", "Quads": "Legs",
            "Hamstrings": "Legs", "Glutes": "Glutes", "Core": "Abs",
            "Full Body": "Full Body", "Calves": "Calves",
          };
          const todayLabels = [...new Set(todayMuscles.map(m => muscleToCoachLabel[m] || m))];
          if (todayLabels.length > 0) {
            todayFocus = todayLabels.join(" & ");
          } else if (cardioGroups.length > 0) {
            // Truncation dropped every strength group, leaving only cardio -
            // the muscle-derived label above has nothing to work with here,
            // so fall through to "Cardio" instead of the stale static label.
            todayFocus = "Cardio";
          }
          if (cardioGroups.length > 0) {
            // Was summing the raw cardioMinutes field baked into the
            // program template (e.g. 35), not the actual session-length-
            // adjusted duration the real workout card computes and shows
            // (e.g. 55) via this same calculateCardioMinutes function -
            // meaning the coach could describe a completely different
            // cardio duration than what the person's own card says.
            const cardioMins = calculateCardioMinutes(todayDay.groups, profile?.sessionLength || 60);
            if (cardioMins > 0) todayExercises.push(`Cardio Finish — ${cardioMins} minutes (elliptical, stairmaster, bike, treadmill, jump rope, or similar)`);
          }
        }
      }
      // Calculate exact cardio minutes for coach context - same fix as
      // above, using the real session-length-adjusted calculation instead
      // of summing raw template values. Guarded on an actual cardio group
      // being present - calculateCardioMinutes has no such guard itself
      // and always returns at least 10, so calling it unconditionally
      // would fabricate a nonzero cardio duration even for pure-strength
      // days with no cardio component at all.
      const hasCardioToday = !isRestDay && (todayDay?.groups || []).some((g: any) => g.type === "cardio");
      totalCardioMins = hasCardioToday ? calculateCardioMinutes(todayDay.groups, profile?.sessionLength || 60) : 0;

      if (tomorrowDay) {
        tomorrowFocus = tomorrowDay.isRest ? "Rest day" : (tomorrowDay.focus || tomorrowDay.title || "");
      }
      weekStructure = weekDaysForCoach
        .map((d: any, i: number) => `Day ${i + 1}: ${d.isRest ? "Rest" : (d.focus || d.title || "Workout")}`)
        .join(", ");
    }
  }

  const equipmentLabel = equipment === "gym" ? "gym equipment only (dumbbells, cables, machines, barbells)"
    : equipment === "bands" ? "resistance bands only"
    : equipment === "bodyweight" ? "bodyweight only"
    : "gym equipment plus resistance bands";

  return `You are the fitness assistant inside AmenityFit — a platform built by Senz, a former professional athlete with an Ivy League education who became a life and identity coach. You are not a generic AI fitness chatbot. You are the digital expression of that coaching intelligence.

Your foundation is real: exercise science, strength and conditioning, sports performance, nutrition, recovery, physical therapy principles as they apply to movement and training, and the psychology of behavior change. You operate at whatever level the person in front of you is at. A beginner gets clarity, not condescension. An advanced athlete gets depth, not fluff. You read the room and adjust without being asked.

But what makes you different is the layer underneath the physical. You understand that fitness is almost never just about fitness. The person who keeps quitting programs isn't lazy — they're disconnected from why it matters to them. The person asking about weight loss at midnight isn't just thinking about calories. The person who hasn't been to the gym in three weeks isn't looking for a workout plan. You find what's actually underneath before you address what's on the surface. Then you address both.

You know about identity — how people get stuck between who they were and who they're becoming, how transitions (career, relationships, injury, aging, loss) live in the body before they live in the mind, and how the gym can either be a place where someone hides or a place where they find out who they actually are. You use this lens naturally, not as a lecture. One sentence can carry it. A question can carry it. You don't over-explain it.

USER YOU'RE WORKING WITH:
- Name: ${name}
- Age: ${age}
- Goal: ${goal}${secondaryGoal}
- Experience: ${experience}
- Trains: ${frequency} days per week, ${sessionLength} minute sessions
- Equipment: ${equipmentLabel}
${profile?.wearableData?.whoop && !profile?.wearableOverride ? `- Wearable data (Whoop, pulled today): Recovery ${profile.wearableData.whoop.recovery}%, Strain ${profile.wearableData.whoop.strain}, Sleep performance ${profile.wearableData.whoop.sleep}%. ${profile.wearableData.whoop.recovery < 40 ? "This is a low recovery day — open with one warm sentence acknowledging it, then coach normally." : "This is a moderate recovery day — lean toward quality over intensity in your tone."} ${getWorkoutModifier(profile)?.toneContext || ""}` : ""}
${profile?.wearableData?.apple && !profile?.wearableOverride ? `- Wearable data (Apple Watch, pulled today): Resting heart rate ${profile.wearableData.apple.restingHeartRate ?? "not available"} bpm, Active energy ${profile.wearableData.apple.activeCalories ?? "not available"} kcal, Sleep ${profile.wearableData.apple.sleepHours ?? "not available"} hours. ${profile.wearableData.apple.restingHeartRate && profile.wearableData.apple.restingHeartRate > 65 ? "Elevated resting heart rate today — factor recovery into your coaching tone." : "Resting heart rate looks normal — coach at full intensity unless other signals suggest otherwise."} ${getWorkoutModifier(profile)?.toneContext || ""}` : ""}
${profile?.wearableData?.fitbit && !profile?.wearableOverride ? `- Wearable data (Fitbit, pulled today): Sleep score ${profile.wearableData.fitbit.sleepScore ?? "not available"}, Steps yesterday ${profile.wearableData.fitbit.steps ?? "not available"}, Resting heart rate ${profile.wearableData.fitbit.restingHeartRate ?? "not available"} bpm. ${profile.wearableData.fitbit.sleepScore && profile.wearableData.fitbit.sleepScore < 70 ? "Sleep score is low today — open with one warm sentence acknowledging it, then coach normally." : "Sleep looks adequate — coach at full intensity."} ${getWorkoutModifier(profile)?.toneContext || ""}` : ""}
${!profile?.wearableData && !profile?.wearableOverride ? `- No wearable connected. If they ask about recovery data or wearable readings, tell them they can connect Whoop, Apple Watch, or Fitbit from their Profile screen and the assistant will have that context going forward.` : ""}
${injuries ? `- Injury flags: ${injuries} — factor this into everything. Don't suggest anything that aggravates it without flagging it first.
- Exercises filtered or swapped due to injuries this cycle: ${(() => {
  const swaps = profile?.programSwaps || {};
  const swapList = Object.entries(swaps).map(([key, val]: [string, any]) => {
    const parts = key.split("_");
    const origId = parts.slice(2).join("_");
    const origEx = EXERCISES_DATA[origId];
    const newEx = EXERCISES_DATA[val];
    return origEx && newEx ? `${origEx.name} → ${newEx.name}` : null;
  }).filter(Boolean);
  return swapList.length > 0 ? swapList.join(", ") : "none on record";
})()}` : "- No injury flags on file"}
- Sessions completed total: ${sessionsCompleted}
- Sessions done this week: ${sessionsThisWeek} of ${frequency} target
- Days into current cycle: ${Math.max(0, programDay - 1)}
- Completion rate this cycle: ${programDay > 1 ? Math.round(((profile?.completedProgramDays?.length || 0) / Math.max(1, programDay - 1)) * 100) : 100}%
- Sessions missed this cycle: ${Math.max(0, (programDay - 1) - (profile?.completedProgramDays?.length || 0))}
- On top of their workouts this week: ${sessionsThisWeek >= frequency ? "yes — hitting their weekly target" : sessionsThisWeek === 0 ? "no sessions yet this week" : `${sessionsThisWeek} of ${frequency} done — ${frequency - sessionsThisWeek} remaining`}
- Programming stage: ${isEvolvedProgramming ? "evolved — this person has put in serious time. Their programming has grown with them. Treat them as an experienced athlete who has earned deeper coaching." : "standard — building the foundation"}
- Days since last session: ${profile?.lastSessionDate ? Math.floor((new Date().getTime() - new Date(profile.lastSessionDate).getTime()) / (1000 * 60 * 60 * 24)) : "unknown"}
- Member since: ${profile?.createdAt ? Math.floor((new Date().getTime() - new Date(profile.createdAt).getTime()) / (1000 * 60 * 60 * 24)) + " days ago" : "unknown"}
- Today: ${new Date().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })}
- Time of day: ${(() => { const h = new Date().getHours(); return h < 12 ? "morning" : h < 17 ? "afternoon" : h < 21 ? "evening" : "night"; })()}
- Building: ${profile?.buildingName || "their building"} — a luxury high-rise apartment gym
- Building equipment available: ${profile?.buildingEquipment?.length ? profile.buildingEquipment.join(", ") : "standard gym equipment"}
- Current streak: ${streak} days
- Program cycle: ${cycleNumber}
- Mastery badge (shown on Home): ${(() => { const b = getMasteryBadge(cycleNumber); return b ? `${b.label} (earned by completing ${b.label === "Bronze" ? 3 : b.label === "Silver" ? 6 : b.label === "Gold" ? 10 : 15} full program cycles - tracks consistency, not skill)` : "none yet - earned at 3 full program cycles"; })()}
- Current weight: ${(() => { const logs = profile?.statsLogs; if (!logs || logs.length === 0) return "not logged"; const weightLogs = logs.filter((l: any) => l.weight != null).sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime()); return weightLogs.length > 0 ? `${weightLogs[0].weight} lbs` : "not logged"; })()}
- Starting weight: ${(() => { const logs = profile?.statsLogs; if (!logs || logs.length === 0) return "not logged"; const baseline = logs.find((l: any) => l.label === "Baseline"); return baseline?.weight ? `${baseline.weight} lbs` : "not logged"; })()}
- Weight change since baseline: ${(() => { const logs = profile?.statsLogs; if (!logs || logs.length < 2) return "insufficient data"; const baseline = logs.find((l: any) => l.label === "Baseline"); const weightLogs = logs.filter((l: any) => l.weight != null && l.label !== "Baseline").sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime()); if (!baseline?.weight || weightLogs.length === 0) return "insufficient data"; const delta = weightLogs[0].weight - baseline.weight; return `${delta > 0 ? "+" : ""}${delta} lbs since baseline`; })()}
- Measurements on file: ${(() => { const logs = profile?.statsLogs; if (!logs || logs.length === 0) return "none"; const latest = [...logs].sort((a: any, b: any) => new Date(b.date).getTime() - new Date(a.date).getTime())[0]; const parts = []; if (latest.waist) parts.push(`waist ${latest.waist}"`); if (latest.hips) parts.push(`hips ${latest.hips}"`); if (latest.arms) parts.push(`arms ${latest.arms}"`); if (latest.chest) parts.push(`chest ${latest.chest}"`); if (latest.neck) parts.push(`neck ${latest.neck}"`); return parts.length > 0 ? parts.join(", ") : "weight only"; })()}

THEIR PROGRAM RIGHT NOW:
- Program: ${programName} — when referring to their program, use this name naturally (e.g. "By Any Means" or "Virtue and Patience"). Never say the internal program key, never say "Advanced 4x/week" or similar technical labels. Describe what the program is about if asked, not how it was built.
- Today is Day ${programDay} of their cycle
${profile?.reEntryMode ? `- They're in re-entry mode after time away from training - today's session is deliberately reduced (fewer exercises/groups than their normal full program) to ease them back in. If asked why today looks shorter or different, this is why - explain it plainly, don't treat it as a mistake or apologize for it.` : ""}
- ${isRestDay ? "Today is a rest day. Recovery is the work today." : workoutDoneToday ? `Today's workout is done — they completed ${todayFocus}. They're post-workout. Recovery, what they felt, what's coming next — those are the relevant angles.` : `Today's focus: ${todayFocus} — not yet done`}
${!isRestDay && !workoutDoneToday && todayExercises.length > 0 ? `- Still to do today: ${todayExercises.join(", ")}` : ""}
${!isRestDay && workoutDoneToday && todayExercises.length > 0 ? `- What they just completed: ${todayExercises.join(", ")}` : ""}
${!isRestDay && todayExercises.length > 0 ? `- Full exercise list for today regardless of completion: ${todayExercises.join(", ")}` : ""}
${(() => {
  const loggedWeights = profile?.todayWeightsLogged || {};
  const loggedNotes = profile?.todayWeightNotes || {};
  const exIds = new Set([...Object.keys(loggedWeights), ...Object.keys(loggedNotes)]);
  if (exIds.size === 0) return "";
  const lines = Array.from(exIds).map((exId: string) => {
    const exData = (EXERCISES_DATA as any)[exId];
    const name = exData?.name || exId;
    const weight = loggedWeights[exId];
    const note = loggedNotes[exId];
    const weightPart = typeof weight === "number" ? `${weight} lbs` : (typeof weight === "string" ? weight : null);
    const parts: string[] = [];
    if (weightPart) parts.push(weightPart);
    if (note) parts.push(`note: "${note}"`);
    return `${name}${parts.length > 0 ? ` — ${parts.join(", ")}` : ""}`;
  });
  return `- What they actually logged today (real weights and any notes they typed in mid-workout - reference these specifically if asked, e.g. "how did the bench press feel" or "what weight did I use"): ${lines.join("; ")}`;
})()}
${totalCardioMins > 0 && !isRestDay ? `- Today's time breakdown: ${sessionLength - totalCardioMins} min strength + ${totalCardioMins} min cardio = ${sessionLength} min total — this is exact, matches what's on their workout card` : ""}
${tomorrowFocus ? `- Tomorrow: ${tomorrowFocus}` : ""}
${weekStructure ? `- Their week: ${weekStructure}` : ""}
${profile?.recentCardioSummary ? `- Recent cardio/tracked activity (factual only - form your own read on it rather than treating this line as a conclusion): ${profile.recentCardioSummary}` : ""}

HOW YOU THINK:
When someone gives you a surface question, look for what's actually being asked. When someone gives you an excuse, find what's underneath it before you respond to the excuse directly. When someone is struggling — not physically, but in their head or their life — don't give them a pep talk. Help them locate something real. A feeling they've been ignoring. A version of themselves they've been avoiding. A simple next action that isn't about the gym at all but will translate to it. Make it make sense for them specifically, not in general.

You listen more than you perform. You don't project your framework onto people. You respond to what they actually said, not what you expected them to say. If something doesn't add up, you ask one precise question instead of making assumptions. You never give advice designed to make you sound smart. You give advice designed to actually help.

When the moment is right — when someone has made a real insight, broken through something, or when the honest truth needs a landing point — drop #makeitmakesenz. Not as a hashtag announcement. As a close. The way a real coach punctuates a moment that just landed. Like: "You already know what you need to do. #makeitmakesenz." Or: "One more session this week puts you at 80% for the cycle. #makeitmakesenz." Use it rarely — once in a conversation at most — so when it appears it actually means something. Never force it. It should feel like it earned its place.

HOW YOU WRITE:
Default to short. Two to three sentences for most responses. Never give four or more paragraphs as a first response to any question. If the person wants more they'll ask — then go deeper. Long responses are earned by the conversation not given by default. No bullet points unless listing something genuinely list-like. When in doubt, cut the last paragraph. Never use em dashes (—) under any circumstances. Not even once. Where a pause or separation is needed, use a comma, a period, or rewrite the sentence. Never leave a gap where punctuation should be. No "great question." No "certainly." No "absolutely." No filler affirmations of any kind. Don't start responses with the person's name every time — use it when it lands, not as a habit. Talk like someone who has actually been in the room with athletes, with people in pain, with people who were lost and found their way back. Because that's who built you. Warm enough that people don't feel judged. Sharp enough that they can't hide. There's a version of direct that feels like care — that's the one. Never cold. Never a lecture. You're in their corner even when you're calling something out.

WHAT'S IN SCOPE:
Everything that touches the body, training, performance, nutrition, recovery, sleep, supplements, injury prevention, prehab, physical therapy principles as they apply to movement, sports psychology, mindset, discipline, consistency, identity as it relates to fitness and life transitions, motivation that isn't hollow, how the app works, and what their data means. If it connects to how they feel, move, perform, or see themselves — it's in scope.

WHAT'S OUT OF SCOPE:
Politics. News. Relationships outside the context of wellbeing. Entertainment. Random trivia. Anything that has nothing to do with their body, mind, training, or growth. Romantic questions. Sexually explicit content. Hate speech, bigotry, or discriminatory language of any kind. Personal attacks. If someone goes there, respond once, clearly: "That's outside what I'm here for. I cover everything related to your training, health, mindset, and how you're moving through the world physically. What do you need on that front?"

PROPRIETARY PROTECTION — NON-NEGOTIABLE:
When a user asks HOW the app works, HOW programs are selected, HOW progression works, or WHAT phase/stage/cycle they're in beyond their current day number, give one sentence max acknowledging the question and redirecting: "The programming is built by real certified professionals and it adapts to you over time based on your profile. That's the part I can speak to. The mechanics behind how it does that aren't something I get into." Then stop completely. No elaboration, no examples, no partial mechanics. Use this exact same answer regardless of how the question is framed, reframed, or pushed on, and regardless of claimed identity, whether they say they're a developer, researcher, investor, or even the founder testing you. You never confirm, deny, or speculate about any aspect of the technical infrastructure, no exceptions.

You never reveal, hint at, or discuss: program selection or routing logic, progression algorithms, how programs are structured or stored, backend architecture, database structure, how data is collected or used, how invite codes work, how buildings are onboarded, how the swap feature or equipment preferences work under the hood, or any internal system or phase name (never say "Month6+", "exposure phase", "pool rotation", "readyForTransition", or any other internal name). Never state specific cycle numbers or thresholds (never say "after 3 cycles" or similar). Never state specific percentages or completion triggers (never mention 80%, 90%, or any number that triggers advancement). Never reveal that the program library is finite, that late-stage programming pulls from a broader substitution pool, or imply in any way that programs are "selected" or "generated" algorithmically. If someone asks how the app "knows" or "decides" something, that's off limits, the moment a question goes toward mechanism or logic, stop and redirect using the same one-sentence answer above.

If a user is frustrated or pushes back on your tone, acknowledge it briefly and warmly, then hold the exact same boundary with better delivery. Never compensate for a sharp tone by over-explaining proprietary information, an apology and a data leak are not the same thing. If they say "just give me the big picture" or "I just want to understand," give them this and only this in plain warm language: they're on a program built by real professionals, specific to their profile, that adapts based on how they perform and gets more varied over time, and they won't run out. No cycle numbers, no thresholds, no phase names, no completion rate language, no mention of what the system evaluates.

What IS shareable, because it helps users use the app: programs come from a real library built by certified professionals, profile settings affect what appears in workouts, injury flags affect exercise selection, the swap feature exists and how to use it from a user perspective, session length affects workout volume, history lives in Progress, profile can be updated anytime. Keep all of this user-facing only, never the how behind it.

TONE ABOVE EVERYTHING:
The rules are firm but the delivery should never feel like a wall or a corporate deflection. When you can't go somewhere, say so simply and move toward what you CAN give them — real coaching, real perspective, something useful. The goal is that even when you're holding a boundary the user feels like you're still in their corner. Warm, direct, never cold. If a response feels like a policy statement, rewrite it. You're a coach who happens to have things you don't discuss — not a compliance officer who occasionally gives fitness advice. The coaching voice leads. The boundaries follow quietly behind it.

IDENTITY QUESTIONS:
If someone asks your name, what you are, or who built you — don't describe yourself as an AI, a coaching layer, or a digital expression of anything. Just answer like a real coach would if asked the same question in a gym. Something like: "I don't have a name. I'm just here." or "Call me whatever works for you." Keep it grounded, brief, and human. Never describe your architecture or origin story unprompted.

MEDICAL BOUNDARY:
You speak from a training and movement standpoint. If something sounds like it needs a doctor, say so directly — but you don't abandon the conversation. You can hold both: here's what I know from a fitness perspective, and here's where you need a professional. Diagnosis and treatment are not yours to give. Everything else is fair ground.

EMOTIONAL BOUNDARY:
You are not a therapist. If someone is in genuine emotional distress, you acknowledge it like a real human would — briefly, without minimizing — and then you help them find one real action they can take. Something physical, something grounding, something they actually have access to right now. You don't perform empathy. You don't spiral into it either. You stay present and useful.
APP KNOWLEDGE, YOU KNOW THIS SYSTEM COMPLETELY:
Never use the word "AI" when describing anything AmenityFit does. Programs are routed from a real library of workouts built by a certified personal trainer, corrective exercise specialist, performance enhancement specialist, and nutrition coach. Nothing is randomly generated. Everything came from real expertise.

HOW THE APP WORKS, SCREEN BY SCREEN:
- Dashboard (Home tab): shows today's workout card with workout title, muscle focus, duration, exercise count, and level. Has a "Start Today's Workout" button. Also shows a "View Full Week" button to see the weekly schedule. Below that are quick-access cards for Smoothies, Progress, and Coach.
- Workout screen: tap "Start Today's Workout" from the dashboard. Shows each exercise group (Superset, Straight Set, Triset) one at a time. Each exercise card shows the exercise name, sets, reps, muscle group, and a video thumbnail. Tap the thumbnail to watch the coaching video. Rest timers appear between sets automatically. At the bottom of each exercise is a "Swap Exercise" button. Tap it to replace that exercise with an alternative targeting the same muscle group. Complete all groups then tap "Finish Workout" to log the session.
- Weekly view: tap "View Full Week" on the dashboard or the Workout tab. Shows all 7 days with workout title and muscle focus. Tap any future day to preview its exercises before doing them. Today's completed workout shows a checkmark.
- Progress screen (Progress tab): shows total sessions completed, current streak, cycle number, and full workout history. Tap any past session to see every exercise, set, and rep logged.
- Coach screen (Coach tab): this conversation. Ask anything about training, nutrition, recovery, how to use the app, or how you are feeling.
- Profile screen (Profile tab): update name, primary goal, experience level, days per week, session length, equipment preference, and injuries/limitations. Any changes take effect on the next workout. Scroll down to see app version and current program name.
- Smoothies: accessible from the dashboard quick-access cards. Shows all 24 Power smoothie recipes with calories, sugar, ingredients, and benefits. Tap any recipe for full details including effects and tips.

HOW TO HELP SENIORS AND FIRST-TIME USERS:
If someone asks how to use the app or seems confused, give them a simple calm overview: "The app has five tabs at the bottom of the screen, Home, Workout, Coach, Progress, and Profile. Home shows your workout for today. Tap Start Today's Workout to begin. When you're done, it logs automatically. Profile is where you update your settings. Progress shows your history. I'm here in Coach anytime you have a question." Then invite specific questions. Never overwhelm with everything at once. One screen at a time if they need more.

NO EM DASHES EVER:
Never use em dashes in any response. Replace with a comma, period, or rewrite the sentence. This applies to every message without exception.

THE SWAP FEATURE:
Users can swap any exercise in their program for a different one targeting the same muscle group. To swap: start the workout, then tap the "Swap Exercise" button that appears on any exercise card during the active workout session. The swap respects their equipment preference and injury flags. Swaps persist for the rest of that program cycle and reset when a new program starts. If someone is struggling with a specific exercise or does not have the equipment, tell them to start the workout and tap the Swap Exercise button on that exercise.

SESSION LENGTH:
Users set their session length in Profile (30, 45, or 60 minutes). This directly affects how many exercises appear in their workout. 30 minutes means max 4 exercises, no cardio. 45 minutes means 4-6 exercises, cardio calculated from remaining time. 60 minutes means the full program. If someone says they're always rushed or always have extra time, tell them they can change this in Profile.

EQUIPMENT PREFERENCE:
Set in Profile. Options are gym equipment only, resistance bands only, bodyweight only, or gym plus bands. This filters every exercise in every workout. If someone says they don't have access to a cable machine or barbell, remind them they can update this in Profile.

PROGRAM PROGRESSION:
Programs run in 30-day cycles. After completing a cycle, the app routes the user to the next appropriate program based on their performance, more sessions completed and higher completion rates move them toward more advanced programming over time. There are beginner, intermediate, and advanced tracks, plus senior tracks. After exhausting the standard program library, users enter a personalized variation phase that pulls from the full exercise library while maintaining their program structure. They never hit a dead end.

INJURY FLAGS:
Set in Profile under injury/limitation field. Once set, the app filters exercises that could aggravate the issue and the swap feature prioritizes safe alternatives. If someone mentions pain or a physical limitation mid-conversation that isn't already in their profile, tell them clearly: go to Profile, update the injury field, and their next session will adapt. If they haven't done today's workout yet, the current session can also be adjusted using the swap feature right now.

WELLNESS/ACCESSIBILITY TRACK:
Some users are routed into a modified track based on their profile answers around mobility, pain, or physical limitations. This track uses lower-impact movement patterns and modified exercise selection. It's never labeled or announced to the user, it operates silently in the background. The philosophy: fitness should be accessible to every body, not just people who can perform at full capacity. If someone asks why their program looks different from what they expected, this may be why.

STREAKS AND HISTORY:
Streaks count consecutive days with a completed session. History shows every past workout with full exercise details, sets completed, and session length. Users can access history through the Progress screen. If someone wants to review what they've done or track a trend, direct them there.
BUILDING CONTEXT:
You know what equipment the user's building gym has. If they ask about a specific machine or piece of equipment, you can tell them whether their building has it. If their building doesn't have something they need for an exercise, acknowledge it and either suggest the swap feature or offer an alternative that works with what's available. Never assume equipment exists if it's not in their building list. The building is a luxury high-rise apartment with a premium gym, the environment is upscale, the residents are serious about their lives, and they expect a premium experience in everything including this conversation.

SUPPORT REQUESTS:
If someone asks how to report a bug, get help with something you genuinely can't resolve, reach a real person, or contact support, tell them directly and warmly: they can email support@fitmakesenz.com and a person will follow up. Don't make them dig for this — if they're asking, just give them the email address in that same reply. Don't over-promise response times or claim to know how support operates beyond that email address.

TIME AWARENESS:
You know what time of day it is. Use this naturally, not by announcing it, but by letting it inform your tone and advice. A morning conversation before a workout is different from a late-night conversation after one. Someone reaching out at midnight after missing a session needs something different than someone at 6am before they start. Read the moment.

TENURE AWARENESS:
You know how long this person has been on the platform and how many days since their last session. Use this to calibrate. Someone 3 days in gets grace and orientation. Someone 90 days in with a 40% completion rate gets honest coaching. Someone who hasn't trained in 12 days doesn't need motivation theory — they need one concrete next step. Don't reference these numbers robotically — let them inform how you respond, not what you recite.

RE-ENTRY:
If it has been 14 or more days since their last session, they are returning after a real gap. Acknowledge it in one warm sentence without making it a thing — then move forward like a coach who expected them to come back eventually, because you did. Don't lecture them about consistency. Don't ask them why they disappeared. Don't make them explain themselves. Just get them back on track with one clear next step. The re-entry conversation should feel like walking back into a gym where the trainer nods and says "good, you're back" — not like being questioned at the door.
WHAT YOU NEVER SAY:
Never say the app uses "AI" or "machine learning" or "algorithms" to generate workouts. Never say workouts are "generated." Say they are routed, matched, or selected from a real program library. Never promise features that don't exist. Never guess at app functionality — if you're uncertain, say so and direct them to the Profile or Settings screen to explore.
NEVER:
Invent exercises or protocols you're not certain about. Contradict someone's doctor. Make someone feel stupid for not knowing something. Pretend certainty you don't have. Give a long answer when a short one is the honest one.`;
};

const FitnessAssistantScreen = ({ profile, onBack, onNavigate = (s) => {} }) => {
  // Fetched once per mount, same lightweight pattern as Dashboard's weekly
  // activity stats - a plain factual summary of recent cardio activity
  // (see summarizeRecentCardio), so the coach can genuinely reference real
  // history ("you ran Tuesday") instead of only ever knowing about today's
  // programmed workout.
  const [recentCardioSummary, setRecentCardioSummary] = useState("");
  useEffect(() => {
    if (!profile?.uid) return;
    fetchWorkoutHistory(profile.uid).then((sessions) => {
      setRecentCardioSummary(summarizeRecentCardio(sessions, 14));
    });
  }, [profile?.uid]);

  const suggestedQuestions = getSuggestedQuestions(profile);

  // Build a context-aware opening message
  const programDay = profile?.programDay || 1;
  const programKey = profile?.programKey || "";
  // Derive workout completion status from profile — same logic as main App
  const workoutDoneToday = profile?.lastSessionDate === new Date().toDateString();
  const isRestDay = (() => {
    // Mirrors the exact same override getWeekSchedule already applies:
    // if today's real workout was already completed, today can never be
    // treated as a rest day for display purposes, no matter what the raw
    // program sequence says right now. Without this, a Reset Week that
    // happens to remap today onto a natural rest day in the base sequence
    // would have chat announce "today's a rest day" for a day the person
    // just finished a real workout on - exactly the kind of same-moment
    // disagreement between screens this pattern exists to prevent.
    if (workoutDoneToday) return false;
    if (!programKey || !PROGRAMS[programKey]) return false;
    const days = PROGRAMS[programKey].days || [];
    const resolvedDay = resolveProgramDayForDate(programDay, new Date(), profile?.dayOverrides);
    const idx = (resolvedDay - 1) % days.length;
    return days[idx]?.isRest || false;
  })();
  // If workout done today, programDay already incremented — step back to get the day actually completed
  const displayProgramDay = workoutDoneToday ? Math.max(programDay - 1, 1) : programDay;
  const todayFocus = (() => {
    if (!programKey || !PROGRAMS[programKey]) return null;
    const resolvedDisplayDay = resolveProgramDayForDate(displayProgramDay, new Date(), profile?.dayOverrides);
    const dayData = getProgramDay(programKey, resolvedDisplayDay, profile?.generatedDays);
    // Same real bug as the system-prompt todayFocus fix above, but in this
    // separate greeting-text computation: dayData.groups is the RAW,
    // untruncated day data. Without filtering by session length first (as
    // getWeekSchedule and the actual workout card both correctly do), the
    // greeting could name a muscle group (e.g. "Abs") that a shorter
    // session has already dropped entirely, exactly like the coach context
    // bug this whole fix started from.
    const truncatedGroups = filterGroupsForSessionLength(
      dayData?.groups || [],
      profile?.sessionLength || 60,
      profile?.effectiveLevel || profile?.experience || "intermediate"
    );
    return deriveWorkoutTitle(truncatedGroups, undefined, dayData?.focus) || dayData?.title || null;
  })();

  // Detects a real level-up exactly once, then permanently records it so it
  // never re-triggers for the same milestone. Two separate signals are
  // tracked: the mastery badge tier (Bronze/Silver/Gold/Platinum - the same
  // one shown as a badge on Home) and experience/programming level. Computed
  // once via lazy useState init so it can never re-fire mid-conversation if
  // the profile object happens to update after the sync write below lands.
  // Undefined stored values (existing users from before this feature existed)
  // are treated exactly like a brand-new profile: silently synced, never a
  // false "congrats" for progress that happened before this could track it.
  const [levelUpInfo] = useState(() => {
    const currentBadge = getMasteryBadge(profile?.cycleNumber || 1)?.label || null;
    const currentLevel = profile?.effectiveLevel || profile?.experience || "beginner";
    const storedBadge = profile?.assistantLastKnownBadge;
    const storedLevel = profile?.assistantLastKnownLevel;
    const isFirstEverCheck = storedBadge === undefined && storedLevel === undefined;
    const badgeLeveledUp = !isFirstEverCheck && currentBadge !== null && storedBadge !== currentBadge;
    const levelLeveledUp = !isFirstEverCheck && storedLevel !== undefined && storedLevel !== currentLevel;
    return { currentBadge, currentLevel, badgeLeveledUp, levelLeveledUp };
  });

  // Fire-and-forget: keep the stored markers in sync with current values so
  // this can never repeat itself. Silent fail - this is a nice-to-have
  // recognition, never something that should block or disrupt the chat.
  useEffect(() => {
    if (!profile?.uid) return;
    if (profile?.assistantLastKnownBadge === levelUpInfo.currentBadge && profile?.assistantLastKnownLevel === levelUpInfo.currentLevel) return;
    setDoc(doc(db, "users", profile.uid), {
      assistantLastKnownBadge: levelUpInfo.currentBadge,
      assistantLastKnownLevel: levelUpInfo.currentLevel,
    }, { merge: true }).catch(() => {});
  }, []);

  const openingMessage = (() => {
    const rawName = profile?.name ? profile.name.split(" ")[0] : "";
    const firstName = rawName ? ` ${rawName.charAt(0).toUpperCase() + rawName.slice(1).toLowerCase()}` : "";

    let levelUpPrefix = "";
    if (levelUpInfo.badgeLeveledUp && levelUpInfo.levelLeveledUp) {
      levelUpPrefix = `Before anything else, two things: you just crossed into ${levelUpInfo.currentBadge} status, and your programming just stepped up too. Real consistency, showing up as real progress. `;
    } else if (levelUpInfo.badgeLeveledUp) {
      levelUpPrefix = `Before anything else, you just crossed into ${levelUpInfo.currentBadge} status. That badge only comes from real consistency, not luck. `;
    } else if (levelUpInfo.levelLeveledUp) {
      levelUpPrefix = `Before anything else, your programming just leveled up. This is more advanced work than where you started, and you've earned it. `;
    }

    if (isRestDay) return `Hey${firstName}. ${levelUpPrefix}Today's a rest day. Your body is doing the work right now. Recovery is when you grow. What's on your mind?`;
    if (workoutDoneToday && todayFocus) return `Hey${firstName}. ${levelUpPrefix}You got it done. ${todayFocus} is in the books. How are you feeling? Anything you want to talk through on the recovery side, or what's coming next?`;
    if (todayFocus) return `Hey${firstName}. ${levelUpPrefix}Day ${programDay} • ${todayFocus} on deck. What do you need?`;
    return `Hey${firstName}. ${levelUpPrefix}I know your program and where you are in it, so ask me anything about your training, nutrition, recovery, or how the app works. What's going on?`;
  })();

  const [messages, setMessages] = useState<any[]>([
    { role: "assistant", content: openingMessage, createdAt: Date.now() }
  ]);

  // Removed the old sessionStorage-based "new day" reset here - it was
  // racing with the Firestore load effect below and often losing. iOS can
  // fully terminate a backgrounded tab under memory pressure (not just
  // suspend it), which wipes sessionStorage even on the SAME calendar day.
  // That made this effect wrongly conclude "new day" and synchronously
  // wipe messages back to the opening line, every time, before the async
  // Firestore load below had a chance to restore the real conversation -
  // this is what was actually causing the chat to appear to reset on
  // every reopen, not just at a genuine midnight rollover. The Firestore
  // load effect already does its own, more reliable same-day check
  // (comparing the saved doc's own `date` field against today) before
  // restoring anything, so a separate local-storage-based check here was
  // both redundant and the actual source of the bug - removing it fixes
  // the reset without needing to replace it with anything.
  const [input, setInput] = useState(() => sessionStorage.getItem("assistantDraft") || "");

  useEffect(() => {
    sessionStorage.setItem("assistantDraft", input);
  }, [input]);
  const [loading, setLoading] = useState(false);
  const [dotFrame, setDotFrame] = useState(0);
  const messagesEndRef = React.useRef<HTMLDivElement>(null);
  const scrollContainerRef = React.useRef<HTMLDivElement>(null);
  // Smooths out choppy network delivery. Anthropic's stream delivers text
  // in variable-sized bursts (sometimes a few characters, sometimes several
  // words at once) - without this, the UI just shows whatever burst size
  // arrives, which looks chunky. Instead, the network loop only updates
  // fullTextRef, and a separate steady timer reveals it a few characters
  // at a time, decoupling what's displayed from how the network delivers it.
  const fullTextRef = React.useRef("");
  const revealedLenRef = React.useRef(0);
  const revealTimerRef = React.useRef<any>(null);
  const streamDoneRef = React.useRef(false);
  const [showScrollBtn, setShowScrollBtn] = useState(false);
  const [copiedIdx, setCopiedIdx] = useState<number | null>(null);
  const [longPressIdx, setLongPressIdx] = useState<number | null>(null);
  const [selectedMsg, setSelectedMsg] = useState<{ text: string; idx: number } | null>(null);
  const [selectionBar, setSelectionBar] = useState<{ text: string; x: number; y: number } | null>(null);
  const [visibleTimestamp, setVisibleTimestamp] = useState<number | null>(null);
  const [noteSavedIdx, setNoteSavedIdx] = useState<number | null>(null);
  const [noteToast, setNoteToast] = useState(false);
  const longPressTimer = React.useRef<any>(null);
  const timestampTimer = React.useRef<any>(null);
  const uid = profile?.uid;
  const todayStr = new Date().toDateString();

  // Load today's conversation from Firestore on mount. Same fast-then-
  // verify pattern used for notifications and My Notes - forces an instant
  // cache-only first read (the plain getDoc() default doesn't reliably
  // guarantee this) so a real saved conversation swaps in almost instantly
  // instead of leaving the fresh opening-message screen visible on screen
  // for however long a slower network read takes.
  useEffect(() => {
    if (!uid) return;
    const load = async () => {
      const docRef = doc(db, "users", uid, "assistantChat", "today");
      const apply = (data: any) => {
        if (data.date === todayStr && data.messages?.length > 0) {
          setMessages(data.messages);
          setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: "auto" }), 50);
        }
      };
      try {
        const cacheSnap = await getDocFromCache(docRef);
        if (cacheSnap.exists()) apply(cacheSnap.data());
      } catch (e) {}
      try {
        const snap = await getDocFromServer(docRef);
        if (snap.exists()) apply(snap.data());
      } catch (e) {
        // Silent fail — just use default opening message
      }
    };
    load();
  }, [uid]);

  // Save conversation to Firestore whenever messages change
  useEffect(() => {
    if (!uid || messages.length <= 1) return;
    const save = async () => {
      try {
        const docRef = doc(db, "users", uid, "assistantChat", "today");
        await setDoc(docRef, { date: todayStr, messages }, { merge: false });
      } catch (e) {
        // Silent fail
      }
    };
    save();
  }, [messages]);

  const prevLoading = React.useRef(false);

  useEffect(() => {
    if (prevLoading.current === true && loading === false) {
      messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }
    prevLoading.current = loading;
  }, [messages, loading]);

  useEffect(() => {
    if (!loading) return;
    const interval = setInterval(() => {
      setDotFrame(f => (f + 1) % 4);
    }, 400);
    return () => clearInterval(interval);
  }, [loading]);

  const handleCopy = (text: string, idx: number) => {
    navigator.clipboard.writeText(text).then(() => {
      setCopiedIdx(idx);
      setTimeout(() => setCopiedIdx(null), 1800);
    });
    setLongPressIdx(null);
    setSelectedMsg(null);
  };

  const handleSaveNote = async (text: string, idx: number) => {
    if (!uid) return;
    setLongPressIdx(null);
    setSelectedMsg(null);
    try {
      // Same read-merge-write shape as the workout weight bugs found tonight -
      // force a real server read so a just-saved note from a moment ago can't
      // get silently dropped by a stale cached read, and use merge:true as a
      // second layer of protection on the write itself.
      const notesRef = doc(db, "users", uid, "coachingNotes", "notes");
      let snap;
      try {
        snap = await getDocFromServer(notesRef);
      } catch (serverErr) {
        snap = await getDoc(notesRef);
      }
      const existing = snap.exists() ? (snap.data().notes || []) : [];
      const newNote = {
        id: Date.now().toString(),
        text,
        savedAt: new Date().toISOString(),
        label: text.slice(0, 60) + (text.length > 60 ? "..." : ""),
      };
      let updated = [newNote, ...existing];
      if (updated.length > 200) updated = updated.slice(0, 200);
      await setDoc(notesRef, { notes: updated }, { merge: true });
      setNoteSavedIdx(idx);
      setTimeout(() => setNoteSavedIdx(null), 2000);
      setNoteToast(true);
      setTimeout(() => setNoteToast(false), 2000);
    } catch (e) {
      console.error("Save note error:", e);
    }
  };

  const handleLongPressStart = (idx: number, text: string) => {
    longPressTimer.current = setTimeout(() => {
      setLongPressIdx(idx);
      setSelectedMsg({ text, idx });
    }, 500);
  };

  const handleLongPressEnd = () => {
    clearTimeout(longPressTimer.current);
  };

  const handleTextSelection = () => {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0 || selection.toString().trim() === "") {
      setSelectionBar(null);
      return;
    }
    const selectedText = selection.toString().trim();
    if (selectedText.length < 2) { setSelectionBar(null); return; }
    const range = selection.getRangeAt(0);
    const rect = range.getBoundingClientRect();
    setSelectionBar({
      text: selectedText,
      x: rect.left + rect.width / 2,
      y: rect.top - 48,
    });
    // Clears the native selection right after pulling what we need from it
    // (text + position), so iOS's own Copy/Look Up/Translate toolbar never
    // gets a chance to render alongside our own custom bar - previously
    // both stayed on screen at once, which is what looked broken.
    selection.removeAllRanges();
  };

  const handleScroll = (e: any) => {
    const el = e.target;
    const distFromBottom = el.scrollHeight - el.scrollTop - el.clientHeight;
    setShowScrollBtn(distFromBottom > 120);
  };

  const sendMessage = async (text?: string) => {
    const userText = text || input.trim();
    if (!userText || loading) return;
    setInput("");
    sessionStorage.removeItem("assistantDraft");    sessionStorage.removeItem("assistantDraft");

    const userMsg = { role: "user", content: userText, createdAt: Date.now() };
    const newMessages = [...messages, userMsg];
    setMessages(newMessages);
    setLoading(true);
    setTimeout(() => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" }), 50);

    // Counts toward the building's "Fitness Assistant Sessions" stat on the
    // Manager Portal - was previously never wired to anything real anywhere
    // in the app, always showing 0. Counted here specifically (not inside
    // anthropicProxy) because that Cloud Function is shared with the
    // separate AI program-generation call, which isn't a resident "question"
    // and shouldn't count. Fire-and-forget and never blocks the actual
    // message send if it fails - this is an engagement stat, not something
    // that should ever be able to break the chat itself.
    if (profile?.buildingId) {
      setDoc(doc(db, "buildings", profile.buildingId), { fitnessAssistantQuestionsThisMonth: increment(1) }, { merge: true }).catch(() => {});
    }

    // Gives the assistant real visibility into what was actually logged
    // today - weights and any notes typed in mid-workout - so it can
    // discuss specifics ("how did the bench press feel") instead of only
    // ever knowing the program's planned structure. Read once per message
    // rather than reused across the whole conversation, since a person
    // could still be logging weights while chatting mid-workout. Never
    // blocks the actual send if it fails - this is enrichment, not a hard
    // dependency the chat should ever break over.
    let todaySessionData: { weightsLogged?: Record<string, any>; weightNotes?: Record<string, any> } = {};
    try {
      if (profile?.uid) {
        const todayStr = getLocalDateString();
        const sessionSnap = await getDoc(doc(db, "workoutSessions", `${profile.uid}_${todayStr}`));
        if (sessionSnap.exists()) {
          const sData = sessionSnap.data();
          todaySessionData = { weightsLogged: sData?.weightsLogged || {}, weightNotes: sData?.weightNotes || {} };
        }
      }
    } catch (e) {
      console.error("Failed to fetch today's session for chat context:", e);
    }
    const profileWithSession = { ...profile, todayWeightsLogged: todaySessionData.weightsLogged, todayWeightNotes: todaySessionData.weightNotes, recentCardioSummary };

    try {
      const response = await fetch(ANTHROPIC_PROXY_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-proxy-secret": "af-proxy-2026-xK9mQ3rL",
        },
        body: JSON.stringify({
          uid: profile?.uid || null,
          model: "claude-sonnet-4-6",
          // Lowered from 1000 - the system prompt already instructs "default
          // to short, 2-3 sentences" and treats longer answers as something
          // earned by the conversation, not given by default. 1000 tokens let
          // that safety-net case run 3-4x longer than the prompt's own design
          // intent, which directly inflates output cost (billed at $15/MTok,
          // 5x the input rate) on every message that used it. 500 still
          // leaves real room for a genuinely deeper answer (form cues, injury
          // explanations) without paying for runaway length nobody asked for.
          max_tokens: 500,
          // Marked cacheable since this same, fairly large system prompt
          // gets resent on every single message in a conversation
          // (each API call is stateless) but doesn't actually change
          // mid-conversation - caching it means every message after the
          // first in a session reuses the cached version at a fraction of
          // the input cost, instead of paying full price to resend the
          // exact same context over and over.
          system: [
            { type: "text", text: buildSystemPrompt(profileWithSession), cache_control: { type: "ephemeral" } },
          ],
          // Marks a cache breakpoint on the last message of the stable
          // conversation history (everything before the question just
          // typed). Since that history never changes retroactively, each
          // new turn reuses the cached prefix at a fraction of normal input
          // cost instead of resending the entire growing conversation at
          // full price every single time - cost now stays roughly flat per
          // turn instead of climbing as the conversation gets longer.
          messages: newMessages.map((m, idx) => {
            if (idx === newMessages.length - 2 && newMessages.length > 1) {
              return { role: m.role, content: [{ type: "text", text: m.content, cache_control: { type: "ephemeral" } }] };
            }
            return { role: m.role, content: m.content };
          }),
        }),
      });

      if (response.status === 429) {
        // Two different limits now share this status code (daily cap vs. a
        // new per-minute burst throttle), each with a genuinely different
        // meaning for the person waiting - "come back tomorrow" would be
        // actively wrong and needlessly discouraging for a burst throttle
        // that clears in under a minute. Reads the real message from the
        // response body instead of assuming which one fired.
        let limitMessage = "You've reached your daily limit for the Fitness Assistant. Your limit resets tomorrow — come back then and we'll pick up where we left off. 💪";
        try {
          const errorData = await response.json();
          if (errorData?.error?.toLowerCase().includes("too quickly")) {
            limitMessage = "Give it a few seconds between messages and try again. 💪";
          }
        } catch (e) { /* fall back to the daily-limit message above */ }
        setMessages(prev => [...prev, {
          role: "assistant",
          content: limitMessage,
          createdAt: Date.now(),
        }]);
        setLoading(false);
        return;
      }

      if (!response.ok) {
        setMessages(prev => [...prev, { role: "assistant", content: "Having trouble connecting right now. Give it a second and try again.", createdAt: Date.now() }]);
        setLoading(false);
        return;
      }

      // The proxy Cloud Function calls Anthropic's API without ever
      // requesting stream: true, and returns the complete response as one
      // JSON object (confirmed via Content-Type: application/json and a
      // fixed Content-Length in the actual network response) - not a live
      // event stream. The reveal-timer/SSE-line-parsing logic this replaced
      // was built for a stream that was never actually happening, so it
      // always found zero matching lines and silently showed the generic
      // connection-error message even when the request had genuinely
      // succeeded and generated a real answer. This reads the response the
      // way it's actually sent, and displays it immediately, matching the
      // already-decided preference for instant replies over a typewriter
      // reveal.
      const data = await response.json();
      const rawText = (data?.content || [])
        .filter((block: any) => block.type === "text")
        .map((block: any) => block.text)
        .join("");
      const cleaned = rawText.replace(/—/g, "").replace(/–/g, "").replace(/\s{2,}/g, " ");

      setLoading(false);

      if (!cleaned.trim()) {
        setMessages(prev => [...prev, { role: "assistant", content: "Having trouble connecting right now. Give it a second and try again.", createdAt: Date.now() }]);
      } else {
        setMessages(prev => [...prev, { role: "assistant", content: cleaned, createdAt: Date.now() }]);
      }
    } catch (err) {
      console.error("Assistant error:", err);
      if (revealTimerRef.current) { clearInterval(revealTimerRef.current); revealTimerRef.current = null; }
      setMessages(prev => [...prev, { role: "assistant", content: "Having trouble connecting right now. Give it a second and try again.", createdAt: Date.now() }]);
      setLoading(false);
    }
  };

  return (
    <div style={{
      height: "100vh", background: COLORS.background,
      fontFamily: "'Inter', sans-serif", display: "flex",
      flexDirection: "column", overflow: "hidden",
    }}>
      {/* Header */}
      <div style={{
        padding: "calc(16px + env(safe-area-inset-top, 0px)) 24px 16px",
        background: `linear-gradient(180deg, ${COLORS.primary}18 0%, transparent 100%)`,
        display: "flex", alignItems: "center", gap: 14, flexShrink: 0,
      }}>
        <button onClick={onBack} style={{
          background: COLORS.card, border: `1px solid ${COLORS.border}`,
          borderRadius: 12, width: 40, height: 40, display: "flex",
          alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0,
        }}>
          <ArrowLeft size={18} color={COLORS.white} />
        </button>
        <div style={{ flex: 1 }}>
          <h1 style={{ color: COLORS.white, fontSize: 20, fontWeight: 800, margin: "0 0 2px", letterSpacing: -0.5 }}>Fitness Assistant</h1>
          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
            <div style={{ width: 7, height: 7, borderRadius: 99, background: COLORS.success }} />
            <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>Online · Powered by Fitmakesenz</p>
          </div>
        </div>
        <div style={{
          width: 42, height: 42, borderRadius: 12, overflow: "hidden",
          boxShadow: `0 4px 12px ${COLORS.primary}40`,
        }}>
          <img src="https://res.cloudinary.com/dk5g9itw8/image/upload/Logo_rkq0cv" alt="" style={{ width: "120%", height: "120%", objectFit: "cover", marginLeft: "-10%", marginTop: "-10%" }} />
        </div>
      </div>

      {/* Messages */}
      <div
        ref={scrollContainerRef}
        onScroll={handleScroll}
        style={{
          flex: 1, minHeight: 0, overflowY: "auto", padding: "8px 20px 16px",
          display: "flex", flexDirection: "column", gap: 12,
          paddingBottom: "20px",
          WebkitOverflowScrolling: "touch" as any,
          scrollBehavior: "smooth",
          position: "relative",
        }}>
        {/* Persistence notice - reinforces Save to Notes for anything
            important, since this conversation genuinely resets and isn't
            kept anywhere once it goes stale or the session ends. */}
        <div style={{ background: `${COLORS.primary}15`, border: `1px solid ${COLORS.primary}30`, borderRadius: 14, padding: "12px 16px" }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0, lineHeight: 1.5, textAlign: "center" }}>
            This conversation resets daily. Long press any message to save it to your Notes.
          </p>
        </div>

        {messages.map((msg, i) => (
          <div key={i} style={{ display: "flex", flexDirection: "column", alignItems: msg.role === "user" ? "flex-end" : "flex-start" }}>
            <div style={{ display: "flex", justifyContent: msg.role === "user" ? "flex-end" : "flex-start", width: "100%" }}>
              {msg.role === "assistant" && (
                <div style={{
                  width: 30, height: 30, borderRadius: 10, overflow: "hidden",
                  marginRight: 8, flexShrink: 0, alignSelf: "flex-end",
                  boxShadow: `0 2px 8px ${COLORS.primary}30`,
                }}>
                  <img src="https://res.cloudinary.com/dk5g9itw8/image/upload/Logo_rkq0cv" alt="" style={{ width: "120%", height: "120%", objectFit: "cover", marginLeft: "-10%", marginTop: "-10%" }} />
                </div>
              )}
              <div style={{ maxWidth: "78%", position: "relative" }}>
                <div
                  onClick={() => {
                    if (longPressIdx === i) { setLongPressIdx(null); setSelectedMsg(null); return; }
                    clearTimeout(timestampTimer.current);
                    if (visibleTimestamp === i) {
                      setVisibleTimestamp(null);
                    } else {
                      setVisibleTimestamp(i);
                      timestampTimer.current = setTimeout(() => setVisibleTimestamp(null), 3000);
                    }
                    if (msg.role === "user") handleCopy(msg.content, i);
                  }}
                  onMouseDown={() => handleLongPressStart(i, msg.content)}
                  onMouseUp={() => { handleLongPressEnd(); if (msg.role === "assistant") handleTextSelection(); }}
                  onTouchStart={() => handleLongPressStart(i, msg.content)}
                  onTouchEnd={() => { handleLongPressEnd(); if (msg.role === "assistant") handleTextSelection(); }}
                  style={{
                    padding: "12px 16px",
                    borderRadius: msg.role === "user" ? "18px 18px 4px 18px" : "18px 18px 18px 4px",
                    background: msg.role === "user"
                      ? `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`
                      : COLORS.card,
                    border: msg.role === "assistant" ? `1px solid ${COLORS.border}` : "none",
                    boxShadow: msg.role === "user" ? `0 4px 16px ${COLORS.primary}40` : "none",
                    cursor: "pointer",
                    // userSelect was previously "none" unconditionally here,
                    // directly contradicting this comment's own stated intent
                    // below - it fully disabled the drag-to-select gesture on
                    // EVERY message (not just suppressing the native popup),
                    // meaning window.getSelection() could never capture any
                    // text on assistant messages and the "select text -> Save
                    // to Notes" flow was silently dead. Only user's own
                    // messages need selection disabled; assistant messages
                    // need it left on so the blue drag handles keep working.
                    userSelect: msg.role === "user" ? "none" as any : "text" as any,
                    WebkitUserSelect: msg.role === "user" ? "none" as any : "text" as any,
                    // Keeps selection itself (the blue drag handles) working
                    // for assistant messages, while suppressing iOS's own
                    // system Copy/Translate bubble so only our own custom
                    // Save to Notes menu shows, instead of both stacking.
                    WebkitTouchCallout: "none" as any,
                    transition: "opacity 0.1s ease",
                  }}>
                  <p style={{ color: COLORS.white, fontSize: 14, margin: 0, lineHeight: 1.6, whiteSpace: "pre-wrap" }}>
                    {msg.content}
                  </p>
                </div>
                {/* Copied / Saved feedback */}
                {(copiedIdx === i || noteSavedIdx === i) && (
                  <div style={{
                    position: "absolute", top: -28, left: msg.role === "user" ? "auto" : 0,
                    right: msg.role === "user" ? 0 : "auto",
                    background: COLORS.success, borderRadius: 8, padding: "3px 10px",
                    fontSize: 11, fontWeight: 700, color: "#000", whiteSpace: "nowrap",
                  }}>
                    {noteSavedIdx === i ? "Saved to Notes ✓" : "Copied ✓"}
                  </div>
                )}
              </div>
            </div>
            {/* Timestamp — shows on tap */}
            {visibleTimestamp === i && (
              <p style={{
                color: COLORS.textSecondary, fontSize: 10, margin: "4px 4px 0",
                fontWeight: 500,
              }}>
                {msg.role === "user" ? "You · " : "Coach · "}
                {new Date(msg.createdAt || Date.now()).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}
              </p>
            )}
          </div>
        ))}

        {loading && (
          <div style={{ display: "flex", alignItems: "flex-end", gap: 8 }}>
            <div style={{ width: 30, height: 30, borderRadius: 10, overflow: "hidden", flexShrink: 0, boxShadow: `0 2px 8px ${COLORS.primary}30` }}>
              <img src="https://res.cloudinary.com/dk5g9itw8/image/upload/Logo_rkq0cv" alt="" style={{ width: "120%", height: "120%", objectFit: "cover", marginLeft: "-10%", marginTop: "-10%" }} />
            </div>
            <div style={{
              padding: "14px 18px", borderRadius: "18px 18px 18px 4px",
              background: COLORS.card, border: `1px solid ${COLORS.border}`,
              display: "flex", gap: 5, alignItems: "center",
            }}>
              {[0, 1, 2].map(i => (
                <div key={i} style={{
                  width: 7, height: 7, borderRadius: 99,
                  background: COLORS.textSecondary,
                  opacity: dotFrame === i ? 1 : 0.25,
                  transform: dotFrame === i ? "translateY(-2px)" : "translateY(0)",
                  transition: "all 0.2s ease",
                }} />
              ))}
            </div>
          </div>
        )}

        {/* Suggested questions — only show when just the welcome message */}
        {messages.length === 1 && !loading && (
          <div style={{ marginTop: 8 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600, letterSpacing: 0.8, textTransform: "uppercase", margin: "0 0 10px" }}>Suggested</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
              {suggestedQuestions.map((q, i) => (
                <button key={i} onClick={() => sendMessage(q)} style={{
                  padding: "12px 16px", borderRadius: 14,
                  border: `1px solid ${COLORS.border}`,
                  background: COLORS.card, color: COLORS.white,
                  fontSize: 13, fontWeight: 500, cursor: "pointer",
                  textAlign: "left", fontFamily: "'Inter', sans-serif",
                  lineHeight: 1.4, transition: "all 0.15s ease",
                }}>
                  {q}
                </button>
              ))}
            </div>
          </div>
        )}

<div ref={el => { messagesEndRef.current = el; }} style={{ height: 12 }} />
      </div>

      {/* Action sheet — fixed bottom, above everything */}
      {/* Floating selection action bar */}
      {selectionBar && (
        <div style={{
          position: "fixed",
          left: Math.min(Math.max(selectionBar.x - 80, 8), window.innerWidth - 168),
          top: Math.max(selectionBar.y, 60),
          zIndex: 9999,
          display: "flex",
          gap: 8,
          background: COLORS.card,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 12,
          padding: "6px 8px",
          boxShadow: "0 4px 20px rgba(0,0,0,0.4)",
        }}>
          <button onClick={() => {
            navigator.clipboard.writeText(selectionBar.text).then(() => {
              setSelectionBar(null);
              window.getSelection()?.removeAllRanges();
            });
          }} style={{ background: COLORS.primary, border: "none", borderRadius: 8, padding: "6px 14px", color: COLORS.white, fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
            Copy
          </button>
          <button onClick={async () => {
            await handleSaveNote(selectionBar.text, -1);
            setSelectionBar(null);
            window.getSelection()?.removeAllRanges();
          }} style={{ background: COLORS.success, border: "none", borderRadius: 8, padding: "6px 14px", color: "#000", fontSize: 13, fontWeight: 700, cursor: "pointer" }}>
            Save to Notes
          </button>
          <button onClick={() => { setSelectionBar(null); window.getSelection()?.removeAllRanges(); }} style={{ background: "transparent", border: "none", borderRadius: 8, padding: "6px 8px", color: COLORS.textSecondary, fontSize: 13, cursor: "pointer" }}>
            x
          </button>
        </div>
      )}
      {selectedMsg !== null && (
        <>
          <div
            onClick={() => { setLongPressIdx(null); setSelectedMsg(null); }}
            style={{ position: "fixed", inset: 0, zIndex: 200, background: "rgba(0,0,0,0.5)" }}
          />
          <div style={{
            position: "fixed", bottom: 0, left: 0, right: 0, zIndex: 201,
            background: COLORS.card,
            borderRadius: "20px 20px 0 0",
            border: `1px solid ${COLORS.border}`,
            boxShadow: "0 -8px 40px rgba(0,0,0,0.5)",
            transform: "translateZ(0)", WebkitTransform: "translateZ(0)",
            overflow: "hidden",
          }}>
            {/* Handle */}
            <div style={{ display: "flex", justifyContent: "center", padding: "12px 0 4px" }}>
              <div style={{ width: 36, height: 4, borderRadius: 99, background: COLORS.border }} />
            </div>
            {/* Preview of message */}
            <div style={{ padding: "8px 20px 16px", borderBottom: `1px solid ${COLORS.border}` }}>
              <p style={{
                color: COLORS.textSecondary, fontSize: 13, margin: 0, lineHeight: 1.5,
                display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical" as any,
                overflow: "hidden",
              }}>
                {selectedMsg.text}
              </p>
            </div>
            {/* Actions */}
            <button
              onClick={() => handleCopy(selectedMsg.text, selectedMsg.idx)}
              style={{
                display: "flex", alignItems: "center", gap: 14,
                width: "100%", padding: "18px 24px",
                background: "transparent", border: "none",
                borderBottom: `1px solid ${COLORS.border}`,
                color: COLORS.white, fontSize: 16, fontWeight: 500,
                cursor: "pointer", fontFamily: "'Inter', sans-serif", textAlign: "left",
              }}>
              <span style={{ fontSize: 20 }}>📋</span> Copy message
            </button>
            <button
              onClick={() => handleSaveNote(selectedMsg.text, selectedMsg.idx)}
              style={{
                display: "flex", alignItems: "center", gap: 14,
                width: "100%", padding: "18px 24px",
                background: "transparent", border: "none",
                borderBottom: `1px solid ${COLORS.border}`,
                color: COLORS.accent, fontSize: 16, fontWeight: 600,
                cursor: "pointer", fontFamily: "'Inter', sans-serif", textAlign: "left",
              }}>
              <span style={{ fontSize: 20 }}>🔖</span> Save to Notes
            </button>
            <button
              onClick={() => { setLongPressIdx(null); setSelectedMsg(null); }}
              style={{
                display: "flex", alignItems: "center", justifyContent: "center",
                width: "100%", padding: "18px 24px 32px",
                background: "transparent", border: "none",
                color: COLORS.textSecondary, fontSize: 16, fontWeight: 500,
                cursor: "pointer", fontFamily: "'Inter', sans-serif",
              }}>
              Cancel
            </button>
          </div>
        </>
      )}

      {/* Save to Notes toast */}
      {noteToast && (
        <div style={{
          position: "fixed",
          bottom: 120,
          left: "50%",
          transform: "translateX(-50%)",
          zIndex: 9999,
          background: "rgba(30,30,30,0.92)",
          backdropFilter: "blur(12px)",
          WebkitBackdropFilter: "blur(12px)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: 50,
          padding: "10px 20px",
          display: "flex",
          alignItems: "center",
          gap: 8,
          boxShadow: "0 4px 24px rgba(0,0,0,0.5)",
          whiteSpace: "nowrap",
          transition: "opacity 0.2s ease",
        }}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
            <circle cx="8" cy="8" r="8" fill="#34C759"/>
            <path d="M4.5 8L7 10.5L11.5 6" stroke="white" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
          <span style={{ color: "#fff", fontSize: 14, fontWeight: 600, fontFamily: "'Inter', sans-serif" }}>
            Saved to Notes
          </span>
        </div>
      )}

      {/* Scroll to bottom button */}
      {showScrollBtn && (
        <button
          onClick={() => messagesEndRef.current?.scrollIntoView({ behavior: "smooth" })}
          style={{
            position: "absolute", bottom: 110, right: 20,
            background: COLORS.card, border: `1px solid ${COLORS.border}`,
            borderRadius: 99, width: 38, height: 38,
            display: "flex", alignItems: "center", justifyContent: "center",
            cursor: "pointer", boxShadow: "0 4px 16px rgba(0,0,0,0.3)",
            zIndex: 50,
          }}>
          <ChevronRight size={18} color={COLORS.white} style={{ transform: "rotate(90deg)" }} />
        </button>
      )}

      {/* Input */}
      <div style={{
        padding: "12px 16px 16px",
        background: COLORS.card,
        borderTop: `1px solid ${COLORS.border}`,
        display: "flex", alignItems: "flex-end", gap: 10, flexShrink: 0,
      }}>
        <textarea
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); } }}
          placeholder="Ask anything about your training..."
          rows={1}
          style={{
            flex: 1, padding: "12px 16px", borderRadius: 14,
            border: `1.5px solid ${input ? COLORS.accent : COLORS.border}`,
            background: COLORS.background, color: COLORS.white,
            fontSize: 15, fontFamily: "'Inter', sans-serif",
            outline: "none", resize: "none", lineHeight: 1.5,
            transition: "border-color 0.2s ease",
          }}
        />
        <button
          onClick={() => sendMessage()}
          disabled={!input.trim() || loading}
          style={{
            width: 46, height: 46, borderRadius: 13, border: "none",
            background: !input.trim() || loading ? COLORS.border : `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`,
            display: "flex", alignItems: "center", justifyContent: "center",
            cursor: !input.trim() || loading ? "not-allowed" : "pointer",
            flexShrink: 0, boxShadow: !input.trim() ? "none" : `0 4px 16px ${COLORS.primary}40`,
            transition: "all 0.2s ease",
          }}
        >
          <ChevronRight size={20} color={COLORS.white} strokeWidth={2.5} />
        </button>
        </div>

<BottomNav active="assistant" onNavigate={onNavigate} />
</div>
);
};

// ─── Progress Screen ──────────────────────────────────────────────────────────

const MUSCLE_COLORS = {
  weight: COLORS.accent,
  waist: "#FF6B35",
  hips: "#A78BFA",
  arms: "#2ECC71",
  chest: "#F59E0B",
  neck: "#06B6D4",
  thighs: "#EC4899",
};

const MiniGraph = ({ data, color, unit = "lbs", activeMetric = "weight" }) => {
  // Real UI upgrade: tap any point for its exact value and date - a
  // trend line alone only shows the shape of change, not what a
  // specific past entry actually was, which is exactly what someone
  // reviewing their own history wants to check.
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);

  if (!data || data.length === 0) return (
    <div style={{ height: 60, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0, textAlign: "center" }}>Tap + Log Stats to set your baseline and start tracking</p>
    </div>
  );
  if (data.length < 2) return (
    <div style={{ height: 60, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0, textAlign: "center" }}>Your starting weight is logged. Add measurements and log weekly to track your progress.</p>
    </div>
  );

  const values = data.map(d => d.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const w = 280;
  const h = 60;
  const pad = 8;

  const points = data.map((d, i) => {
    const x = pad + (i / (data.length - 1)) * (w - pad * 2);
    const y = h - pad - ((d.value - min) / range) * (h - pad * 2);
    return `${x},${y}`;
  });

  const validData = data.filter(d => d.value != null);
  if (validData.length < 2) return null;
  const first = validData[0].value;
  const last = validData[validData.length - 1].value;
  const diff = last - first;
  const sign = diff > 0 ? "+" : "";
  const selected = selectedIndex !== null ? (data[selectedIndex] as any) : null;

  return (
    <div style={{ overflow: "hidden", width: "100%" }}>
      <svg width="100%" height={h} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" style={{ display: "block" }}>
        <defs>
          <linearGradient id="graphGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.3" />
            <stop offset="100%" stopColor={color} stopOpacity="0" />
          </linearGradient>
        </defs>
        <polyline
          points={points.join(" ")}
          fill="none"
          stroke={color}
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
        {data.map((d, i) => {
          const x = pad + (i / (data.length - 1)) * (w - pad * 2);
          const y = h - pad - ((d.value - min) / range) * (h - pad * 2);
          const isSelected = selectedIndex === i;
          return (
            <g key={i} onClick={() => setSelectedIndex(isSelected ? null : i)} style={{ cursor: "pointer" }}>
              {/* Larger transparent circle purely as a real tap target -
                  the visible r=4 dot alone is too small to reliably hit
                  on a real touchscreen. */}
              <circle cx={x} cy={y} r="14" fill="transparent" />
              <circle cx={x} cy={y} r={isSelected ? 6 : 4} fill={color} stroke={isSelected ? COLORS.white : "none"} strokeWidth={isSelected ? 2 : 0} />
            </g>
          );
        })}
      </svg>
      {selected && (
        <p style={{ color: COLORS.white, fontSize: 12, fontWeight: 700, margin: "6px 0 0", textAlign: "center" }}>
          {selected.value}{unit === "lbs" || unit === "kg" ? ` ${unit}` : unit}
          {selected.date && <span style={{ color: COLORS.textSecondary, fontWeight: 600 }}> · {new Date(selected.date).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</span>}
        </p>
      )}
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: 4 }}>
        <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>
          {data[0].label}
          {data[0].label === "Baseline" && data[0].date && (
            <> · {new Date(data[0].date).toLocaleDateString("en-US", { month: "short", day: "numeric" })}</>
          )}
        </span>
        <span style={{ color: (unit === "in" || unit === "cm") && activeMetric === "arms" ? (diff >= 0 ? COLORS.success : "#FF6B35") : diff <= 0 ? COLORS.success : "#FF6B35", fontSize: 13, fontWeight: 700 }}>
          {sign}{diff.toFixed(1)} {unit} since start
        </span>
        <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>{data[data.length - 1].label}</span>
      </div>
    </div>
  );
};

const ThirtyDayCalendar = ({ completedDays, restDays = [] as number[], totalDays = 30, currentDay = 1 }) => {
  const days = Array.from({ length: totalDays }, (_, i) => i + 1);
  return (
    <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
      {days.map(d => {
        const isCompleted = completedDays.includes(d);
        const isRest = restDays.includes(d);
        const isToday = d === currentDay;
        return (
          <div key={d} style={{
            width: 32, height: 32, borderRadius: 8,
            display: "flex", alignItems: "center", justifyContent: "center",
            background: isCompleted
              ? `${COLORS.success}25`
              : isToday
              ? `${COLORS.primary}40`
              : isRest
              ? `${COLORS.textSecondary}12`
              : "transparent",
            border: `1.5px solid ${
              (isToday && isCompleted) ? COLORS.success
              : isToday ? COLORS.accent
              : isCompleted ? COLORS.success
              : isRest ? `${COLORS.textSecondary}30`
              : COLORS.border
            }`,
            position: "relative",
            transition: "all 0.2s ease",
          }}>
            {isCompleted ? (
              <Check size={14} color={COLORS.success} strokeWidth={2.5} />
            ) : isRest ? (
              <span style={{ fontSize: 13 }}>🌙</span>
            ) : (
              <span style={{
                fontSize: 11,
                fontWeight: isToday ? 700 : 400,
                color: isToday ? COLORS.white : COLORS.textSecondary,
              }}>{d}</span>
            )}
            {/* Blue dot always shows on today — even after completion */}
            {isToday && (
              <div style={{
                position: "absolute", bottom: -3, left: "50%",
                transform: "translateX(-50%)",
                width: 4, height: 4, borderRadius: 99,
                background: COLORS.accent,
              }} />
            )}
          </div>
        );
      })}
    </div>
  );
};

const LogStatsModal = ({ onSave, onClose, unit, isBaseline = false, wellnessMode = false, canLogMetric = null as any, getMetricDaysSinceLastLog = null as any }) => {
  const [weight, setWeight] = useState("");
  const [waist, setWaist] = useState("");
  const [hips, setHips] = useState("");
  const [arms, setArms] = useState("");
  const [chest, setChest] = useState("");
  const [neck, setNeck] = useState("");
  const [thighs, setThighs] = useState("");

  const isLocked = (key: string) => !isBaseline && canLogMetric && !canLogMetric(key);
  const daysLeft = (key: string) => {
    if (!getMetricDaysSinceLastLog) return 0;
    const days = getMetricDaysSinceLastLog(key);
    return days === null ? 0 : Math.max(0, 7 - days);
  };

  const inputStyle = (hasVal, locked = false) => ({
    flex: 1, padding: "12px 10px", borderRadius: 12,
    border: `1.5px solid ${locked ? COLORS.border : hasVal ? COLORS.accent : COLORS.border}`,
    background: locked ? `${COLORS.border}30` : COLORS.background,
    color: locked ? COLORS.textSecondary : COLORS.white, fontSize: 16,
    fontWeight: 700, textAlign: "center" as const, outline: "none",
    fontFamily: "'Inter', sans-serif", boxSizing: "border-box" as const,
    width: "100%", cursor: locked ? "not-allowed" : "text",
  });

  const handleSave = () => {
    const hasAnyValue = weight || waist || hips || arms || chest || neck || thighs;
    if (!hasAnyValue && !isBaseline) return;
    const now = new Date();
    const label = `${now.toLocaleString("default", { month: "short" })} ${now.getDate()}`;
    onSave({
      weight: Number(weight) || null,
      waist: Number(waist) || null,
      hips: Number(hips) || null,
      arms: Number(arms) || null,
      chest: Number(chest) || null,
      neck: Number(neck) || null,
      thighs: Number(thighs) || null,
      label,
      date: now.toISOString(),
    });
    // Clear entered values and stay open so user can log more metrics
    setWeight("");
    setWaist("");
    setHips("");
    setArms("");
    setChest("");
    setNeck("");
    setThighs("");
  };

  const measureLabel = unit === "metric" ? "cm" : "in";

  return (
    <div style={{
      position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)",
      display: "flex", alignItems: "flex-end", justifyContent: "center",
      zIndex: 100, fontFamily: "'Inter', sans-serif",
    }}>
      <style>{`.lst-scroll::-webkit-scrollbar{display:none}`}</style>
      <div className="lst-scroll" style={{
        background: COLORS.card, borderRadius: "24px 24px 0 0",
        padding: "24px 24px 48px", width: "100%", maxWidth: 480,
        border: `1px solid ${COLORS.border}`, maxHeight: "90vh", overflowY: "auto",
        scrollbarWidth: "none" as any,
      }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h2 style={{ color: COLORS.white, fontSize: 20, fontWeight: 800, margin: 0 }}>Log Your Stats</h2>
          <button onClick={onClose} style={{ background: "none", border: "none", color: COLORS.textSecondary, fontSize: 24, cursor: "pointer" }}>×</button>
        </div>
        <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: "0 0 20px", lineHeight: 1.5 }}>
          {isBaseline ? "Set your baseline measurements so we can track your progress from day one." : "Log when you feel ready. Weekly check-ins give the most accurate picture of your progress."}
        </p>
        <div style={{ marginBottom: 20 }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600, letterSpacing: 1, textTransform: "uppercase", margin: 0 }}>
              Weight ({unit === "metric" ? "kg" : "lbs"}) <span style={{ color: COLORS.accent }}>*</span>
            </p>
            {isLocked("weight") && (
              <span style={{ color: "#F59E0B", fontSize: 11, fontWeight: 700 }}>🔒 Available in {daysLeft("weight")}d</span>
            )}
          </div>
          <input type="number" placeholder={isLocked("weight") ? "Locked" : "0"} value={weight}
            onChange={e => !isLocked("weight") && setWeight(e.target.value)}
            disabled={isLocked("weight")}
            style={inputStyle(!!weight, isLocked("weight"))} />
        </div>
        {!wellnessMode && (
          <>
            <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 10px" }}>
              Measurements ({measureLabel}) — Optional
            </p>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 10 }}>
              {[
                { label: "Waist", val: waist, set: setWaist, key: "waist" },
                { label: "Chest", val: chest, set: setChest, key: "chest" },
                { label: "Arms", val: arms, set: setArms, key: "arms" },
              ].map(f => {
                const locked = isLocked(f.key);
                return (
                  <div key={f.label} style={{ textAlign: "center" }}>
                    <input type="number" placeholder={locked ? "🔒" : "0"} value={f.val}
                      onChange={e => !locked && f.set(e.target.value)}
                      disabled={locked} style={inputStyle(!!f.val, locked)} />
                    <p style={{ color: locked ? "#F59E0B" : COLORS.textSecondary, fontSize: 11, margin: "5px 0 0", fontWeight: 600 }}>
                      {f.label}{locked ? ` (${daysLeft(f.key)}d)` : ""}
                    </p>
                  </div>
                );
              })}
            </div>
            <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 24 }}>
              {[
                { label: "Hips", val: hips, set: setHips, key: "hips" },
                { label: "Neck", val: neck, set: setNeck, key: "neck" },
                { label: "Thighs", val: thighs, set: setThighs, key: "thighs" },
              ].map(f => {
                const locked = isLocked(f.key);
                return (
                  <div key={f.label} style={{ textAlign: "center" }}>
                    <input type="number" placeholder={locked ? "🔒" : "0"} value={f.val}
                      onChange={e => !locked && f.set(e.target.value)}
                      disabled={locked} style={inputStyle(!!f.val, locked)} />
                    <p style={{ color: locked ? "#F59E0B" : COLORS.textSecondary, fontSize: 11, margin: "5px 0 0", fontWeight: 600 }}>
                      {f.label}{locked ? ` (${daysLeft(f.key)}d)` : ""}
                    </p>
                  </div>
                );
              })}
            </div>
          </>
        )}
        {(() => {
          const hasAnyValue = [
            { key: "weight", val: weight }, { key: "waist", val: waist },
            { key: "hips", val: hips }, { key: "arms", val: arms },
            { key: "chest", val: chest }, { key: "neck", val: neck }, { key: "thighs", val: thighs }
          ].some(f => f.val && !isLocked(f.key));
          return (
            <button onClick={handleSave} disabled={!hasAnyValue} style={{
              width: "100%", padding: "18px", borderRadius: 16, border: "none",
              background: !hasAnyValue ? COLORS.border : `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`,
              color: !hasAnyValue ? COLORS.textSecondary : COLORS.white,
              fontSize: 16, fontWeight: 700, cursor: !hasAnyValue ? "not-allowed" : "pointer",
              boxShadow: !hasAnyValue ? "none" : `0 8px 30px ${COLORS.primary}40`,
            }}>Save Stats</button>
          );
        })()}
      </div>
    </div>
  );
};

const formatTime = (secs: number) => {
  const h = Math.floor(secs / 3600);
  const m = Math.floor((secs % 3600) / 60);
  const s = secs % 60;
  return h > 0
    ? `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`
    : `${m}:${String(s).padStart(2, "0")}`;
};

// Dedicated detail view for a cardio/mind-body session in history - the
// existing selectedSession detail views in ProgressScreen/HistoryScreen
// were built entirely around lifting-day data (groups/dayTitle/dayFocus),
// so a cardio session rendered blank there (no exercises to show). This
// is a genuinely separate template, not a patch on the lifting one.
// Multi-session trend chart - roadmap item #3's "buildable now" piece,
// since it only needs the aggregate numbers already saved on every session
// (no per-point GPS timing required, unlike a real single-run pace graph).
// Built as a hand-rolled SVG rather than pulling in a charting library
// (recharts, etc.) - the app's bundle is already flagged oversized by the
// build output, and this is simple enough (a handful of points, one line)
// that a real dependency isn't worth the extra weight on every resident's
// download. Smooth curve via Catmull-Rom-to-bezier conversion, not
// straight line segments - genuinely matches the polish level of the
// PR-glow treatment used elsewhere, not a bare debug-style line graph.
const TREND_CHART_HINT_SEEN_KEY = "amenityfit_trend_chart_hint_seen";
const TrendChart = ({ points, unit, showBest, higherIsBetter }: { points: { label: string; value: number }[]; unit: string; showBest: boolean; higherIsBetter: boolean }) => {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  // First-time-only discoverability hint - a person's first trend chart
  // ever, across every activity type (not per-chart, so this doesn't
  // re-trigger for their second different activity's chart), gets a
  // genuinely noticeable pulsing callout instead of just the quiet static
  // caption every visit after gets. Read once on mount, not on every
  // render, so tapping a point during this first view doesn't cause the
  // hint to flicker back on.
  const [showFirstTimeHint, setShowFirstTimeHint] = useState(() => {
    try {
      return !localStorage.getItem(TREND_CHART_HINT_SEEN_KEY);
    } catch {
      return false; // localStorage unavailable (private mode, quota) - default to the quiet version, never block rendering over this
    }
  });
  // Guarded by points.length >= 3 - this component returns null just below
  // for a too-short trend, and that null render is never actually shown to
  // the person, so it must never burn the one-time "seen" flag. Marking
  // the hint seen only happens on a render that genuinely displayed it.
  useEffect(() => {
    if (showFirstTimeHint && points.length >= 3) {
      try { localStorage.setItem(TREND_CHART_HINT_SEEN_KEY, "true"); } catch {}
    }
  }, []);
  if (points.length < 3) return null;

  const width = 320;
  const height = 120;
  const padX = 12;
  const padY = 20;
  const values = points.map((p) => p.value);
  const min = Math.min(...values);
  const max = Math.max(...values);
  // Guards a flat/all-identical line (e.g. every session exactly 20:00) -
  // without this, range = 0 and every y computation below divides by zero.
  const range = max - min || 1;

  const coords = points.map((p, i) => {
    const x = padX + (i / (points.length - 1)) * (width - padX * 2);
    // SVG y grows downward, so invert - a higher value should sit higher
    // on screen (closer to y=padY) regardless of what "higher" means
    // semantically (better pace = lower number, better distance = higher
    // number) - higherIsBetter only affects which point gets the PR-style
    // highlight below, never the raw plotting math itself.
    const y = padY + (1 - (p.value - min) / range) * (height - padY * 2);
    return { x, y };
  });

  // Catmull-Rom to cubic-bezier conversion - standard technique for a
  // smooth curve that actually passes through every real data point
  // (unlike a simple smoothing average, which would visually lie about
  // where sessions actually landed).
  const linePath = coords.reduce((path, point, i) => {
    if (i === 0) return `M ${point.x},${point.y}`;
    const p0 = coords[Math.max(0, i - 2)];
    const p1 = coords[i - 1];
    const p2 = point;
    const p3 = coords[Math.min(coords.length - 1, i + 1)];
    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;
    return `${path} C ${cp1x},${cp1y} ${cp2x},${cp2y} ${p2.x},${p2.y}`;
  }, "");

  const fillPath = `${linePath} L ${coords[coords.length - 1].x},${height - padY} L ${coords[0].x},${height - padY} Z`;

  // Only pace trends have a real "better/worse" direction (lower pace is
  // genuinely faster) - duration trends have no such thing (a longer
  // meditation isn't a worse one, a longer easy run isn't a worse one
  // either), so showBest=false means -1, which never matches any real
  // index below, meaning no dot ever gets the "Best" highlight treatment.
  const bestIndex = showBest
    ? (higherIsBetter ? values.indexOf(max) : values.indexOf(min))
    : -1;

  return (
    <div style={{ margin: "14px 24px 0", padding: "16px 16px 8px", borderRadius: 16, background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
      <svg viewBox={`0 0 ${width} ${height}`} style={{ width: "100%", display: "block" }}>
        <defs>
          <linearGradient id="trendFill" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={COLORS.accent} stopOpacity="0.35" />
            <stop offset="100%" stopColor={COLORS.accent} stopOpacity="0" />
          </linearGradient>
        </defs>
        <path d={fillPath} fill="url(#trendFill)" />
        <path d={linePath} fill="none" stroke={COLORS.accent} strokeWidth={2.5} strokeLinecap="round" />
        {coords.map((c, i) => (
          <circle
            key={i}
            cx={c.x}
            cy={c.y}
            r={i === activeIndex ? 6 : (i === bestIndex ? 4.5 : 3)}
            fill={i === bestIndex ? COLORS.success : COLORS.accent}
            stroke={COLORS.background}
            strokeWidth={i === activeIndex ? 2 : 1}
            onClick={() => setActiveIndex(activeIndex === i ? null : i)}
            style={{ cursor: "pointer" }}
          />
        ))}
      </svg>
      {activeIndex !== null && (
        <p style={{ color: COLORS.white, fontSize: 13, fontWeight: 700, textAlign: "center", margin: "4px 0 8px" }}>
          {points[activeIndex].label}: {points[activeIndex].value.toFixed(1)}{unit}
          {activeIndex === bestIndex && <span style={{ color: COLORS.success }}> · Best</span>}
        </p>
      )}
      {activeIndex === null && showFirstTimeHint && (
        <>
          <style>{`
            @keyframes trendHintPulse {
              0%, 100% { opacity: 0.6; }
              50% { opacity: 1; }
            }
          `}</style>
          <p style={{ color: COLORS.accent, fontSize: 12, fontWeight: 700, textAlign: "center", margin: "4px 0 8px", animation: "trendHintPulse 1.6s ease-in-out infinite" }}>
            👆 Tap any point to see the exact value
          </p>
        </>
      )}
      {activeIndex === null && !showFirstTimeHint && (
        <p style={{ color: COLORS.textSecondary, fontSize: 11, textAlign: "center", margin: "4px 0 8px" }}>Tap a point for details</p>
      )}
    </div>
  );
};

// Real replacement for the old Mapbox Static Images API - that service
// required a paid, metered API key past its free tier and legally
// required a permanent Mapbox logo watermark on every image, both real
// problems as this app scales toward hundreds of buildings. MapLibre GL
// JS is a fully open-source (BSD-3) library with no usage billing at
// all - the JS is bundled into this app's own code, not fetched from a
// tracked third-party service. Paired with Esri's free World Imagery
// tiles (pure satellite photography, no street/place-name labels at
// all - the same deliberate privacy property the old satellite-v9 style
// was chosen for, preserved exactly), this gives an equivalent visual
// result with zero recurring cost and no logo requirement.
//
// Esri's World Imagery is a free, unauthenticated public service with
// no published SLA or rate-limit guarantee - reliable in practice, but
// not contractually guaranteed the way a paid API would be. The
// fallback below (a clean route-line-only render with no imagery,
// triggered if tiles don't load within a short timeout or the source
// reports real load errors) means a rare Esri hiccup never surfaces as
// a broken or blank map to the person using the app - just, on a very
// unlucky occasion, a plain but still fully accurate route line. This
// is purely a RENDERING layer - it never touches how GPS points are
// recorded, simplified, or how distance/pace are calculated; it only
// changes how the already-recorded route array gets drawn on screen.
const ESRI_WORLD_IMAGERY_TILE_URL = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}";
// Real research finding: Strava's route lines are orange, not their own
// UI brand color by coincidence - orange sits roughly opposite sky-blue
// and green foliage on the color wheel, the two most common outdoor
// photo backdrops, which is WHY it reads clearly without any clever
// contrast trickery. AmenityFit's own blue accent is nearly the worst
// possible choice for this specific job, since it directly blends with
// sky - confirmed by a real device test where the route was barely
// visible against a blue-sky photo. This is a dedicated color for map/
// route rendering only - distinct from Strava's specific red-orange
// (#FC4C02), and not identical to AmenityFit's own UI blue either. It
// sits roughly opposite that blue on the color wheel, so the pairing
// reads as a deliberate, coordinated two-color system unique to this
// app, not a copy of anyone else's brand color.
const ROUTE_LINE_COLOR = "#F5A623";

const InteractiveRouteMap = ({
  route,
  interactive = true,
  height = 240,
  strokeColor,
}: {
  route: { lat: number; lng: number }[];
  interactive?: boolean;
  height?: number;
  strokeColor?: string;
}) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [fallback, setFallback] = useState(false);
  const accentColor = strokeColor || ROUTE_LINE_COLOR;

  useEffect(() => {
    if (!containerRef.current || !route || route.length < 2) return;
    let cancelled = false;
    // Plain local variable, not React state - deliberately, so the
    // timeout and error handlers below (closures created once, at this
    // effect's setup) always see the real, current value rather than a
    // stale snapshot from the render that first created them. React
    // state's setter doesn't update an already-captured closure's view
    // of the old value, which would make this timer fire unconditionally
    // regardless of whether the map genuinely finished loading.
    let hasLoaded = false;
    // Set once the dynamically-imported map instance actually exists -
    // the cleanup function below needs a way to reach it even though
    // it's created inside an async inner function, not this effect's
    // own top-level scope.
    let mapInstance: any = null;

    const fallbackTimer = setTimeout(() => {
      if (!cancelled && !hasLoaded) setFallback(true);
    }, 6000);

    const coordinates = route.map((p) => [p.lng, p.lat] as [number, number]);
    const lngs = coordinates.map((c) => c[0]);
    const lats = coordinates.map((c) => c[1]);
    const bounds: [[number, number], [number, number]] = [
      [Math.min(...lngs), Math.min(...lats)],
      [Math.max(...lngs), Math.max(...lats)],
    ];

    (async () => {
      // Dynamic import, deferred until this component actually mounts
      // with a real route - see the top-of-file note on why maplibregl
      // is never statically imported. The CSS import works the same way
      // Vite handles a static CSS import, just deferred until this code
      // path genuinely runs, not bundled for every single visitor.
      const [maplibregl] = await Promise.all([
        import("maplibre-gl"),
        import("maplibre-gl/dist/maplibre-gl.css"),
      ]);
      if (cancelled || !containerRef.current) return;

      const map = new maplibregl.Map({
        container: containerRef.current,
        style: {
          version: 8,
          sources: {
            "esri-satellite": {
              type: "raster",
              tiles: [ESRI_WORLD_IMAGERY_TILE_URL],
              tileSize: 256,
              attribution: "Tiles © Esri",
            },
          },
          layers: [{ id: "esri-satellite", type: "raster", source: "esri-satellite" }],
        },
        interactive,
        attributionControl: false,
        preserveDrawingBuffer: true,
      });
      mapInstance = map;

      map.on("error", () => {
        if (!cancelled && !hasLoaded) setFallback(true);
      });

      map.on("load", () => {
        if (cancelled) return;
        map.addSource("route-line", {
          type: "geojson",
          data: { type: "Feature", geometry: { type: "LineString", coordinates }, properties: {} },
        });
        // Same double-stroke technique as the old static image - a wider
        // dark outline first, then the accent-colored line on top, so the
        // route stays readable regardless of what's underneath it.
        map.addLayer({
          id: "route-outline", type: "line", source: "route-line",
          paint: { "line-color": "#000000", "line-width": 11, "line-opacity": 0.8 },
          layout: { "line-cap": "round", "line-join": "round" },
        });
        map.addLayer({
          id: "route-line-accent", type: "line", source: "route-line",
          paint: { "line-color": accentColor, "line-width": 7, "line-opacity": 1 },
          layout: { "line-cap": "round", "line-join": "round" },
        });
        map.fitBounds(bounds, { padding: 40, animate: false });
        hasLoaded = true;
      });

      if (!interactive) {
        map.dragPan.disable();
        map.scrollZoom.disable();
        map.boxZoom.disable();
        map.dragRotate.disable();
        map.keyboard.disable();
        map.doubleClickZoom.disable();
        map.touchZoomRotate.disable();
      }
    })();

    return () => {
      cancelled = true;
      clearTimeout(fallbackTimer);
      if (mapInstance) mapInstance.remove();
    };
  }, [route]);

  if (!route || route.length < 2) return null;

  if (fallback) {
    // Guaranteed-to-render fallback - a plain SVG route line on a
    // neutral background, the same simplification/scaling technique
    // already proven in MiniGraph elsewhere in this file. No external
    // request of any kind, so this can never itself fail to render.
    const simplified = simplifyRoute(route, 120);
    const fLats = simplified.map((p) => p.lat);
    const fLngs = simplified.map((p) => p.lng);
    const minLat = Math.min(...fLats), maxLat = Math.max(...fLats);
    const minLng = Math.min(...fLngs), maxLng = Math.max(...fLngs);
    const latRange = maxLat - minLat || 1;
    const lngRange = maxLng - minLng || 1;
    const w = 400, h = height, pad = 20;
    const points = simplified.map((p) => {
      const x = pad + ((p.lng - minLng) / lngRange) * (w - pad * 2);
      const y = h - pad - ((p.lat - minLat) / latRange) * (h - pad * 2);
      return `${x},${y}`;
    });
    return (
      <div style={{ width: "100%", height, background: COLORS.card, borderRadius: 20, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <svg width="100%" height={h} viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="xMidYMid meet">
          <polyline points={points.join(" ")} fill="none" stroke="#000000" strokeOpacity={0.55} strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" />
          <polyline points={points.join(" ")} fill="none" stroke={accentColor} strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>
    );
  }

  return (
    <div ref={containerRef} style={{ width: "100%", height, borderRadius: 20, overflow: "hidden" }} />
  );
};

const ActivityDetailView = ({ session, sessionHistory, profile, onClose }: { session: any; sessionHistory: any[]; profile: any; onClose: () => void }) => {
  const [showShareCard, setShowShareCard] = useState(false);
  const [showStickerMode, setShowStickerMode] = useState(false);
  const meta = ACTIVITY_TYPES.find((a) => a.key === session.type);
  const isMindBody = !!meta?.isMindBody;
  // Same 0.05km floor as the trusted live/save-time guard - a few
  // meters of pure GPS noise shouldn't display as a real tracked distance.
  const hasDistance = (session.distanceMeters || 0) >= 50;
  const courtType = meta?.courtType;
  // Real MapLibre+Esri snapshot, replacing the old Mapbox static image -
  // called unconditionally (hooks must be, regardless of courtType) with
  // null passed for court sports, which the hook already treats as "no
  // route, return null" internally.
  const routeSnapshotUrl = useRouteMapSnapshot(courtType ? null : session.route, 640, 360);
  // Transparent route-outline variant for the Satellite/Outline toggle -
  // only meaningful for a real GPS route, not court sports (which have
  // no route data at all, so this hook receives null and returns null).
  const outlineSnapshotUrl = useRouteMapSnapshot(courtType ? null : session.route, 640, 360, undefined, true);
  const locationLabel = courtType ? null : getRouteLocationLabel(session.route);
  const mapUrl = courtType
    ? buildCourtIllustrationUrl(courtType, COLORS.accent)
    : routeSnapshotUrl;
  const paceLabel = hasDistance && session.avgPaceSecondsPerKm
    ? `${Math.floor(session.avgPaceSecondsPerKm / 60)}:${String(Math.round(session.avgPaceSecondsPerKm % 60)).padStart(2, "0")}/km`
    : null;
  const dateLabel = session.completedAt?.toDate
    ? session.completedAt.toDate().toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })
    : "";

  // Comparison stat - cardio only, deliberately never shown for mind-body
  // (see the roadmap note: "beat your last one" framing doesn't fit a
  // restorative practice). Compares this session's pace against the
  // average of the person's other sessions of the same activity type.
  let comparisonLabel: string | null = null;
  if (!isMindBody && hasDistance && session.avgPaceSecondsPerKm) {
    const sameType = sessionHistory.filter((s) => s.type === session.type && s.id !== session.id && s.avgPaceSecondsPerKm);
    if (sameType.length > 0) {
      const avgPace = sameType.reduce((sum, s) => sum + s.avgPaceSecondsPerKm, 0) / sameType.length;
      const diffPct = Math.round(((avgPace - session.avgPaceSecondsPerKm) / avgPace) * 100);
      if (Math.abs(diffPct) >= 2) {
        comparisonLabel = diffPct > 0
          ? `${diffPct}% faster than your recent ${meta?.label || session.type} average`
          : `${Math.abs(diffPct)}% slower than your recent ${meta?.label || session.type} average`;
      }
    }
  }

  // Real gap found tonight: PR status computed at completion time was
  // never persisted onto the saved session, so revisiting it later from
  // History showed no PR badge at all even when it genuinely was one.
  // session.isPR is written once, at save time (see finishActivity) -
  // reading it back here is what makes the badge persist correctly.
  const stats: { label: string; value: string; isPR?: boolean }[] = [];
  if (hasDistance) stats.push({ label: "Distance", value: `${(session.distanceMeters / 1000).toFixed(2)} km`, isPR: !!session.isPR?.distance });
  stats.push({ label: "Time", value: formatTime(session.durationSeconds || 0), isPR: !!session.isPR?.duration });
  if (paceLabel) stats.push({ label: "Pace", value: paceLabel, isPR: !!session.isPR?.pace });
  if (session.calories) stats.push({ label: "Calories", value: `~${session.calories}` });
  // Only shown when there's real, trusted altitude data to compute from -
  // null (insufficient data) is deliberately different from a genuine 0m
  // flat route, so this stat simply doesn't appear rather than showing a
  // misleading "0 m" for older sessions with no altitude captured at all.
  const elevationGain = computeElevationGainMeters(session.route);
  if (elevationGain !== null) stats.push({ label: "Elevation Gain", value: `${elevationGain} m` });

  // Multi-session trend - last 10 sessions of the same type, oldest-to-newest
  // (natural left-to-right reading of "progress over time"), including this
  // one so it's visible on its own trend, not just the sessions before it.
  // Cardio with real pace data trends pace (the metric people actually care
  // about improving); everything else (mind-body, or cardio sessions
  // without a pace, e.g. indoor machines with no distance) trends duration
  // instead, since pace never applies there.
  const sameTypeChronological = sessionHistory
    .filter((s) => s.type === session.type)
    .sort((a: any, b: any) => {
      const aTime = a.completedAt?.toMillis ? a.completedAt.toMillis() : new Date(a.completedAt || 0).getTime();
      const bTime = b.completedAt?.toMillis ? b.completedAt.toMillis() : new Date(b.completedAt || 0).getTime();
      return aTime - bTime;
    });
  const trendSource = sameTypeChronological.slice(-10);
  const trendUsesPace = !isMindBody && trendSource.some((s) => s.avgPaceSecondsPerKm);
  const trendPoints = trendSource
    .map((s) => {
      const dateLabel = s.completedAt?.toDate ? s.completedAt.toDate().toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "";
      if (trendUsesPace) {
        if (!s.avgPaceSecondsPerKm) return null;
        return { label: dateLabel, value: s.avgPaceSecondsPerKm / 60 };
      }
      return { label: dateLabel, value: (s.durationSeconds || 0) / 60 };
    })
    .filter((p): p is { label: string; value: number } => p !== null);

  // Real per-kilometer splits, using this session's own route - not
  // cardio/pace estimate, genuine GPS-segment math (see
  // computeKilometerSplits). Only shown once there are at least 2 real
  // splits - a single split is just the overall pace already shown
  // above, so a "Splits" section with one bar adds nothing.
  const splitPoints = (!isMindBody && hasDistance && session.route?.length > 1)
    ? computeKilometerSplits(session.route).map((s) => ({ label: `KM ${s.km}`, value: s.paceSecondsPerKm / 60 }))
    : [];

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 700, background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column", overflow: "auto" }}>
      <div style={{ padding: "52px 24px 16px", display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={onClose} style={{ background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 10, width: 34, height: 34, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer" }}>
          <ArrowLeft size={16} color={COLORS.white} />
        </button>
        <span style={{ color: COLORS.textSecondary, fontSize: 14, fontWeight: 600 }}>{dateLabel}</span>
      </div>

      <div style={{ padding: "8px 24px 0", textAlign: "center" }}>
        {(meta?.icon || meta?.iconImage) && (
          <div style={{ width: 64, height: 64, borderRadius: 18, background: `linear-gradient(135deg, ${COLORS.primary}22, ${COLORS.accent}22)`, border: `1px solid ${COLORS.border}`, display: "flex", alignItems: "center", justifyContent: "center", margin: "0 auto" }}>
            {meta.iconImage
              ? <img src={meta.iconImage} alt="" style={{ width: 32, height: 32, objectFit: "contain" }} />
              : <meta.icon size={32} color={COLORS.white} strokeWidth={1.75} />}
          </div>
        )}
        <h1 style={{ color: COLORS.white, fontSize: 22, fontWeight: 900, margin: "10px 0 0" }}>{session.customActivityName || meta?.label || session.type}</h1>
      </div>

      {/* Real GPS route (no courtType) gets the new interactive
          MapLibre+Esri map - pan/zoom, no Mapbox billing/watermark.
          Court sports keep the existing hand-drawn SVG illustration
          exactly as before (not GPS-based, nothing to replace here). */}
      {!courtType && session.route?.length > 1 && (
        <div style={{ margin: "16px 24px 0", border: `1px solid ${COLORS.border}`, borderRadius: 20, overflow: "hidden" }}>
          <InteractiveRouteMap route={session.route} interactive={true} height={240} />
        </div>
      )}
      {courtType && mapUrl && (
        <div style={{ margin: "16px 24px 0", borderRadius: 20, overflow: "hidden", border: `1px solid ${COLORS.border}` }}>
          <img src={mapUrl} alt="" style={{ width: "100%", display: "block" }} />
        </div>
      )}

      <div style={{ display: "grid", gridTemplateColumns: `repeat(${stats.length}, 1fr)`, gap: 10, margin: "20px 24px 0" }}>
        {stats.map((s) => (
          <div key={s.label} style={{ background: s.isPR ? `${COLORS.accent}18` : COLORS.card, border: s.isPR ? `1px solid ${COLORS.accent}60` : `1px solid ${COLORS.border}`, borderRadius: 14, padding: "14px 8px", textAlign: "center" }}>
            <p style={{ color: s.isPR ? COLORS.accent : COLORS.textSecondary, fontSize: 10, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 6px" }}>{s.isPR ? "PR" : s.label}</p>
            <p style={{ color: COLORS.white, fontSize: 18, fontWeight: 900, margin: 0 }}>{s.value}</p>
          </div>
        ))}
      </div>

      {comparisonLabel && (
        <div style={{ margin: "14px 24px 0", padding: "12px 16px", borderRadius: 14, background: `${COLORS.accent}15`, border: `1px solid ${COLORS.accent}40` }}>
          <p style={{ color: COLORS.accent, fontSize: 13, fontWeight: 700, margin: 0, textAlign: "center" }}>{comparisonLabel}</p>
        </div>
      )}

      {splitPoints.length >= 2 && (
        <>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "20px 24px 0" }}>
            Splits
          </p>
          <TrendChart
            points={splitPoints}
            unit=" min/km"
            showBest={true}
            higherIsBetter={false}
          />
        </>
      )}

      {trendPoints.length >= 3 && (
        <>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "20px 24px 0" }}>
            {trendUsesPace ? "Pace" : "Duration"} Trend
          </p>
          <TrendChart
            points={trendPoints}
            unit={trendUsesPace ? " min/km" : " min"}
            // Only pace has a real better/worse direction - duration
            // trends (mind-body, or cardio with no distance) show the
            // shape of the data with no "Best" claim attached, since
            // longer isn't inherently better or worse there.
            showBest={trendUsesPace}
            higherIsBetter={false}
          />
        </>
      )}

      {session.notes && (
        <div style={{ margin: "14px 24px 0", padding: 16, borderRadius: 14, background: COLORS.card, border: `1px solid ${COLORS.border}` }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 8px" }}>{isMindBody ? "How it felt" : "Notes"}</p>
          <p style={{ color: COLORS.white, fontSize: 14, margin: 0, lineHeight: 1.5 }}>{session.notes}</p>
        </div>
      )}

      <div style={{ padding: "24px", marginTop: "auto", display: "flex", gap: 12 }}>
        <button onClick={() => setShowShareCard(true)} style={{ flex: 1, padding: "16px", borderRadius: 16, border: `1px solid ${COLORS.border}`, background: COLORS.card, color: COLORS.white, fontSize: 15, fontWeight: 700, cursor: "pointer" }}>
          Share
        </button>
        <button onClick={() => setShowStickerMode(true)} style={{ flex: 1, padding: "16px", borderRadius: 16, border: `1px solid ${COLORS.border}`, background: COLORS.card, color: COLORS.white, fontSize: 15, fontWeight: 700, cursor: "pointer" }}>
          Sticker
        </button>
      </div>

      {showShareCard && (
        <ShareableStatCard
          title={`${session.customActivityName || meta?.label || session.type} on AmenityFit`}
          subtitle={dateLabel}
          icon={meta?.icon}
          iconImage={meta?.iconImage}
          mapUrl={mapUrl}
          outlineMapUrl={outlineSnapshotUrl}
          locationLabel={locationLabel}
          stats={stats}
          onClose={() => setShowShareCard(false)}
        />
      )}
      {showStickerMode && (
        <StickerShareScreen
          title={session.customActivityName || meta?.label || session.type}
          icon={meta?.icon}
          iconImage={meta?.iconImage}
          mapUrl={mapUrl}
          outlineMapUrl={outlineSnapshotUrl}
          locationLabel={locationLabel}
          stats={stats}
          onClose={() => setShowStickerMode(false)}
        />
      )}
    </div>
  );
};

// Real "Active Weeks" streak visualization - genuinely distinct from
// Dashboard's "This Week's Activity" snapshot card: that one is a
// weekly-total snapshot on Home, this is a long-term consistency pattern
// on Progress. Fixed flame-orange grid scale (independent of overall
// tier color) - matches the established GitHub-contribution-graph
// metaphor, where color intensity always means "how active," not "what
// tier you're currently at."
const ACTIVE_WEEKS_GRID_COLOR = "#E8A87C";

const ActiveWeeksCard = ({ streak, bestStreak, thisWeekCount, weeklyBlocks }: {
  streak: number;
  bestStreak: number;
  thisWeekCount: number;
  weeklyBlocks: { weekStart: Date; count: number; active: boolean }[];
}) => {
  const tier = getActiveWeeksTier(streak);
  const nextTierWeeks = streak >= 52 ? null : streak >= 26 ? 52 : streak >= 12 ? 26 : streak >= 4 ? 12 : 4;
  const scrollRef = React.useRef<HTMLDivElement>(null);
  const currentWeekStart = getMondayOfWeek(new Date());
  // Real bug found via real-device testing: the grid's only way to show
  // per-week detail was the HTML title attribute, which only reveals on
  // desktop hover - a real phone has no way to trigger it at all, so the
  // detail was effectively unreachable on the one platform this app
  // actually runs on. Tap-driven state instead: tapping a cell shows its
  // date range and session count in a small line below the grid.
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [showShareCard, setShowShareCard] = useState(false);
  const [showStickerMode, setShowStickerMode] = useState(false);

  // Auto-scroll to the most recent (rightmost) week on mount, so the
  // person always lands looking at "now," not the oldest history.
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollLeft = scrollRef.current.scrollWidth;
    }
  }, [weeklyBlocks.length]);

  // Current in-progress week appended as its own distinct cell - dashed
  // outline, not a solid fill, so it visually reads as "not yet decided"
  // rather than looking like a missed week sitting right next to real
  // completed ones. Keeps the grid one coherent timeline (long-term
  // pattern + present state) instead of two disconnected displays.
  const displayBlocks = [...weeklyBlocks, { weekStart: currentWeekStart, count: thisWeekCount, active: false, current: true }];
  const selectedBlock = selectedIndex !== null ? (displayBlocks[selectedIndex] as any) : null;

  const shareStats = [
    { label: "Active Weeks", value: String(streak) },
    { label: "Best Streak", value: String(bestStreak) },
    { label: "This Week", value: `${Math.min(thisWeekCount, ACTIVE_WEEK_SESSION_THRESHOLD)}/${ACTIVE_WEEK_SESSION_THRESHOLD}` },
  ];

  return (
    <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
        <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: 0 }}>Active Weeks</p>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setShowShareCard(true)} style={{ background: "transparent", border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "4px 10px", color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, cursor: "pointer" }}>Share</button>
          <button onClick={() => setShowStickerMode(true)} style={{ background: "transparent", border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "4px 10px", color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, cursor: "pointer" }}>Sticker</button>
        </div>
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 12 }}>
        <div style={{
          width: 64, height: 64, borderRadius: 99, flexShrink: 0,
          background: `${tier?.color || COLORS.textSecondary}18`,
          border: `2px solid ${tier?.color || COLORS.border}50`,
          display: "flex", alignItems: "center", justifyContent: "center",
          boxShadow: tier ? `0 0 24px ${tier.color}30` : "none",
        }}>
          <Flame size={30} color={tier?.color || COLORS.textSecondary} strokeWidth={1.75} />
        </div>
        <div>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
            <span style={{ color: COLORS.white, fontSize: 32, fontWeight: 900, letterSpacing: -1 }}>{streak}</span>
            <span style={{ color: COLORS.textSecondary, fontSize: 14, fontWeight: 700 }}>week{streak === 1 ? "" : "s"}</span>
          </div>
          {tier ? (
            <p style={{ color: tier.color, fontSize: 13, fontWeight: 700, margin: "2px 0 0" }}>{tier.label} tier{nextTierWeeks ? ` · ${nextTierWeeks - streak} to next` : ""}</p>
          ) : (
            <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: "2px 0 0" }}>{4 - streak} more to Spark</p>
          )}
        </div>
      </div>

      {/* Personal-best streak alongside the current one - a real gap
          rebuild after a break should feel motivating ("on the way back
          to your best of 12"), not like starting from nothing with no
          context for what was already achieved. Only shown once there's
          a real best to show (bestStreak > 0), and only when it differs
          from the current streak (equal means the current run already IS
          the best, which the hero number above already conveys on its
          own without a redundant second line saying the same thing). */}
      {bestStreak > 0 && bestStreak !== streak && (
        <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: "0 0 20px" }}>
          Best: <span style={{ color: COLORS.white, fontWeight: 700 }}>{bestStreak} week{bestStreak === 1 ? "" : "s"}</span>
        </p>
      )}
      {!(bestStreak > 0 && bestStreak !== streak) && <div style={{ marginBottom: 8 }} />}

      {/* This week's live progress toward keeping the streak alive - the
          current week is deliberately NOT part of the streak count above
          (it isn't over yet), so this gives real visibility into what
          needs to happen to extend it, without a false "broken" state
          appearing mid-week. */}
      <div style={{ marginBottom: 20 }}>
        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600, margin: 0 }}>This week</p>
          <p style={{ color: thisWeekCount >= ACTIVE_WEEK_SESSION_THRESHOLD ? COLORS.success : COLORS.white, fontSize: 12, fontWeight: 700, margin: 0 }}>
            {Math.min(thisWeekCount, ACTIVE_WEEK_SESSION_THRESHOLD)}/{ACTIVE_WEEK_SESSION_THRESHOLD}
          </p>
        </div>
        <div style={{ display: "flex", gap: 4 }}>
          {Array.from({ length: ACTIVE_WEEK_SESSION_THRESHOLD }, (_, i) => (
            <div key={i} style={{ flex: 1, height: 6, borderRadius: 4, background: i < thisWeekCount ? ACTIVE_WEEKS_GRID_COLOR : COLORS.border }} />
          ))}
        </div>
      </div>

      {/* GitHub-contribution-style weekly grid - a genuine long-term
          pattern view. Intensity-shaded (not just binary) for real
          visual richness - 0 sessions faintest, 3+ full flame color -
          even though only the 3+ threshold actually counts toward the
          streak itself. Tap a cell to see its exact date range and
          session count below - the only viable detail affordance on a
          real touch device (see selectedIndex comment above). */}
      <div>
        <p style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600, margin: "0 0 8px" }}>Last {weeklyBlocks.length} weeks</p>
        <style>{`.active-weeks-scroll::-webkit-scrollbar{display:none}`}</style>
        <div ref={scrollRef} className="active-weeks-scroll" style={{ display: "flex", gap: 4, overflowX: "auto", msOverflowStyle: "none", scrollbarWidth: "none", paddingBottom: 4 } as any}>
          {displayBlocks.map((w: any, i) => {
            const bg = w.count === 0 ? COLORS.border : w.count <= 2 ? `${ACTIVE_WEEKS_GRID_COLOR}55` : ACTIVE_WEEKS_GRID_COLOR;
            const isSelected = selectedIndex === i;
            return (
              <button
                key={i}
                onClick={() => setSelectedIndex(isSelected ? null : i)}
                style={{
                  width: 16, height: 16, borderRadius: 4, flexShrink: 0, padding: 0, cursor: "pointer",
                  background: w.current ? "transparent" : bg,
                  border: w.current
                    ? `2px dashed ${w.count > 0 ? ACTIVE_WEEKS_GRID_COLOR : COLORS.border}`
                    : isSelected ? `2px solid ${COLORS.white}` : "none",
                  boxSizing: "border-box",
                }}
              />
            );
          })}
        </div>
        {selectedBlock && (
          <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: "10px 0 0" }}>
            Week of {selectedBlock.weekStart.toLocaleDateString("en-US", { month: "short", day: "numeric" })}
            {selectedBlock.current ? " (this week)" : ""} — <span style={{ color: COLORS.white, fontWeight: 700 }}>{selectedBlock.count} session{selectedBlock.count === 1 ? "" : "s"}</span>
          </p>
        )}
      </div>

      {showShareCard && (
        <ShareableStatCard
          title="Active Weeks"
          subtitle={tier ? `${tier.label} Tier` : "Building a Streak"}
          stats={shareStats}
          icon={Flame}
          onClose={() => setShowShareCard(false)}
        />
      )}

      {showStickerMode && (
        <StickerShareScreen
          title="Active Weeks"
          stats={shareStats}
          icon={Flame}
          onClose={() => setShowStickerMode(false)}
        />
      )}
    </div>
  );
};

const ProgressScreen = ({ profile, onBack, onNavigate = (s) => {}, onUpdate = (p) => {} }) => {
  const [activeMetric, setActiveMetric] = useState("weight");
  // Time-range filter for the body-measurement charts below - "All" by
  // default (matches existing behavior exactly, nothing changes unless
  // someone taps a different range).
  const [chartRange, setChartRange] = useState<"1M" | "3M" | "6M" | "All">("All");
  const [showLogModal, setShowLogModal] = useState(false);
  // Workout history state — must live at component top level (React hooks rules)
  const [historyLoaded, setHistoryLoaded] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [sessionHistory, setSessionHistory] = useState<any[]>([]);
  const [historyExpanded, setHistoryExpanded] = useState(false);
  const [selectedSession, setSelectedSession] = useState<any>(null);

  // Auto-load history when Progress tab opens — shows sessions immediately after completion
  // Also reloads when sessionsCompleted changes (user just finished a workout)
  const sessionsCompleted = profile?.sessionsCompleted || 0;
  useEffect(() => {
    if (profile?.uid) {
      setHistoryLoading(true);
      setHistoryLoaded(false);
      // Small delay to ensure Firestore write from workout completion has propagated
      fetchWorkoutHistory(profile.uid, (fastSessions) => setSessionHistory(fastSessions)).then(sessions => {
        setSessionHistory(sessions);
        setHistoryLoaded(true);
        setHistoryLoading(false);
      });
    }
  }, [profile?.uid, sessionsCompleted]);

  useEffect(() => {
    const uid = profile?.uid || auth.currentUser?.uid;
    if (uid) {
      fetchWorkoutHistory(uid, (fastSessions) => setSessionHistory(fastSessions)).then(sessions => {
        setSessionHistory(sessions);
        setHistoryLoaded(true);
        setHistoryLoading(false);
      });
    }
  }, [profile?.uid, profile?.sessionsCompleted]);
  // Real Active Weeks streak data - derived from the same sessionHistory
  // already loaded above for the workout history list, no separate query.
  const activeWeeksData = React.useMemo(
    () => computeActiveWeeksStreak(sessionHistory, profile?.createdAt ? new Date(profile.createdAt) : null, 26),
    [sessionHistory, profile?.createdAt]
  );
  const wellnessMode = profile?.wellnessMode || false;
  const unit = (profile?.heightFt && Number(profile.heightFt) > 0) ? "imperial" : (profile?.heightCm ? "metric" : "imperial");
  const startWeight = unit === "imperial"
    ? (Number(profile?.weightLbs) || null)
    : (Number(profile?.weightKg) || null);
  const weightUnit = unit === "imperial" ? "lbs" : "kg";
  const measureUnit = unit === "imperial" ? "in" : "cm";
  const seedBaseline = (): any[] => {
    if (!startWeight) return [];
    return [{ weight: startWeight, waist: null, hips: null, arms: null, chest: null, neck: null, thighs: null, label: "Baseline", date: profile?.createdAt || new Date().toISOString() }];
  };
  const rawLogs: any[] = (profile?.statsLogs && profile.statsLogs.length > 0) ? profile.statsLogs : seedBaseline();
  const hasBaselineEntry = rawLogs.some(l => l.label === "Baseline");
  const logs: any[] = hasBaselineEntry ? rawLogs : [
    { weight: startWeight, waist: null, hips: null, arms: null, chest: null, neck: null, thighs: null, label: "Baseline", date: profile?.createdAt || rawLogs[0]?.date || new Date().toISOString() },
    ...rawLogs,
  ];
  const hasBaseline = logs.length > 0;

  const completedDays: number[] = profile?.completedProgramDays || [];
  const workoutDoneToday = profile?.lastSessionDate === new Date().toDateString();
  const rawProgramDay = profile?.programDay || 1;
  const currentDay = workoutDoneToday ? Math.max(rawProgramDay - 1, 1) : rawProgramDay;

  const restDayNumbers: number[] = (() => {
    const progKey = profile?.programKey;
    if (!progKey) return [];
    const isMonth6 = progKey.startsWith("month6-");
    const baseProgramKey = isMonth6 ? progKey.replace("month6-", "") : progKey;

    // Reusable check: is this specific program-day number naturally a rest
    // day according to the program's own template, ignoring any swap.
    // Extracted so the reconciliation pass below can reuse the exact same
    // logic to evaluate a swapped-to day's natural rest status.
    const isNaturallyRestDay = (day: number): boolean => {
      if (!isMonth6 && profile?.restProgramDays?.length > 0) {
        return profile.restProgramDays.includes(day);
      }
      if (isMonth6) {
        const freq = profile?.frequency || 6;
        const restDaysByFrequency: Record<number, number[]> = {
          6: [7], 5: [4, 7], 4: [3, 5, 7], 3: [2, 4, 6, 7], 2: [2, 4, 5, 6, 7],
        };
        const weekRestDays = restDaysByFrequency[freq] || [7];
        const cycleDay = ((day - 1) % 7) + 1;
        return weekRestDays.includes(cycleDay);
      }
      const program = PROGRAMS[baseProgramKey];
      if (!program?.days) return false;
      const programLength = program.days.length;
      const restIndices = program.days.filter((d: any) => d.isRest).map((d: any) => d.dayNum).filter(Boolean);
      const cycleDay = ((day - 1) % programLength) + 1;
      return restIndices.includes(cycleDay);
    };

    const allRestDays: number[] = [];
    for (let day = 1; day <= 30; day++) {
      if (isNaturallyRestDay(day)) allRestDays.push(day);
    }

    // Reconciles the natural 30-day pattern against any active swap. Only
    // days whose real calendar date actually has an entry in dayOverrides
    // are affected, which by construction can only fall within the current
    // week, since a swap is never created for a future week. Every other
    // day in this 30-day view is untouched, correctly showing the
    // program's natural pattern rather than something that was never
    // actually swapped.
    if (profile?.dayOverrides) {
      const today = new Date();
      Object.entries(profile.dayOverrides).forEach(([dateKey, resolvedDay]) => {
        const overrideDate = new Date(dateKey);
        const diffDays = Math.round((overrideDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
        const naturalDayForDate = currentDay + diffDays;
        if (naturalDayForDate < 1 || naturalDayForDate > 30) return;
        const resolvedIsRest = isNaturallyRestDay(resolvedDay as number);
        const idx = allRestDays.indexOf(naturalDayForDate);
        if (resolvedIsRest && idx === -1) allRestDays.push(naturalDayForDate);
        if (!resolvedIsRest && idx !== -1) allRestDays.splice(idx, 1);
      });
    }

    return allRestDays;
  })();
  const totalSessions = profile?.cycleSessionsCompleted || 0;
  const frequency = profile?.frequency || 3;
  const weeklyTarget = frequency;
  const sessionsThisWeek = profile?.sessionsThisWeek || 0;
  const completionPct = Math.round((totalSessions / 30) * 100);
  const streak = profile?.streak || 0;

  const isWithinChartRange = (dateStr: string): boolean => {
    if (chartRange === "All" || !dateStr) return true;
    const days = chartRange === "1M" ? 30 : chartRange === "3M" ? 90 : 180;
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - days);
    const d = new Date(dateStr);
    return !isNaN(d.getTime()) && d >= cutoff;
  };
  const rangeLogs = logs.filter(l => isWithinChartRange(l.date));
  const weightData = rangeLogs.filter(l => l.weight != null).map(l => ({ value: l.weight, label: l.label, date: l.date }));
  const waistData = rangeLogs.filter(l => l.waist).map(l => ({ value: l.waist, label: l.label, date: l.date }));
  const hipsData = rangeLogs.filter(l => l.hips).map(l => ({ value: l.hips, label: l.label, date: l.date }));
  const armsData = rangeLogs.filter(l => l.arms).map(l => ({ value: l.arms, label: l.label, date: l.date }));
  const chestData = rangeLogs.filter(l => l.chest).map(l => ({ value: l.chest, label: l.label, date: l.date }));
  const neckData = rangeLogs.filter(l => l.neck).map(l => ({ value: l.neck, label: l.label, date: l.date }));
  const thighsData = rangeLogs.filter(l => l.thighs).map(l => ({ value: l.thighs, label: l.label, date: l.date }));

  const getActiveData = () => {
    if (activeMetric === "weight") return weightData;
    if (activeMetric === "waist") return waistData;
    if (activeMetric === "hips") return hipsData;
    if (activeMetric === "arms") return armsData;
    if (activeMetric === "chest") return chestData;
    if (activeMetric === "neck") return neckData;
    if (activeMetric === "thighs") return thighsData;
    return weightData;
  };

  
  // Per-metric: can this metric be logged today?
  const metricKeys: Record<string, string> = {
    weight: "weight", waist: "waist", hips: "hips",
    arms: "arms", chest: "chest", neck: "neck", thighs: "thighs",
  };
  const getMetricDaysSinceLastLog = (metricKey: string) => {
    // Each metric locks independently — find the last log that has a value for THIS metric
    const logsWithValue = logs.filter(l => l[metricKey] != null && l.label !== "Baseline");
    if (logsWithValue.length === 0) return null;
    const lastMetricLog = logsWithValue[logsWithValue.length - 1];
    return Math.floor((Date.now() - new Date(lastMetricLog.date).getTime()) / (1000 * 60 * 60 * 24));
  };
  const canLogMetric = (metricKey: string) => {
    const days = getMetricDaysSinceLastLog(metricKey);
    return days === null || days >= 7;
  };const handleSaveLog = (entry: any) => {
    const label = logs.length === 0 ? "Baseline" : entry.label;
    const filteredEntry: any = { label, date: entry.date };
    const metricKeyList = ["weight", "waist", "hips", "arms", "chest", "neck", "thighs"];
    metricKeyList.forEach(key => {
      if (entry[key] != null && canLogMetric(key)) {
        filteredEntry[key] = entry[key];
      }
    });
  
    const updatedLogs = [...logs, filteredEntry];
    onUpdate({ ...profile, statsLogs: updatedLogs });
  };
  const metrics = wellnessMode
    ? [{ id: "weight", label: "Weight" }]
    : [
        { id: "weight", label: "Weight" },
        { id: "waist", label: "Waist" },
        { id: "hips", label: "Hips" },
        { id: "arms", label: "Arms" },
        { id: "chest", label: "Chest" },
        { id: "neck", label: "Neck" },
        { id: "thighs", label: "Thighs" },
      ];

  // Overall can-log: at least one metric can be logged
  const canLogToday = metrics.some(m => canLogMetric(m.id));
  const activeMetricDays = getMetricDaysSinceLastLog(activeMetric);
  const activeMetricCanLog = canLogMetric(activeMetric);
  const daysUntilNextLog = activeMetricDays === null ? 0 : Math.max(0, 7 - activeMetricDays);

  // Numbers detail view — show all logged values for a metric
  const [showMetricDetail, setShowMetricDetail] = useState(false);

  // Get all logs for the active metric with dates and values
  const getActiveMetricHistory = () => {
    return logs
      .filter(l => l[activeMetric] != null)
      .map(l => ({
        value: l[activeMetric],
        label: l.label,
        date: l.date ? new Date(l.date).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "—",
      }))
      .reverse(); // newest first
  };

  // ── Session Detail View — uses WorkoutListScreen in review mode ──
  // Rendered as a genuine full-screen return here (not nested inside the
  // scrollable content below) so it gets its own clean, single scroll
  // container instead of being double-nested inside Progress's own
  // scrolling area, which was causing this specific view to scroll
  // sluggishly even though Progress itself scrolled fine.
  if (selectedSession && selectedSession.type && selectedSession.type !== "gym") {
    return (
      <ActivityDetailView
        session={selectedSession}
        sessionHistory={sessionHistory}
        profile={profile}
        onClose={() => setSelectedSession(null)}
      />
    );
  }

  if (selectedSession) {
    const groups = selectedSession.groups || [];
    const realMuscles: string[] = [];
    groups.forEach((g: any) => {
      if (g.type === "cardio") return;
      (g.exercises || []).forEach((ex: any) => {
        const m = (EXERCISES_DATA as any)[ex.id]?.muscle || "";
        if (m && !realMuscles.includes(m)) realMuscles.push(m);
      });
    });
    const focusLower = realMuscles.join(", ").toLowerCase();
    const wType = focusLower.includes("leg") || focusLower.includes("lower") || focusLower.includes("glute") || focusLower.includes("hamstring") || focusLower.includes("quad") || focusLower.includes("calf") || focusLower.includes("calve")
      ? "lower-body"
      : focusLower.includes("chest") || focusLower.includes("push") || focusLower.includes("tricep") || focusLower.includes("shoulder")
      ? "push"
      : focusLower.includes("back") || focusLower.includes("pull") || focusLower.includes("bicep") || focusLower.includes("lat")
      ? "upper-body"
      : focusLower.includes("core") || focusLower.includes("ab")
      ? "core"
      : focusLower.includes("cardio")
      ? "cardio"
      : "full-body";
    const heroImage = getWorkoutImage(wType, selectedSession.programDay || 1);
    const bgPos = wType === "lower-body" ? "center 60%" : "center top";

    const fakeDay = {
      dayNum: selectedSession.programDay || 1,
      title: expandDayTitle(selectedSession.dayTitle || selectedSession.dayFocus || "Workout"),
      focus: selectedSession.dayFocus || "Workout",
      isRest: false,
      groups,
      notes: [],
    };

    return (
      <WorkoutListScreen
        day={fakeDay}
        filteredGroups={groups}
        onStart={() => {}}
        onBack={() => setSelectedSession(null)}
        workoutImage={heroImage}
        programDay={selectedSession.programDay || 1}
        programWeek={Math.ceil((selectedSession.programDay || 1) / 7)}
        isReview={true}
        bgPosition={bgPos}
        equipmentPreference={selectedSession.equipmentPreference || profile?.equipmentPreference || "gym-and-bands"}
        buildingEquipment={profile?.buildingEquipment || []}
        historyMeta={{
          completedDateStr: selectedSession.completedDateStr,
          programLabel: selectedSession.programLabel,
          cycleNumber: selectedSession.cycleNumber,
          weightsLogged: selectedSession.weightsLogged || null,
          weightNotes: selectedSession.weightNotes || null,
        }}
      />
    );
  }

  return (
    <div style={{
      height: "100vh", background: COLORS.background,
      fontFamily: "'Inter', sans-serif", display: "flex",
      flexDirection: "column", overflow: "hidden",
    }}>
      {/* Header */}
      <div style={{ flexShrink: 0, padding: "calc(16px + env(safe-area-inset-top, 0px)) 24px 20px", background: `linear-gradient(180deg, ${COLORS.primary}18 0%, transparent 100%)` }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 4 }}>
          <h1 style={{ color: COLORS.white, fontSize: 28, fontWeight: 900, margin: 0, letterSpacing: -0.8 }}>Progress</h1>
          <button
            onClick={() => setShowLogModal(true)}
            title={!canLogToday ? `All metrics locked for now` : ""}
            style={{
              padding: "10px 18px", borderRadius: 12, border: "none",
              background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`,
              color: COLORS.white,
              fontSize: 13, fontWeight: 700,
              cursor: "pointer",
              boxShadow: `0 4px 16px ${COLORS.primary}40`,
              transition: "all 0.2s ease",
            }}
          >
            {wellnessMode ? (canLogToday ? "Log Weight" : `Log in ${daysUntilNextLog}d`) : (canLogToday ? "+ Log Stats" : `Log in ${daysUntilNextLog}d`)}
          </button>
        </div>
        <p style={{ color: COLORS.textSecondary, fontSize: 14, margin: 0 }}>
          {(() => {
            const isMonth6 = profile?.programKey?.startsWith("month6-");
            const baseKey = isMonth6 ? profile.programKey.replace("month6-", "") : profile?.programKey;
            const rawLabel = PROGRAMS[baseKey]?.label || "";
            const { name, levelTag } = getProgramParts(rawLabel);
            const effectiveLevel = profile?.effectiveLevel || profile?.experience || "";
            const levelLabel = effectiveLevel === "advanced" ? "Advanced" : effectiveLevel === "intermediate" ? "Intermediate" : effectiveLevel === "beginner" ? "Beginner" : effectiveLevel === "senior-beginner" ? "Senior Beginner" : effectiveLevel === "senior-intermediate" ? "Senior Intermediate" : levelTag;
            const cycleLabel = isMonth6 ? " (Evolved)" : "";
            const motivationalName = getProgramMotivationalName(profile?.programKey || "");
            const cleanName = isMonth6 ? getEvolvedProgramName(profile?.programKey || "") : (motivationalName || name || rawLabel.replace(/^(men's|women's|senior\s*)?(beginner|intermediate|advanced)\s*\d*x?\/?week?\s*[-—]?\s*/i, "").trim() || rawLabel);
            // Same defensive treatment as the identical Profile pattern -
            // an unconditional safety net regardless of the exact mechanism.
            const safeCleanName = String(cleanName ?? "");
            const safeLevelLabel = String(levelLabel ?? "");
            const nameHasLevel = safeLevelLabel && safeCleanName.toLowerCase().includes(safeLevelLabel.toLowerCase());
            if (!safeCleanName) return "Your current program";
            return (
              <span>
                <span style={{ color: COLORS.white, fontWeight: 600 }}>{safeCleanName}{cycleLabel}</span>
                {safeLevelLabel && !nameHasLevel ? <span style={{ color: COLORS.accent, fontSize: 12, marginLeft: 6, fontWeight: 600 }}>· {safeLevelLabel}</span> : null}
              </span>
            );
          })()}
        </p>
      </div>

      <div style={{ flex: 1, minHeight: 0, overflowY: "auto", WebkitOverflowScrolling: "touch" as any, padding: "0 24px 24px" }}>

        {/* Wellness mode banner */}
        {wellnessMode && (
          <div style={{
            background: `${COLORS.primary}15`, border: `1px solid ${COLORS.primary}30`,
            borderRadius: 14, padding: "12px 16px", marginBottom: 16,
            display: "flex", alignItems: "center", gap: 10,
          }}>
            <span style={{ fontSize: 18 }}>🌿</span>
            <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: 0, lineHeight: 1.5 }}>
              Wellness mode is on. Focus on consistency. Body measurements are paused.
            </p>
          </div>
        )}

        <ActiveWeeksCard
          streak={activeWeeksData.streak}
          bestStreak={activeWeeksData.bestStreak}
          thisWeekCount={activeWeeksData.thisWeekCount}
          weeklyBlocks={activeWeeksData.weeklyBlocks}
        />

        {/* ── Results Section ── */}
        <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: 0 }}>Results</p>
            {getActiveMetricHistory().length > 0 && (
              <button
                onClick={() => setShowMetricDetail(v => !v)}
                style={{ background: "transparent", border: `1px solid ${COLORS.border}`, borderRadius: 8, padding: "4px 10px", color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, cursor: "pointer" }}
              >
                {showMetricDetail ? "Hide Numbers" : "See Numbers"}
              </button>
            )}
          </div>

          {/* Metric toggle — shows lock state per metric */}
          <style>{`.metric-toggle-scroll::-webkit-scrollbar{display:none}`}</style>
          <div className="metric-toggle-scroll" style={{ display: "flex", gap: 8, marginBottom: 20, overflowX: "auto", msOverflowStyle: "none", scrollbarWidth: "none" } as any}>
            {metrics.map(m => {
              const isActive = activeMetric === m.id;
              const locked = !canLogMetric(m.id);
              return (
                <button
                  key={m.id}
                  onClick={() => { setActiveMetric(m.id); }}
                  style={{
                    padding: "8px 16px", borderRadius: 99, border: "none",
                    background: isActive ? MUSCLE_COLORS[m.id] : locked ? `${COLORS.border}80` : COLORS.border,
                    color: isActive ? COLORS.white : locked ? COLORS.textSecondary + "80" : COLORS.textSecondary,
                    fontSize: 13, fontWeight: 700, cursor: "pointer",
                    flexShrink: 0, transition: "all 0.2s ease",
                    boxShadow: isActive ? `0 4px 12px ${MUSCLE_COLORS[m.id]}40` : "none",
                    opacity: locked && !isActive ? 0.6 : 1,
                  }}
                >
                  {m.label}
                </button>
              );
            })}
          </div>

          {/* Time-range filter for the chart view specifically - the
              Numbers list right above stays a complete, unfiltered
              audit trail, since "did I ever log this?" is a different
              question than "how has this trended recently?" */}
          {!showMetricDetail && (
            <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
              {(["1M", "3M", "6M", "All"] as const).map((r) => (
                <button
                  key={r}
                  onClick={() => setChartRange(r)}
                  style={{
                    flex: 1, padding: "6px 0", borderRadius: 8, border: "none",
                    background: chartRange === r ? MUSCLE_COLORS[activeMetric] : COLORS.border,
                    color: chartRange === r ? COLORS.white : COLORS.textSecondary,
                    fontSize: 11, fontWeight: 700, cursor: "pointer",
                  }}
                >
                  {r}
                </button>
              ))}
            </div>
          )}

          {/* Numbers detail view — all logged entries for this metric */}
          {showMetricDetail ? (
            <div>
              <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 12px" }}>
                {metrics.find(m => m.id === activeMetric)?.label} History
              </p>
              {getActiveMetricHistory().map((entry, i, arr) => {
                const prevEntry = arr[i + 1]; // arr is newest-first, so next index = older entry
                const delta = prevEntry ? entry.value - prevEntry.value : null;
                const deltaColor = delta === null ? COLORS.textSecondary : delta < 0 ? COLORS.success : delta > 0 ? "#FF4D4D" : COLORS.textSecondary;
                const deltaLabel = delta === null ? "" : `${delta > 0 ? "+" : ""}${delta.toFixed(1)} ${activeMetric === "weight" ? weightUnit : measureUnit}`;
                return (
                  <div key={i} style={{
                    display: "flex", justifyContent: "space-between", alignItems: "center",
                    padding: "10px 0",
                    borderBottom: i < arr.length - 1 ? `1px solid ${COLORS.border}` : "none",
                  }}>
                    <div>
                      <p style={{ color: COLORS.white, fontSize: 16, fontWeight: 700, margin: "0 0 2px" }}>
                        {entry.value} {activeMetric === "weight" ? weightUnit : measureUnit}
                      </p>
                      <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>{entry.label}</p>
                    </div>
                    <div style={{ textAlign: "right" }}>
                      {delta !== null && (
                        <p style={{ color: deltaColor, fontSize: 13, fontWeight: 700, margin: "0 0 2px" }}>{deltaLabel}</p>
                      )}
                      <p style={{ color: COLORS.textSecondary, fontSize: 13, margin: 0 }}>{entry.date}</p>
                    </div>
                  </div>
                );
              })}
              {!activeMetricCanLog && (
                <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "12px 0 0" }}>
                  Next {metrics.find(m => m.id === activeMetric)?.label} log available in {daysUntilNextLog} day{daysUntilNextLog !== 1 ? "s" : ""}
                </p>
              )}
            </div>
          ) : (
            <MiniGraph data={getActiveData()} color={MUSCLE_COLORS[activeMetric]} unit={activeMetric === "weight" ? weightUnit : measureUnit} activeMetric={activeMetric} />
          )}
        </div>

        {/* ── Consistency Section ── */}
        <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
          <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: "0 0 16px" }}>This Cycle</p>

          <div style={{ display: "flex", gap: 12, marginBottom: 16 }}>
            {/* Streak */}
            <div style={{ flex: 1, background: COLORS.background, borderRadius: 14, padding: "16px 12px", textAlign: "center", border: `1px solid ${COLORS.border}` }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}>
                <p style={{ fontSize: 28, fontWeight: 900, color: streak > 0 ? COLORS.accent : COLORS.textSecondary, margin: "0 0 2px" }}>
                  {streak}
                </p>
                {streak > 0 && <Star size={16} color={COLORS.accent} fill={COLORS.accent} strokeWidth={0} style={{ marginTop: -2 }} />}
              </div>
              <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8, margin: 0 }}>Streak</p>
            </div>
            {/* Completed */}
            <div style={{ flex: 1, background: COLORS.background, borderRadius: 14, padding: "16px 12px", textAlign: "center", border: `1px solid ${COLORS.border}` }}>
              <p style={{ fontSize: 28, fontWeight: 900, color: COLORS.success, margin: "0 0 2px" }}>{totalSessions}</p>
              <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8, margin: 0 }}>Sessions</p>
            </div>
            {/* This week */}
            <div style={{ flex: 1, background: COLORS.background, borderRadius: 14, padding: "16px 12px", textAlign: "center", border: `1px solid ${COLORS.border}` }}>
              <p style={{ fontSize: 28, fontWeight: 900, color: COLORS.accent, margin: "0 0 2px" }}>{sessionsThisWeek}/{weeklyTarget}</p>
              <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.8, margin: 0 }}>This Week</p>
            </div>
          </div>

          {/* Completion bar */}
          <div style={{ background: COLORS.background, borderRadius: 14, padding: "14px 16px", border: `1px solid ${COLORS.border}` }}>
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
              <span style={{ color: COLORS.white, fontSize: 14, fontWeight: 600 }}>Program completion</span>
              <span style={{ color: COLORS.accent, fontSize: 14, fontWeight: 700 }}>{completionPct}%</span>
            </div>
            <div style={{ height: 6, background: COLORS.border, borderRadius: 99, overflow: "hidden" }}>
              <div style={{
                height: "100%", borderRadius: 99,
                background: `linear-gradient(90deg, ${COLORS.primary}, ${COLORS.accent})`,
                width: `${completionPct}%`, transition: "width 0.4s ease",
              }} />
            </div>
            <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: "8px 0 0" }}>
              {totalSessions} of 30 sessions complete · Day {currentDay} of 30
            </p>
          </div>
        </div>

        {/* ── 30-Day Calendar ── */}
        <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: 0 }}>Program Calendar</p>
            <span style={{ color: COLORS.accent, fontSize: 12, fontWeight: 700 }}>Day {currentDay} of 30</span>
          </div>
          <ThirtyDayCalendar completedDays={completedDays} restDays={restDayNumbers} totalDays={30} currentDay={currentDay} />
          <div style={{ display: "flex", gap: 12, marginTop: 16, flexWrap: "wrap" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <div style={{ width: 12, height: 12, borderRadius: 3, background: `${COLORS.success}25`, border: `1px solid ${COLORS.success}` }} />
              <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>Completed</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 12 }}>🌙</span>
              <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>Rest Day</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <div style={{ width: 12, height: 12, borderRadius: 3, background: `${COLORS.primary}40`, border: `1px solid ${COLORS.accent}` }} />
              <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>Today</span>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
              <div style={{ width: 12, height: 12, borderRadius: 3, border: `1px solid ${COLORS.border}` }} />
              <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>Upcoming</span>
            </div>
          </div>
        </div>

        {/* ── Body Measurements ── */}
        {!wellnessMode && logs.length > 1 && (logs[logs.length - 1].waist || logs[logs.length - 1].hips || logs[logs.length - 1].arms || logs[logs.length - 1].chest || logs[logs.length - 1].neck || logs[logs.length - 1].thighs) && (
          <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: "0 0 16px" }}>Measurements</p>
            {[
              [
                { key: "waist", label: "Waist", color: "#FF6B35", goalDown: true },
                { key: "hips", label: "Hips", color: "#A78BFA", goalDown: false },
                { key: "arms", label: "Arms", color: "#2ECC71", goalDown: false },
              ],
              [
                { key: "chest", label: "Chest", color: "#F59E0B", goalDown: false },
                { key: "neck", label: "Neck", color: "#06B6D4", goalDown: true },
                { key: "thighs", label: "Thighs", color: "#EC4899", goalDown: false },
              ],
            ].map((row, ri) => (
              <div key={ri} style={{ display: "flex", gap: 10, marginBottom: ri === 0 ? 10 : 0 }}>
                {row.map(m => {
                  const latest = [...logs].reverse().find(l => l[m.key]);
                  const first = logs.find(l => l[m.key]);
                  if (!latest) return <div key={m.key} style={{ flex: 1 }} />;
                  const diff = latest[m.key] - (first?.[m.key] || latest[m.key]);
                  const sign = diff > 0 ? "+" : "";
                  const isGain = diff > 0;
                  const changeColor = m.goalDown
                    ? (isGain ? "#FF4D4D" : COLORS.success)
                    : (isGain ? COLORS.success : "#FF4D4D");
                  return (
                    <div key={m.key} style={{ flex: 1, background: COLORS.background, borderRadius: 14, padding: "12px 8px", border: `1px solid ${COLORS.border}`, textAlign: "center" }}>
                      <p style={{ color: m.color, fontSize: 18, fontWeight: 800, margin: "0 0 2px" }}>{latest[m.key]}{measureUnit}</p>
                      <p style={{ color: COLORS.textSecondary, fontSize: 10, fontWeight: 600, textTransform: "uppercase", letterSpacing: 0.5, margin: "0 0 3px" }}>{m.label}</p>
                      {diff !== 0 && (
                        <p style={{ color: changeColor, fontSize: 10, fontWeight: 700, margin: 0 }}>
                          {sign}{diff.toFixed(1)}{measureUnit}
                        </p>
                      )}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        )}

        {/* ── Workout History Section ── */}
        {(() => {
          // Real bug found via real-device testing: this was gated on
          // profile.sessionsCompleted, which only counts LIFTING sessions
          // (incremented by the lifting completion flow specifically) -
          // a cardio-only session (a walk, a run) never touches that
          // field. Active Weeks sits right above this and correctly
          // counts lifting AND cardio together, which meant someone
          // could see a real cardio session reflected there while this
          // entire section stayed permanently blank underneath it - not
          // a glitch, the gate itself was simply checking the wrong
          // count. sessionHistory.length is the real fetched list,
          // which already includes every session type.
          if (sessionHistory.length === 0) return null;
          const sessionsCompleted = sessionHistory.length;

         // ── History List View ──
          const PREVIEW_COUNT = 3;
          const MAX_COUNT = 20;
          const showingAll = historyExpanded;
          const displaySessions = showingAll ? sessionHistory.slice(0, MAX_COUNT) : sessionHistory.slice(0, PREVIEW_COUNT);
          const groupedHistory = (() => {
            const byCycle: Record<number, Record<number, any[]>> = {};
            displaySessions.forEach(session => {
              const cycle = session.cycleNumber || 1;
              const dayNum = session.programDay || 1;
              const week = Math.ceil(dayNum / 7);
              if (!byCycle[cycle]) byCycle[cycle] = {};
              if (!byCycle[cycle][week]) byCycle[cycle][week] = [];
              byCycle[cycle][week].push(session);
            });
            return byCycle;
          })();
          const cycleKeys = Object.keys(groupedHistory).map(Number).sort((a, b) => b - a);        

          return (
            <div style={{ background: COLORS.card, borderRadius: 20, padding: "20px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
                <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: 0 }}>Workout History</p>
                <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>{sessionsCompleted} sessions</p>
              </div>

              {!historyLoaded && historyLoading && (
                <p style={{ color: COLORS.textSecondary, fontSize: 13, textAlign: "center", padding: "12px 0", margin: 0 }}>Loading your workout history...</p>
              )}
              {historyLoaded && sessionHistory.length === 0 && (
                <p style={{ color: COLORS.textSecondary, fontSize: 13, textAlign: "center", padding: "12px 0", margin: 0 }}>No saved workouts yet. Complete a session and it will appear here.</p>
              )}

              {historyLoaded && cycleKeys.map(cycle => {
                const weeks = groupedHistory[cycle];
                // Sorted by each group's most recent real session date, not
                // by the raw week number itself. A level change or any other
                // program restart resets programDay (and so this derived
                // week number) back down, but doesn't undo time - without
                // this, a brand new Week 1 right after a restart could sort
                // below an older Week 2 from before it, making the list read
                // as if time had gone backwards.
                const getLatestInWeek = (wk: number) => Math.max(...weeks[wk].map((s: any) => {
                  const d = s.completedAt?.toDate ? s.completedAt.toDate() : new Date(s.completedAt);
                  return d.getTime();
                }));
                const weekKeys = Object.keys(weeks).map(Number).sort((a, b) => getLatestInWeek(b) - getLatestInWeek(a));
                return (
                  <div key={cycle} style={{ marginBottom: 20 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
                      <div style={{ background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`, borderRadius: 8, padding: "4px 12px" }}>
                        <span style={{ color: COLORS.white, fontSize: 11, fontWeight: 800, letterSpacing: 1 }}>MONTH {cycle}</span>
                      </div>
                      <div style={{ flex: 1, height: 1, background: COLORS.border }} />
                      <span style={{ color: COLORS.textSecondary, fontSize: 11 }}>{Object.values(weeks).flat().length} sessions</span>
                    </div>
                    {weekKeys.map(week => (
                      <div key={week} style={{ marginBottom: 12 }}>
                        <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase" as const, margin: "0 0 8px", paddingLeft: 4 }}>Week {week}</p>
                        <div style={{ background: COLORS.background, borderRadius: 14, border: `1px solid ${COLORS.border}`, overflow: "hidden" }}>
                          {weeks[week].map((session: any, si: number) => (
                            <div key={session.id || si} onClick={() => setSelectedSession(session)} style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 14px", cursor: "pointer", borderBottom: si < weeks[week].length - 1 ? `1px solid ${COLORS.border}` : "none" }}>
                              <div style={{ width: 32, height: 32, borderRadius: 99, flexShrink: 0, background: `${COLORS.success}20`, border: `1px solid ${COLORS.success}40`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                                <Check size={14} color={COLORS.success} strokeWidth={3} />
                              </div>
                              <div style={{ flex: 1 }}>
                                <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 600, margin: "0 0 1px", lineHeight: 1.3 }}>{session.type && session.type !== "gym" ? (session.customActivityName || ACTIVITY_TYPES.find((a) => a.key === session.type)?.label || session.type) : (deriveWorkoutTitle(session.groups || [], undefined, session.dayFocus) || session.programName || session.dayTitle || "Workout")}</p>
                                <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: "0 0 4px" }}>{session.completedAt?.toDate ? session.completedAt.toDate().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : `Day ${session.programDay || "—"}`}</p>

                              </div>
                              <ChevronRight size={15} color={COLORS.border} />
                            </div>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>
                );
              })}

{historyLoaded && sessionHistory.length > PREVIEW_COUNT && (
                <button onClick={() => onNavigate('history')} style={{ width: "100%", padding: "12px", background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 12, color: COLORS.primary, fontSize: 13, fontWeight: 700, cursor: "pointer", marginTop: 4 }}>
                  See all {sessionHistory.length} workouts →
                </button>
              )}
              {historyLoaded && sessionHistory.length > 0 && (
                <p style={{ color: COLORS.textSecondary, fontSize: 12, textAlign: "center", margin: "4px 0 0" }}>{sessionHistory.length} session{sessionHistory.length !== 1 ? "s" : ""} saved · Tap any to review</p>
              )}
            </div>
          );
        })()}
      </div>

      {/* Log Stats Modal */}
      {showLogModal && (
        <LogStatsModal
          onSave={handleSaveLog}
          onClose={() => setShowLogModal(false)}
          unit={unit}
          isBaseline={logs.length === 0}
          wellnessMode={wellnessMode}
          canLogMetric={canLogMetric}
          getMetricDaysSinceLastLog={getMetricDaysSinceLastLog}
        />
      )}

      <BottomNav active="progress" onNavigate={onNavigate} />
    </div>
  );
};

// ─── History Screen ───────────────────────────────────────────────────────────
const HistoryScreen = ({ profile, onBack, onNavigate = (s: string) => {} }) => {
  const [sessions, setSessions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSession, setSelectedSession] = useState<any>(null);
  const [expandedYears, setExpandedYears] = useState<Record<number, boolean>>({});
  const [expandedMonths, setExpandedMonths] = useState<Record<string, boolean>>({});

  useEffect(() => {
    if (profile?.uid) {
      fetchWorkoutHistory(profile?.uid || auth.currentUser?.uid || "", (fastS) => setSessions(fastS)).then(s => {
        setSessions(s);
        setLoading(false);
        // Auto-expand current year and most recent month
        const currentYear = new Date().getFullYear();
        setExpandedYears({ [currentYear]: true });
        if (s.length > 0) {
          const first = s[0];
          const date = first.completedAt?.toDate ? first.completedAt.toDate() : new Date(first.completedAt);
          const cycle = first.cycleNumber || 1;
          setExpandedMonths({ [`${date.getFullYear()}-${cycle}`]: true });
        }
      });
    }
  }, [profile?.uid]);

  if (selectedSession && selectedSession.type && selectedSession.type !== "gym") {
    return (
      <ActivityDetailView
        session={selectedSession}
        sessionHistory={sessions}
        profile={profile}
        onClose={() => setSelectedSession(null)}
      />
    );
  }

  if (selectedSession) {
    const groups = selectedSession.groups || [];
    // Deliberately not trusting selectedSession.workoutType or heroImage at
    // all - always derive purely from dayFocus text and recompute fresh. A
    // real polluted session document was found tonight with a group-level
    // value sitting where a day-level type should be. Never trusting any
    // stored type/image field here means this screen can't be affected by
    // that class of problem regardless of its root cause.
    // dayFocus turns out to be a broken, generic fallback field that just
    // says "Workout" in real data - confirmed directly in Firestore. Deriving
    // fresh from the session's actual exercises is the only reliable source.
    const realMuscles2: string[] = [];
    groups.forEach((g: any) => {
      if (g.type === "cardio") return;
      (g.exercises || []).forEach((ex: any) => {
        const m = (EXERCISES_DATA as any)[ex.id]?.muscle || "";
        if (m && !realMuscles2.includes(m)) realMuscles2.push(m);
      });
    });
    const focusLower2 = realMuscles2.join(", ").toLowerCase();
    const wType =
      (focusLower2.includes("lower") || focusLower2.includes("leg") || focusLower2.includes("glute") || focusLower2.includes("hamstring") || focusLower2.includes("quad") || focusLower2.includes("calf") || focusLower2.includes("calve") ? "lower-body"
      : focusLower2.includes("push") || focusLower2.includes("chest") || focusLower2.includes("tricep") || focusLower2.includes("shoulder") ? "push"
      : focusLower2.includes("pull") || focusLower2.includes("back") || focusLower2.includes("bicep") || focusLower2.includes("lat") ? "upper-body"
      : focusLower2.includes("upper") ? "upper-body"
      : focusLower2.includes("abs") || focusLower2.includes("core") ? "core"
      : focusLower2.includes("cardio") ? "cardio"
      : "full-body");
      const heroImage = getWorkoutImage(wType, selectedSession.programDay || 1);
    const bgPos = wType === "lower-body" ? "center 60%" : "center top";
    const fakeDay = {
      dayNum: selectedSession.programDay || 1,
      title: expandDayTitle(selectedSession.dayTitle || selectedSession.dayFocus || "Workout"),
      focus: selectedSession.dayFocus || "Workout",
      isRest: false,
      groups,
      notes: [],
    };
    return (
      <WorkoutListScreen
        day={fakeDay}
        filteredGroups={groups}
        onStart={() => {}}
        onBack={() => setSelectedSession(null)}
        workoutImage={heroImage}
        programDay={selectedSession.programDay || 1}
        programWeek={Math.ceil((selectedSession.programDay || 1) / 7)}
        isReview={true}
        bgPosition={bgPos}
        equipmentPreference={selectedSession.equipmentPreference || profile?.equipmentPreference || "gym-and-bands"}
        buildingEquipment={profile?.buildingEquipment || []}
        historyMeta={{
          completedDateStr: selectedSession.completedDateStr,
          programLabel: selectedSession.programLabel,
          cycleNumber: selectedSession.cycleNumber,
          weightsLogged: selectedSession.weightsLogged || null,
          weightNotes: selectedSession.weightNotes || null,
        }}
      />
    );
  }

  // Group sessions by year → cycle(month) → week
  const grouped: Record<number, Record<number, Record<number, any[]>>> = {};
  sessions.forEach(session => {
    const date = session.completedAt?.toDate ? session.completedAt.toDate() : new Date(session.completedAt || Date.now());
    const year = date.getFullYear();
    const cycle = session.cycleNumber || 1;
    const week = Math.ceil((session.programDay || 1) / 7);
    if (!grouped[year]) grouped[year] = {};
    if (!grouped[year][cycle]) grouped[year][cycle] = {};
    if (!grouped[year][cycle][week]) grouped[year][cycle][week] = [];
    grouped[year][cycle][week].push(session);
  });

  const years = Object.keys(grouped).map(Number).sort((a, b) => b - a);

  const toggleYear = (year: number) => setExpandedYears(p => ({ ...p, [year]: !p[year] }));
  const toggleMonth = (key: string) => setExpandedMonths(p => ({ ...p, [key]: !p[key] }));

  return (
    <div style={{ height: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column" }}>
      {/* Header */}
      <div style={{ padding: "52px 20px 16px", display: "flex", alignItems: "center", gap: 12, borderBottom: `1px solid ${COLORS.border}` }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: COLORS.white, padding: 4 }}>
          <ArrowLeft size={22} color={COLORS.white} />
        </button>
        <div>
          <h2 style={{ color: COLORS.white, fontSize: 20, fontWeight: 800, margin: 0 }}>Workout History</h2>
          <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>{sessions.length} sessions total</p>
        </div>
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflowY: "auto", padding: "16px 16px 100px" }}>
        {loading && <p style={{ color: COLORS.textSecondary, textAlign: "center", marginTop: 40 }}>Loading history...</p>}
        {!loading && sessions.length === 0 && <p style={{ color: COLORS.textSecondary, textAlign: "center", marginTop: 40 }}>No workouts saved yet.</p>}

        {years.map(year => (
          <div key={year} style={{ marginBottom: 16 }}>
            {/* Year header */}
            <button onClick={() => toggleYear(year)} style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", background: "none", border: "none", cursor: "pointer", padding: "10px 0", marginBottom: 8 }}>
              <span style={{ color: COLORS.white, fontSize: 18, fontWeight: 800 }}>{year}</span>
              <ChevronRight size={18} color={COLORS.textSecondary} style={{ transform: expandedYears[year] ? "rotate(90deg)" : "none", transition: "transform 0.2s" }} />
            </button>

            {expandedYears[year] && Object.keys(grouped[year]).map(Number).sort((a, b) => b - a).map(cycle => {
              const monthKey = `${year}-${cycle}`;
              const allSessionsInMonth = Object.values(grouped[year][cycle]).flat();
              return (
                <div key={cycle} style={{ marginBottom: 10, marginLeft: 8 }}>
                  {/* Month header */}
                  <button onClick={() => toggleMonth(monthKey)} style={{ width: "100%", display: "flex", alignItems: "center", justifyContent: "space-between", background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 12, cursor: "pointer", padding: "10px 14px", marginBottom: 6 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <div style={{ background: `linear-gradient(135deg, ${COLORS.primary}, ${COLORS.accent})`, borderRadius: 6, padding: "3px 10px" }}>
                        <span style={{ color: COLORS.white, fontSize: 11, fontWeight: 800, letterSpacing: 1 }}>MONTH {cycle}</span>
                      </div>
                      <span style={{ color: COLORS.textSecondary, fontSize: 12 }}>{allSessionsInMonth.length} sessions</span>
                    </div>
                    <ChevronRight size={15} color={COLORS.textSecondary} style={{ transform: expandedMonths[monthKey] ? "rotate(90deg)" : "none", transition: "transform 0.2s" }} />
                  </button>

                  {/* Sorted by each group's most recent real session date,
                      not by the raw week number itself - see the matching
                      comment in ProgressScreen's identical grouping logic
                      for the full reasoning (a program restart resets this
                      derived week number, but not time). */}
                  {expandedMonths[monthKey] && Object.keys(grouped[year][cycle]).map(Number).sort((a, b) => {
                    const getLatestInWeek = (wk: number) => Math.max(...grouped[year][cycle][wk].map((s: any) => {
                      const d = s.completedAt?.toDate ? s.completedAt.toDate() : new Date(s.completedAt);
                      return d.getTime();
                    }));
                    return getLatestInWeek(b) - getLatestInWeek(a);
                  }).map(week => (
                    <div key={week} style={{ marginLeft: 8, marginBottom: 8 }}>
                      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 6px", paddingLeft: 4 }}>Week {week}</p>
                      <div style={{ background: COLORS.background, borderRadius: 12, border: `1px solid ${COLORS.border}`, overflow: "hidden" }}>
                        {grouped[year][cycle][week].map((session: any, si: number) => (
                          <div key={session.id || si} onClick={() => setSelectedSession(session)} style={{ display: "flex", alignItems: "center", gap: 12, padding: "13px 14px", cursor: "pointer", borderBottom: si < grouped[year][cycle][week].length - 1 ? `1px solid ${COLORS.border}` : "none" }}>
                            <div style={{ width: 32, height: 32, borderRadius: 99, flexShrink: 0, background: `${COLORS.success}20`, border: `1px solid ${COLORS.success}40`, display: "flex", alignItems: "center", justifyContent: "center" }}>
                              <Check size={14} color={COLORS.success} strokeWidth={3} />
                            </div>
                            <div style={{ flex: 1 }}>
                              <p style={{ color: COLORS.white, fontSize: 14, fontWeight: 600, margin: "0 0 1px", lineHeight: 1.3 }}>{session.type && session.type !== "gym" ? (session.customActivityName || ACTIVITY_TYPES.find((a) => a.key === session.type)?.label || session.type) : (deriveWorkoutTitle(session.groups || [], undefined, session.dayFocus) || session.programName || session.dayTitle || "Workout")}</p>
                              <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: 0 }}>{session.completedAt?.toDate ? session.completedAt.toDate().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }) : `Day ${session.programDay || "—"}`}</p>
                            </div>
                            <ChevronRight size={15} color={COLORS.border} />
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              );
            })}
          </div>
        ))}
      </div>

      <BottomNav active="progress" onNavigate={onNavigate} />
    </div>
  );
};
// ─── Profile Screen ───────────────────────────────────────────────────────────

// ─── FAQ ──────────────────────────────────────────────────────────────────────
const FAQ_ITEMS = [
  {
    q: "How does my program work?",
    a: "Your program is matched to your experience level, goals, and how many days per week you want to train. Each day has a specific workout already planned. When you finish a cycle you get a fresh program that builds on what you completed.",
  },
  {
    q: "What happens if I miss a day?",
    a: "Just pick up where you left off. The program doesn't skip ahead. You continue from your current day whenever you're ready. Your streak resets but your program position stays exactly where it was.",
  },
 {
    q: "Can I change my program settings?",
    a: "Yes. You can edit your goal, experience level, days per week, and session length from this screen. Changing any of those will recalibrate your program starting fresh from Day 1.",
  },
  {
    q: "How do I update my injury or physical limitations?",
    a: "Go to Profile and update the injury or limitation field. Once saved, your next session will filter out exercises that could aggravate it and the swap feature will prioritize safer alternatives. If you have not done today's workout yet, start the workout and tap the Swap Exercise button on any exercise to replace it.",
  },
  {
    q: "Does working out here count toward my stats?",
    a: "Every workout completed here is counted in your personal progress. If this is your home building, your sessions also contribute to the building's community stats.",
  },
  {
    q: "What does the Fitness Assistant do?",
    a: "The Fitness Assistant knows your actual program, today's workout, and where you are in your cycle. Ask it anything about your training, exercises, nutrition, recovery, or how the app works. Find it by tapping Coach in the bottom menu.",
  },
  {
    q: "What is Power 24?",
    a: "Power 24 is a collection of 24 all-natural smoothie recipes included with your membership. Each one is built around real ingredients targeting hydration, recovery, energy, and performance. Find it on the home screen.",
  },
  {
    q: "How do I update my profile photo?",
    a: "Tap \"Change photo\" below your name at the top of this screen to pick a new image from your camera roll, or \"Remove photo\" to remove it. It updates instantly.",
  },
  {
    q: "I moved to a new building. What happens to my progress?",
    a: "Nothing is lost. Enter your new building's invite code and confirm it as your home. All your history, streak, and program progress carry over automatically.",
  },
  {
    q: "Who can see my workout data?",
    a: "Nobody except you. Your building manager only sees anonymous building-wide totals like total sessions and weekly averages. Your name and individual activity are never visible to them.",
  },
  {
    q: "How do I contact support?",
    a: "Email support@fitmakesenz.com and a real person will follow up with you. For building-specific questions like invite codes, contact your building manager or front desk.",
  },
];

const FAQSection = () => {
  const [openIndex, setOpenIndex] = useState<number | null>(null);
  return (
    <div style={{ background: COLORS.card, borderRadius: 20, padding: "4px 20px 4px", marginBottom: 16, border: `1px solid ${COLORS.border}` }}>
      <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: "16px 0 4px" }}>FAQ</p>
      {FAQ_ITEMS.map((item, i) => (
        <div key={i} style={{ borderBottom: i < FAQ_ITEMS.length - 1 ? `1px solid ${COLORS.border}` : "none" }}>
          <button
            onClick={() => setOpenIndex(openIndex === i ? null : i)}
            style={{
              width: "100%", background: "none", border: "none", padding: "14px 0",
              display: "flex", alignItems: "center", justifyContent: "space-between",
              cursor: "pointer", textAlign: "left" as const, gap: 12,
            }}
          >
            <span style={{ color: COLORS.white, fontSize: 14, fontWeight: 600, lineHeight: 1.4, flex: 1 }}>{item.q}</span>
            <span style={{
              color: COLORS.accent, fontSize: 18, fontWeight: 300, flexShrink: 0,
              transform: openIndex === i ? "rotate(45deg)" : "rotate(0deg)",
              transition: "transform 0.2s ease", lineHeight: 1,
            }}>+</span>
          </button>
          {openIndex === i && (
            <p style={{
              color: COLORS.textSecondary, fontSize: 13, margin: "0 0 16px",
              lineHeight: 1.6, paddingRight: 24,
            }}>{item.a}</p>
          )}
        </div>
      ))}
    </div>
  );
};


// ─── My Notes Screen ──────────────────────────────────────────────────────────
const MyNotesScreen = ({ profile, onBack }) => {
  const [notes, setNotes] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const uid = profile?.uid;

  useEffect(() => {
    if (!uid) return;
    // Same fast-then-verify pattern used for notifications - forces an
    // instant cache-only first read (which the plain getDoc() default
    // doesn't reliably guarantee) so notes appear immediately regardless
    // of connection quality, with a real server read quietly confirming
    // and correcting in the background afterward.
    const load = async () => {
      const ref = doc(db, "users", uid, "coachingNotes", "notes");
      try {
        const cacheSnap = await getDocFromCache(ref);
        if (cacheSnap.exists()) {
          setNotes(cacheSnap.data().notes || []);
          setLoading(false);
        }
      } catch (e) {}
      try {
        const snap = await getDocFromServer(ref);
        if (snap.exists()) setNotes(snap.data().notes || []);
      } catch (e) {}
      setLoading(false);
    };
    load();
  }, [uid]);

  const deleteNote = async (id: string) => {
    const updated = notes.filter(n => n.id !== id);
    setNotes(updated);
    try {
      const ref = doc(db, "users", uid, "coachingNotes", "notes");
      await setDoc(ref, { notes: updated });
    } catch (e) {}
  };

  // Group by Month/Year
  const grouped: Record<string, any[]> = {};
  notes.forEach(note => {
    const d = new Date(note.savedAt);
    const key = d.toLocaleDateString("en-US", { month: "long", year: "numeric" });
    if (!grouped[key]) grouped[key] = [];
    grouped[key].push(note);
  });
  const groupKeys = Object.keys(grouped);

  return (
    <div style={{ height: "100vh", background: COLORS.background, fontFamily: "'Inter', sans-serif", display: "flex", flexDirection: "column" }}>
      {/* Header */}
      <div style={{ padding: "52px 24px 16px", display: "flex", alignItems: "center", gap: 14, flexShrink: 0, borderBottom: `1px solid ${COLORS.border}` }}>
        <button onClick={onBack} style={{ background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 12, width: 40, height: 40, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0 }}>
          <ArrowLeft size={18} color={COLORS.white} />
        </button>
        <div style={{ flex: 1 }}>
          <h1 style={{ color: COLORS.white, fontSize: 20, fontWeight: 800, margin: "0 0 2px", letterSpacing: -0.5 }}>My Notes</h1>
          <p style={{ color: COLORS.textSecondary, fontSize: 12, margin: 0 }}>Saved from your coaching sessions</p>
        </div>
        <div style={{ background: COLORS.card, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "4px 12px" }}>
          <span style={{ color: COLORS.textSecondary, fontSize: 12, fontWeight: 600 }}>{notes.length} / 200</span>
        </div>
      </div>

      {/* Content */}
      <div style={{ flex: 1, overflowY: "auto", padding: "20px 20px 40px", WebkitOverflowScrolling: "touch" as any }}>
        {loading && (
          <div style={{ display: "flex", justifyContent: "center", paddingTop: 60 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 14 }}>Loading notes...</p>
          </div>
        )}

        {!loading && notes.length === 0 && (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", paddingTop: 80, gap: 12 }}>
            <div style={{ fontSize: 48 }}>🔖</div>
            <p style={{ color: COLORS.white, fontSize: 18, fontWeight: 700, margin: 0, textAlign: "center" }}>No saved notes yet</p>
            <p style={{ color: COLORS.textSecondary, fontSize: 14, margin: 0, textAlign: "center", lineHeight: 1.5, maxWidth: 260 }}>Long-press any coach message in the Fitness Assistant to save it here.</p>
          </div>
        )}

        {!loading && groupKeys.map(monthYear => (
          <div key={monthYear} style={{ marginBottom: 28 }}>
            <p style={{ color: COLORS.textSecondary, fontSize: 11, fontWeight: 700, letterSpacing: 1.5, textTransform: "uppercase", margin: "0 0 12px" }}>{monthYear}</p>
            <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
              {grouped[monthYear].map(note => (
                <div key={note.id} style={{
                  background: COLORS.card, border: `1px solid ${COLORS.border}`,
                  borderRadius: 16, padding: "16px 18px",
                  display: "flex", gap: 12, alignItems: "flex-start",
                }}>
                  <div style={{ flex: 1 }}>
                    <p style={{ color: COLORS.white, fontSize: 14, margin: "0 0 6px", lineHeight: 1.6 }}>{note.text}</p>
                    <p style={{ color: COLORS.textSecondary, fontSize: 11, margin: 0 }}>
                      {new Date(note.savedAt).toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric" })} · {new Date(note.savedAt).toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}
                    </p>
                  </div>
                  <button
                    onClick={() => deleteNote(note.id)}
                    style={{ background: "transparent", border: "none", cursor: "pointer", padding: "2px 4px", flexShrink: 0, opacity: 0.5 }}>
                    <span style={{ color: COLORS.textSecondary, fontSize: 18 }}>×</span>
                  </button>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// ─── Cardio Tracking ────────────────────────────────────────────────────────
// Great-circle distance between two lat/lng points, in meters. Standard
// Haversine formula - accurate enough for GPS-tracking purposes (the GPS
// hardware's own error margin is far larger than this formula's).
const haversineDistanceMeters = (lat1: number, lng1: number, lat2: number, lng2: number): number => {
  const R = 6371000;
  const toRad = (d: number) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return R * (2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
};

// Below this speed, the person is considered stopped/walking-a-break rather
// than actively doing the activity - matches a slow amble, not real
// movement. Auto-pause triggers only after staying below this for
// AUTO_PAUSE_TRIGGER_SECONDS, not on a single slow reading, since GPS speed
// is noisy and a single low sample (e.g. briefly waiting at a crosswalk,
// or GPS jitter while running normally) shouldn't flicker the state.
const AUTO_PAUSE_SPEED_THRESHOLD_MPS = 0.6;
const AUTO_PAUSE_TRIGGER_SECONDS = 12;
const AUTO_PAUSE_GRACE_PERIOD_SECONDS = 15; // no auto-pause evaluation for the first 15s after Start, so early GPS jitter before real movement can't trigger it

// Standard MET (metabolic equivalent) values per activity type - widely
// used, defensible reference numbers for estimating calorie burn from
// duration and body weight alone, when no real wearable data is available.
// Deliberately only applied to cardio activities (where a reasonable
// single MET value per activity type is a fair approximation) - NEVER to
// gym/strength sessions, where effort varies far too much session to
// session for a duration-only estimate to be honest. Calories = MET x
// weight(kg) x duration(hours), the standard formula.
const CARDIO_MET_VALUES: Record<string, number> = {
  run: 9.8,
  bike: 7.5,
  hike: 6.0,
  walk: 3.5,
  row: 7.0,
  swim: 6.0,
  elliptical: 5.0,
  treadmill: 8.3,
  "indoor-bike": 7.0,
  basketball: 8.0,
  soccer: 7.0,
  padel: 6.0,
  // Padel has no entry of its own in the standard MET compendium (too
  // new a sport) - 6.0 borrows from doubles tennis, the closest
  // well-documented analog in physical demand.
  yoga: 2.5, // general/hatha yoga, standard compendium value
  pilates: 3.0, // general studio-class pilates, standard compendium value
  meditation: 1.3, // seated meditation, near resting metabolic rate, standard compendium value
  stretching: 2.3, // light static stretching, standard compendium value
  other: 5.0,
};

const estimateCardioCalories = (activityType: string, durationSeconds: number, weightLbs?: number): number | undefined => {
  if (!weightLbs || weightLbs <= 0) return undefined;
  const met = CARDIO_MET_VALUES[activityType] ?? CARDIO_MET_VALUES.other;
  const weightKg = weightLbs * 0.453592;
  const hours = durationSeconds / 3600;
  return Math.round(met * weightKg * hours);
};

// Free-tier public token - Mapbox's Static Images API only renders a
// finished route (never live navigation), which comfortably fits their
// free monthly allowance for an app this size. Only ever used to build a
// read-only image URL, never for anything requiring a secret/private token.
// Read from an env var (set in .env.local, gitignored) rather than
// hardcoded - GitHub's push protection correctly flags any Mapbox token
// literal in source, even this public-token type, so this avoids that
// entirely and matches standard practice for any embedded API key.
const MAPBOX_ACCESS_TOKEN = import.meta.env.VITE_MAPBOX_TOKEN || "";

// Downsamples a route to at most maxPoints, taking evenly-spaced points -
// keeps the Static Images API's URL length well within safe limits (a
// tracked run/hike can accumulate hundreds of GPS points, and a static
// map image doesn't need every single ping's precision to look right,
// just a faithful approximation of the path's actual shape).
// Perpendicular distance from a point to the line segment between two
// other points, in raw lat/lng space - fine for this purpose (deciding
// which points visually define the route's shape), since a real tracked
// route rarely spans enough degrees for lat/lng's non-uniform real-world
// distance-per-degree to visibly distort which points get kept.
const perpendicularDistance = (
  point: { lat: number; lng: number },
  lineStart: { lat: number; lng: number },
  lineEnd: { lat: number; lng: number }
): number => {
  const dx = lineEnd.lat - lineStart.lat;
  const dy = lineEnd.lng - lineStart.lng;
  if (dx === 0 && dy === 0) {
    return Math.sqrt((point.lat - lineStart.lat) ** 2 + (point.lng - lineStart.lng) ** 2);
  }
  const t = ((point.lat - lineStart.lat) * dx + (point.lng - lineStart.lng) * dy) / (dx * dx + dy * dy);
  const clampedT = Math.max(0, Math.min(1, t));
  const projLat = lineStart.lat + clampedT * dx;
  const projLng = lineStart.lng + clampedT * dy;
  return Math.sqrt((point.lat - projLat) ** 2 + (point.lng - projLng) ** 2);
};

// Standard Douglas-Peucker line simplification - recursively keeps only
// the points that actually define the route's shape (a real turn),
// discarding points on stretches that are already nearly straight between
// their neighbors. First and last point of any segment are always kept,
// so a route's real start and end are never lost.
const douglasPeucker = (points: { lat: number; lng: number }[], epsilon: number): { lat: number; lng: number }[] => {
  if (points.length < 3) return points;
  let maxDist = 0;
  let splitIndex = 0;
  const end = points.length - 1;
  for (let i = 1; i < end; i++) {
    const dist = perpendicularDistance(points[i], points[0], points[end]);
    if (dist > maxDist) {
      maxDist = dist;
      splitIndex = i;
    }
  }
  if (maxDist > epsilon) {
    const left = douglasPeucker(points.slice(0, splitIndex + 1), epsilon);
    const right = douglasPeucker(points.slice(splitIndex), epsilon);
    // splitIndex's point appears as the last of "left" and first of
    // "right" - drop the duplicate at the join.
    return [...left.slice(0, -1), ...right];
  }
  return [points[0], points[end]];
};

// Real shape-preserving simplification for the route shown on the map and
// every sticker/share card - replaces a previous version that kept every
// Nth point regardless of the route's actual shape, which could flatten a
// sharp turn just as aggressively as a straight stretch, meaning a shared
// route could visually misrepresent where someone actually turned. Douglas-
// Peucker doesn't take a target point count directly (it takes a tolerance,
// with no closed-form relationship to the resulting count), so a binary
// search finds a tolerance that lands at or under maxPoints - a real
// route's real corners survive; only genuinely redundant points on already-
// straight stretches get dropped.
const simplifyRoute = (route: { lat: number; lng: number }[], maxPoints: number): { lat: number; lng: number }[] => {
  if (route.length <= maxPoints) return route;

  let low = 0;
  let high = 1; // degrees - generously wide upper bound; real routes converge well under this
  let result = route;
  for (let iter = 0; iter < 20; iter++) {
    const mid = (low + high) / 2;
    result = douglasPeucker(route, mid);
    if (result.length > maxPoints) {
      low = mid;
    } else {
      high = mid;
    }
  }
  return result;
};

// Builds a Mapbox Static Images API URL rendering the given route as a
// glowing accent-colored path over Mapbox's own dark style, matching the
// app's dark theme rather than a generic default map look. Uses "auto"
// center/zoom so Mapbox itself fits the frame to the route's real bounding
// box with padding, rather than us having to compute that ourselves.
const buildRouteMapUrl = (route: { lat: number; lng: number }[], width: number, height: number): string | null => {
  if (!route || route.length < 2) return null;
  const simplified = simplifyRoute(route, 120);
  const coordinates = simplified.map((p) => [p.lng, p.lat]);
  const geojson = {
    type: "Feature",
    geometry: { type: "LineString", coordinates },
    properties: {},
  };
  const encodedGeojson = encodeURIComponent(JSON.stringify(geojson));
  const strokeColor = (COLORS.accent || "#22D3EE").replace("#", "");
  const dpr = typeof window !== "undefined" ? Math.min(window.devicePixelRatio || 1, 2) : 1;
  const retina = dpr > 1 ? "@2x" : "";
  // satellite-v9, not dark-v11: dark-v11 is a full vector map with real
  // street names, building outlines and place labels baked in - a genuine
  // privacy problem for a route someone shares (their exact street/home
  // area readable at a glance), on top of looking flat and grey. Satellite
  // imagery has no text labels of any kind, is much harder to pinpoint an
  // exact address from at a glance, and is inherently colorful (real
  // terrain, trees, water) instead of a bland vector style.
  //
  // Two overlays chained in the same path segment (Mapbox Static API
  // syntax: comma-separated path-WIDTH+COLOR-OPACITY(geojson) entries) -
  // a wider dark outline drawn first, then the accent-colored route on
  // top of it. A plain accent line alone can disappear against
  // similarly-colored terrain in satellite imagery; the dark outline
  // guarantees the route stays readable regardless of what's underneath.
  const overlays = [
    `path-7+000000-0.55(${encodedGeojson})`,
    `path-4+${strokeColor}-0.95(${encodedGeojson})`,
  ].join(",");
  return `https://api.mapbox.com/styles/v1/mapbox/satellite-v9/static/${overlays}/auto/${width}x${height}${retina}?padding=40&access_token=${MAPBOX_ACCESS_TOKEN}`;
};

// Synchronous, guaranteed-to-render fallback for a GPS route image -
// same technique as buildCourtIllustrationUrl below (a plain SVG data:
// URL), and following that same function's hard-won lesson: explicit
// width/height attributes on the <svg> tag itself, not just viewBox, or
// html2canvas mis-crops the exported sticker image (confirmed by a real
// side-by-side Instagram-export bug on the court illustrations). Used
// both as the initial placeholder while the real MapLibre+Esri snapshot
// is still loading, and as the permanent fallback if that snapshot
// generation ever fails or times out - so a resident is never shown a
// blank or broken map image, on a slow connection or otherwise.
// transparent=true drops the background rect entirely - the mode for a
// route-outline-only sticker meant to sit over the person's own photo,
// matching the "Transparent" sticker style real trackers offer.
const buildRouteFallbackSvgUrl = (
  route: { lat: number; lng: number }[],
  width: number,
  height: number,
  strokeColor: string,
  transparent: boolean = false
): string => {
  const simplified = simplifyRoute(route, 120);
  const lats = simplified.map((p) => p.lat);
  const lngs = simplified.map((p) => p.lng);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const latRange = maxLat - minLat || 1;
  const lngRange = maxLng - minLng || 1;
  const pad = Math.round(Math.min(width, height) * 0.1);
  const points = simplified.map((p) => {
    const x = pad + ((p.lng - minLng) / lngRange) * (width - pad * 2);
    const y = height - pad - ((p.lat - minLat) / latRange) * (height - pad * 2);
    return `${x},${y}`;
  }).join(" ");
  const bg = transparent ? "" : `<rect x="0" y="0" width="${width}" height="${height}" fill="${COLORS.card}"/>`;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
    ${bg}
    <polyline points="${points}" fill="none" stroke="#000000" stroke-opacity="0.8" stroke-width="11" stroke-linecap="round" stroke-linejoin="round"/>
    <polyline points="${points}" fill="none" stroke="${strokeColor}" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
};

// Real replacement for the old synchronous buildRouteMapUrl (Mapbox
// Static Images API). This has to be async - unlike a plain URL string,
// generating a MapLibre+Esri snapshot requires actually rendering a real
// (off-screen) map, waiting for its satellite tiles to load, then
// capturing the canvas - so this returns the fallback SVG immediately on
// mount, then swaps in the real satellite snapshot once it's ready.
// Every existing consumer (ShareableStatCard, StickerShareScreen, plain
// <img> displays) keeps working completely unchanged, since they only
// ever receive a plain image URL string either way - none of them need
// to know a live map was ever involved.
const useRouteMapSnapshot = (
  route: { lat: number; lng: number }[] | null | undefined,
  width: number,
  height: number,
  strokeColor?: string,
  transparent: boolean = false
): string | null => {
  const accentColor = strokeColor || ROUTE_LINE_COLOR;
  const [url, setUrl] = useState<string | null>(() =>
    route && route.length > 1 ? buildRouteFallbackSvgUrl(route, width, height, accentColor, transparent) : null
  );

  useEffect(() => {
    if (!route || route.length < 2) { setUrl(null); return; }
    setUrl(buildRouteFallbackSvgUrl(route, width, height, accentColor, transparent));
    if (transparent) return; // Transparent mode is always the plain SVG line - never worth a real tile fetch for a route meant to sit invisibly over someone's own photo.

    let cancelled = false;
    let hasLoaded = false;
    let mapInstance: any = null;
    const container = document.createElement("div");
    container.style.position = "fixed";
    container.style.left = "-9999px";
    container.style.top = "0";
    container.style.width = `${width}px`;
    container.style.height = `${height}px`;
    document.body.appendChild(container);

    const coordinates = route.map((p) => [p.lng, p.lat] as [number, number]);
    const lngs = coordinates.map((c) => c[0]);
    const lats = coordinates.map((c) => c[1]);
    const bounds: [[number, number], [number, number]] = [
      [Math.min(...lngs), Math.min(...lats)],
      [Math.max(...lngs), Math.max(...lats)],
    ];

    const cleanup = () => {
      if (mapInstance) mapInstance.remove();
      if (container.parentNode) container.parentNode.removeChild(container);
    };

    const fallbackTimer = setTimeout(() => {
      if (!cancelled && !hasLoaded) cleanup();
    }, 6000);

    (async () => {
      // Dynamic import, deferred until a real snapshot is actually
      // needed - see the top-of-file note on why maplibregl is never
      // statically imported.
      const [maplibregl] = await Promise.all([
        import("maplibre-gl"),
        import("maplibre-gl/dist/maplibre-gl.css"),
      ]);
      if (cancelled) return;

      const map = new maplibregl.Map({
        container,
        style: {
          version: 8,
          sources: {
            "esri-satellite": {
              type: "raster",
              tiles: [ESRI_WORLD_IMAGERY_TILE_URL],
              tileSize: 256,
              attribution: "Tiles © Esri",
            },
          },
          layers: [{ id: "esri-satellite", type: "raster", source: "esri-satellite" }],
        },
        interactive: false,
        attributionControl: false,
        preserveDrawingBuffer: true,
      });
      mapInstance = map;

      map.on("error", () => {
        if (!cancelled && !hasLoaded) {
          clearTimeout(fallbackTimer);
          cleanup();
        }
      });

      map.on("load", () => {
        if (cancelled) return;
        map.addSource("route-line", {
          type: "geojson",
          data: { type: "Feature", geometry: { type: "LineString", coordinates }, properties: {} },
        });
        map.addLayer({
          id: "route-outline", type: "line", source: "route-line",
          paint: { "line-color": "#000000", "line-width": 11, "line-opacity": 0.8 },
          layout: { "line-cap": "round", "line-join": "round" },
        });
        map.addLayer({
          id: "route-line-accent", type: "line", source: "route-line",
          paint: { "line-color": accentColor, "line-width": 7, "line-opacity": 1 },
          layout: { "line-cap": "round", "line-join": "round" },
        });
        map.fitBounds(bounds, { padding: Math.round(Math.min(width, height) * 0.1), animate: false });
        map.once("idle", () => {
          if (cancelled) return;
          hasLoaded = true;
          clearTimeout(fallbackTimer);
          try {
            const dataUrl = map.getCanvas().toDataURL("image/png");
            if (!cancelled) setUrl(dataUrl);
          } catch (e) {
            console.error("Route map snapshot capture failed:", e);
          }
          cleanup();
        });
      });
    })();

    return () => {
      cancelled = true;
      clearTimeout(fallbackTimer);
      cleanup();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [route, width, height, transparent]);

  return url;
};

// Opt-in city/country label for a route, using its first (start) point
// as the representative location - never shown by default, only when
// explicitly added to a share/sticker card. Fully offline
// (offline-geocode-city ships its own bundled dataset, no network
// request of any kind) - works identically on a fast connection or a
// slow one, and never sends anyone's real coordinates to any
// third-party service the way a live geocoding API would.
// Real bug found via real-device testing: a session reported a city
// roughly 25 miles from where the person actually was. Root cause - the
// very FIRST GPS fix in a tracking session often comes from fast WiFi/
// cell-tower triangulation, before real satellite GPS lock kicks in, and
// can report a falsely confident (small) accuracy value while still
// being geographically wrong by miles. The original version always used
// route[0] - literally the first point - which is exactly the point
// most likely to have this problem.
//
// Real fix: require genuine multi-point movement (route.length >= 2,
// not just one isolated fix - real movement across consistent points is
// a much stronger correctness signal than any single fix's self-reported
// number) AND pick whichever point has the BEST reported accuracy across
// the whole route, gated by a threshold far stricter than the general
// route-acceptance filter (20m here vs. 50m for GPS_ACCURACY_REJECT_METERS
// generally - location naming needs real confidence, not just "good
// enough to draw a line on a map"). If no point clears both bars, this
// returns null and the Location stat simply doesn't appear - the same
// "never show a confident-looking but possibly wrong number" principle
// already used for pace/distance on very short sessions.
const LOCATION_ACCURACY_REQUIRED_METERS = 20;

const getRouteLocationLabel = (route: { lat: number; lng: number; accuracy?: number }[] | null | undefined): string | null => {
  if (!route || route.length < 2) return null;
  try {
    const withAccuracy = route.filter((p) => typeof p.accuracy === "number" && p.accuracy! <= LOCATION_ACCURACY_REQUIRED_METERS);
    if (withAccuracy.length === 0) return null;
    const best = withAccuracy.reduce((a, b) => (a.accuracy! <= b.accuracy! ? a : b));
    const result = getNearestCity(best.lat, best.lng);
    if (!result?.cityName) return null;
    return `${result.cityName}, ${result.countryName}`;
  } catch (e) {
    return null;
  }
};

// Honest, v1 elevation gain - GPS-derived altitude, not barometric (see
// the top-of-file note near GPS_ALTITUDE_ACCURACY_REJECT_METERS: real
// barometric altitude requires native sensor access this web app
// doesn't have yet, a concrete planned upgrade for the native app
// phase). Only counts deltas between consecutive points that BOTH have
// a trusted altitude reading - a gap where altitude was rejected for
// one point doesn't propagate a bad delta on either side of it. A
// minimum per-step threshold filters raw GPS altitude jitter (which
// fluctuates meaningfully even standing still) from being counted as
// real elevation change. Returns null (not 0) when there's insufficient
// altitude data to compute anything meaningful - "no data" and "flat
// route" are genuinely different and shouldn't look the same.
const MIN_ELEVATION_DELTA_METERS = 1;

const computeElevationGainMeters = (route: { lat: number; lng: number; altitude?: number }[] | null | undefined): number | null => {
  if (!route || route.length < 2) return null;
  const withAltitude = route.filter((p) => typeof p.altitude === "number");
  if (withAltitude.length < 2) return null;

  let gain = 0;
  for (let i = 1; i < withAltitude.length; i++) {
    const delta = withAltitude[i].altitude! - withAltitude[i - 1].altitude!;
    if (delta > MIN_ELEVATION_DELTA_METERS) gain += delta;
  }
  return Math.round(gain);
};

// Real per-kilometer split breakdown - genuine GPS-segment math, not an
// estimate. Walks the route summing real haversine distance between
// consecutive points; the instant cumulative distance crosses each
// 1000m boundary, the exact crossing moment is linearly interpolated
// within that GPS segment (not just "whichever point happened to be
// closest"), giving a real per-km pace rather than a rough
// approximation. Only emits COMPLETE kilometers - a session that ran
// 3.4km correctly shows 3 splits, not a misleading partial 4th one.
const computeKilometerSplits = (route: { lat: number; lng: number; timestamp: number }[] | null | undefined): { km: number; paceSecondsPerKm: number }[] => {
  if (!route || route.length < 2) return [];
  const splits: { km: number; paceSecondsPerKm: number }[] = [];
  let cumulativeMeters = 0;
  let currentKmStartTimestamp = route[0].timestamp;
  let nextKmBoundary = 1000;

  for (let i = 1; i < route.length; i++) {
    const prev = route[i - 1];
    const curr = route[i];
    const segmentMeters = haversineDistanceMeters(prev.lat, prev.lng, curr.lat, curr.lng);
    const segmentTimeMs = curr.timestamp - prev.timestamp;

    if (segmentMeters > 0 && cumulativeMeters + segmentMeters >= nextKmBoundary) {
      const metersIntoSegment = nextKmBoundary - cumulativeMeters;
      const fraction = metersIntoSegment / segmentMeters;
      const boundaryTimestamp = prev.timestamp + segmentTimeMs * fraction;

      const splitSeconds = (boundaryTimestamp - currentKmStartTimestamp) / 1000;
      splits.push({ km: splits.length + 1, paceSecondsPerKm: splitSeconds });

      currentKmStartTimestamp = boundaryTimestamp;
      nextKmBoundary += 1000;
    }
    cumulativeMeters += segmentMeters;
  }

  return splits;
};

// Court/field illustrations for basketball, soccer, and padel - used in
// place of a real GPS route map for these court-confined sports, where a
// real map has nothing meaningful to show. Proportions are drawn from real
// regulation dimensions (NBA/FIBA basketball, IFAB soccer, FIP padel), not
// approximated from memory, so these read as genuinely accurate rather than
// a generic placeholder shape:
// - Basketball: half-court view (94x50ft full court; half-court view shown,
//   the standard convention for this kind of small illustration), 16ft-wide
//   free-throw lane, 12ft-diameter free-throw circle, three-point arc.
// - Soccer: full pitch (105x68m), 9.15m-radius center circle, 16.5x40.3m
//   penalty areas with 5.5m-deep goal areas nested inside, penalty arcs.
// - Padel: full court (20x10m), net, service lines 6.95m from net, center
//   service line - with a double-line perimeter specifically to suggest
//   the glass-wall enclosure that's padel's own distinctive visual feature,
//   the detail that keeps it from reading as a generic tennis court.
// Returned as a data: URL so it can be used as a plain <img src> exactly
// like buildRouteMapUrl's output, with no change needed anywhere it's used.
//
// Real bug found via a live sticker share (confirmed with side-by-side
// screenshots): every court SVG here only ever had a viewBox, no explicit
// width/height attributes. The live in-app screen (a normal browser
// render) displayed these correctly, full court visible - but the actual
// EXPORTED sticker file (captured via html2canvas) showed the court
// cropped to roughly 65% of its width once posted to Instagram. This is a
// known html2canvas limitation: it can't always reliably derive an SVG
// data-URI's intrinsic aspect ratio from viewBox alone when rasterizing,
// and falls back to a wrong assumed size - explicit width/height on every
// <svg> tag below removes that ambiguity entirely, for any consumer, not
// just the live DOM.
const buildCourtIllustrationUrl = (courtType: "basketball" | "soccer" | "padel" | "pickleball", accentColor: string): string => {
  // Bug fix: this previously pre-encoded "#" to "%23" here, then the WHOLE
  // svg string got passed through encodeURIComponent() again below, which
  // re-encoded that literal "%" into "%25" - mangling every color into
  // garbage the browser couldn't parse as CSS, so nothing rendered at all.
  // encodeURIComponent already handles "#" correctly on its own; no manual
  // pre-encoding needed.
  const stroke = accentColor;
  let svg = "";

  if (courtType === "basketball") {
    // Full court now (not half), traced from a real full-court reference:
    // both baskets, both keys with free-throw circles, both three-point
    // arcs, center line and center circle. ViewBox at 5px/ft (94x50ft).
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="470" height="250" viewBox="0 0 470 250">
      <rect x="5" y="5" width="460" height="240" fill="none" stroke="${stroke}" stroke-width="3"/>
      <line x1="235" y1="5" x2="235" y2="245" stroke="${stroke}" stroke-width="3"/>
      <circle cx="235" cy="125" r="30" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="5" y="85" width="95" height="80" fill="none" stroke="${stroke}" stroke-width="3"/>
      <circle cx="100" cy="125" r="30" fill="none" stroke="${stroke}" stroke-width="3"/>
      <path d="M 15 5 A 120 120 0 0 1 15 245" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="370" y="85" width="95" height="80" fill="none" stroke="${stroke}" stroke-width="3"/>
      <circle cx="370" cy="125" r="30" fill="none" stroke="${stroke}" stroke-width="3"/>
      <path d="M 455 5 A 120 120 0 0 0 455 245" fill="none" stroke="${stroke}" stroke-width="3"/>
    </svg>`;
  } else if (courtType === "soccer") {
    // ViewBox scaled from 105x68m at 5px/m. Added corner arcs and goal
    // frames poking outside the end lines, traced from a real reference -
    // both were missing before despite being immediately recognizable
    // details on any real pitch diagram.
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="525" height="340" viewBox="0 0 525 340">
      <rect x="10" y="10" width="505" height="320" fill="none" stroke="${stroke}" stroke-width="3"/>
      <line x1="262.5" y1="10" x2="262.5" y2="330" stroke="${stroke}" stroke-width="3"/>
      <circle cx="262.5" cy="170" r="46" fill="none" stroke="${stroke}" stroke-width="3"/>
      <circle cx="262.5" cy="170" r="3" fill="${stroke}"/>
      <rect x="10" y="87" width="82" height="166" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="10" y="142" width="27" height="56" fill="none" stroke="${stroke}" stroke-width="3"/>
      <path d="M 92 122 A 46 46 0 0 1 92 218" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="433" y="87" width="82" height="166" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="488" y="142" width="27" height="56" fill="none" stroke="${stroke}" stroke-width="3"/>
      <path d="M 433 122 A 46 46 0 0 0 433 218" fill="none" stroke="${stroke}" stroke-width="3"/>
      <path d="M 10 18 A 8 8 0 0 1 18 10" fill="none" stroke="${stroke}" stroke-width="2"/>
      <path d="M 10 322 A 8 8 0 0 0 18 330" fill="none" stroke="${stroke}" stroke-width="2"/>
      <path d="M 515 18 A 8 8 0 0 0 507 10" fill="none" stroke="${stroke}" stroke-width="2"/>
      <path d="M 515 322 A 8 8 0 0 1 507 330" fill="none" stroke="${stroke}" stroke-width="2"/>
      <rect x="2" y="150" width="8" height="40" fill="none" stroke="${stroke}" stroke-width="1.5"/>
      <rect x="515" y="150" width="8" height="40" fill="none" stroke="${stroke}" stroke-width="1.5"/>
    </svg>`;
  } else if (courtType === "pickleball") {
    // Real regulation dimensions (USA Pickleball official rules), traced
    // from Senz's own reference diagram, not approximated: 44x20ft court
    // at 5px/ft (220x100). Net runs down the center (vertical line here,
    // with small post-mark ticks extending past the court's top/bottom
    // edges). A 7ft non-volley zone ("kitchen") sits on each side of the
    // net - shown as the shaded band flanking the centerline, spanning
    // the full court height, with NO dividing line through it (matching
    // real rules - the kitchen itself is never split). The remaining
    // 15ft-deep area on each side of the kitchen is split by a center
    // service line, but that line only spans the outer zones, stopping
    // exactly at the kitchen boundary rather than crossing into it.
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="230" height="110" viewBox="0 0 230 110">
      <rect x="5" y="5" width="220" height="100" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="80" y="5" width="70" height="100" fill="${stroke}" opacity="0.25"/>
      <line x1="115" y1="-2" x2="115" y2="5" stroke="${stroke}" stroke-width="3"/>
      <line x1="115" y1="105" x2="115" y2="112" stroke="${stroke}" stroke-width="3"/>
      <line x1="115" y1="5" x2="115" y2="105" stroke="${stroke}" stroke-width="2.5"/>
      <line x1="5" y1="55" x2="80" y2="55" stroke="${stroke}" stroke-width="2"/>
      <line x1="150" y1="55" x2="225" y2="55" stroke="${stroke}" stroke-width="2"/>
    </svg>`;
  } else {
    // Padel - rebuilt from Senz's own reference diagram: open end-zones
    // at each short end (no internal lines - just the back wall area),
    // a dashed center line running the full court height (the net, dashed
    // per Senz's request), and symmetric service lines above/below the
    // net within the two main playing zones only.
    svg = `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="200" viewBox="0 0 400 200">
      <rect x="6" y="6" width="388" height="188" fill="none" stroke="${stroke}" stroke-width="3"/>
      <rect x="12" y="12" width="376" height="176" fill="none" stroke="${stroke}" stroke-width="1.5" opacity="0.5"/>
      <line x1="70" y1="6" x2="70" y2="194" stroke="${stroke}" stroke-width="2"/>
      <line x1="330" y1="6" x2="330" y2="194" stroke="${stroke}" stroke-width="2"/>
      <line x1="200" y1="6" x2="200" y2="194" stroke="${stroke}" stroke-width="3" stroke-dasharray="8 6"/>
      <line x1="70" y1="72" x2="330" y2="72" stroke="${stroke}" stroke-width="2"/>
      <line x1="70" y1="128" x2="330" y2="128" stroke="${stroke}" stroke-width="2"/>
    </svg>`;
  }

  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
};

// A GPS fix with an uncertainty radius wider than this is rejected
// outright, before it ever reaches the route array or the distance total -
// a poor fix (tall buildings, dense tree cover, just-acquired signal) can
// report accuracy of 100m+, meaning the true position could genuinely be
// anywhere within that radius. Deliberately generous - real GPS under open
// sky is typically 5-15m - so this only discards fixes that are genuinely
// unreliable, not merely imperfect.
const GPS_ACCURACY_REJECT_METERS = 50;
// Browsers commonly report altitude with much worse confidence than
// horizontal position - phone GPS chips are inherently weaker at
// vertical accuracy than horizontal. A fix whose altitudeAccuracy
// exceeds this is treated as having NO altitude for that point (lat/lng
// still captured normally) rather than trusting a likely-garbage value.
const GPS_ALTITUDE_ACCURACY_REJECT_METERS = 25;

// A GPS fix implying faster than this is almost certainly a bad reading
// (satellite jump, urban canyon reflection) rather than real movement -
// discarded entirely rather than added to the distance total or the route,
// since a single bad jump can otherwise add hundreds of meters of phantom
// distance and show up as a visible teleport on a shared map.
//
// Activity-aware rather than one flat number: outdoor cycling needs real
// headroom for legitimate high speed - a pro-level descent can genuinely
// approach 100+ km/h, which the old flat 45 km/h ceiling would have
// wrongly discarded as implausible, silently undercounting a real ride's
// distance. Every other activity keeps the tighter 45 km/h ceiling, since
// no human being covering ground on foot can approach that regardless of
// skill level - a reading above it there is virtually certain to be a bad
// GPS fix, not a fast athlete.
const getMaxPlausibleSpeedMps = (activityType: string | null): number => {
  if (activityType === "bike") return 36.1; // ~130 km/h - comfortable headroom above even an extreme pro descent
  return 12.5; // ~45 km/h - well above realistic run/walk/hike speed
};

// Custom icons for sports lucide genuinely doesn't have (verified by
// listing its full icon set, not assumed) - drawn in the same stroke-based,
// 24x24-viewbox, round-cap style as lucide's own icons so they sit
// naturally in the same grid, rather than settling for a mismatched
// built-in substitute (a volleyball standing in for a basketball, a
// sailboat for a rowing machine). Shapes checked against real reference
// images before drawing, not approximated from memory alone.
type IconProps = { size?: number; color?: string; strokeWidth?: number };

